// thimble-term's one way to thimble's data: the `thimble` command, with no server and no port.
//
//   readState(surface, args)   `thimble state <surface> --cwd <dir> [args]`, which prints the JSON the server's GET route
//                              for that surface gives the browser; `{error}` and exit 1 when it fails
//   act(kind, payload)         `thimble act <kind> --cwd <dir> <json>`, which calls what the browser's POST route calls
//                              and prints `{ok, …}`; actLong the same for an act that runs until a label's run ends
//
// The renderer keeps no data of its own: what these print is drawn, and read again when the workspace changes. To see
// that it changed without starting Python, `signature` lists the workspace's folders (names, sizes and times only).
//
// The scope: thimble-term draws only in a session the `thimble` command started in terminal mode, which puts the
// workspace folder in THIMBLE_WS and writes `mode: "terminal"` in its trusted/launch.json. Anywhere else it is idle.
import type { Ctx } from './ctx'

/** Where this session's thimble lives: its workspace folder, the corpus folder, the command and the environment each
 *  call carries. */
export type Scope = { ws: string; cwd: string; bin: string; env: Record<string, string> }

export type Got<T = unknown> = { ok: true; value: T } | { ok: false; error: string }

const STATE_TIMEOUT_MS = 60_000
const ACT_TIMEOUT_MS = 60_000

/** The `thimble` command beside this plugin in thimble's tree (`<tree>/mods/thimble-term` → `<tree>/plugin/bin/thimble`),
 *  or the one THIMBLE_TERM_CLI names (the tests' and the live check's stand-in). */
export function cliOf(root: string, override: string | undefined): string {
  if (override) return override
  const dir = root.replace(/\/+$/, '').replace(/\/\.claude-plugin$/, '')
  return `${dir.replace(/\/mods\/[^/]+$/, '')}/plugin/bin/thimble`
}

/** launch.json's mode, or '' when it names none or cannot be read. */
export function launchMode(raw: string): string {
  try {
    const v = JSON.parse(raw) as { mode?: unknown }
    return typeof v?.mode === 'string' ? v.mode : ''
  } catch {
    return ''
  }
}

/** This session's scope when it runs in terminal mode, else null (thimble-term stays idle). */
export async function scopeOf(cx: Ctx): Promise<Scope | null> {
  const ws = ((await cx.env('THIMBLE_WS').catch(() => undefined)) ?? '').replace(/\/+$/, '')
  if (!ws) return null
  const raw = await cx.read(`${ws}/trusted/launch.json`).catch(() => '')
  if (launchMode(raw) !== 'terminal') return null
  const cwd = await cx.root()
  const bin = cliOf(cx.pluginRoot, (await cx.env('THIMBLE_TERM_CLI').catch(() => undefined)) || undefined)
  const env: Record<string, string> = { THIMBLE_WS: ws, THIMBLE_MODE: 'terminal' }
  for (const k of ['THIMBLE_HOME', 'THIMBLE_PORT', 'THIMBLE_UI_PORT']) {
    const v = await cx.env(k).catch(() => undefined)
    if (v) env[k] = v
  }
  return { ws, cwd, bin, env }
}

/** What a run printed, as JSON: its value when it exited 0 and printed JSON without an `error` key, else why not. */
export function parsePrinted(r: { exitCode: number; stdout: string; stderr: string }): Got {
  const out = r.stdout.trim()
  let v: unknown
  try {
    v = out ? JSON.parse(out) : undefined
  } catch {
    v = undefined
  }
  const err = v && typeof v === 'object' && !Array.isArray(v) && typeof (v as { error?: unknown }).error === 'string' ? (v as { error: string }).error : ''
  if (r.exitCode !== 0 || err || v === undefined) {
    const why = err || r.stderr.trim().split('\n').filter(Boolean).at(-1) || (out ? 'it printed no JSON' : 'it printed nothing')
    return { ok: false, error: why.slice(0, 300) }
  }
  return { ok: true, value: v }
}

export async function readState<T = unknown>(cx: Ctx, sc: Scope, surface: string, args: readonly string[] = []): Promise<Got<T>> {
  try {
    const r = await cx.run([sc.bin, 'state', surface, '--cwd', sc.cwd, ...args], { cwd: sc.cwd, env: sc.env, timeoutMs: STATE_TIMEOUT_MS })
    return parsePrinted(r) as Got<T>
  } catch (err) {
    return { ok: false, error: String(err).slice(0, 300) }
  }
}

export async function act<T = Record<string, unknown>>(cx: Ctx, sc: Scope, kind: string, payload: Record<string, unknown>): Promise<Got<T>> {
  try {
    const r = await cx.run([sc.bin, 'act', kind, '--cwd', sc.cwd, JSON.stringify(payload)], { cwd: sc.cwd, env: sc.env, timeoutMs: ACT_TIMEOUT_MS })
    const got = parsePrinted(r)
    if (got.ok && (got.value as { ok?: unknown })?.ok === false) return { ok: false, error: String((got.value as { error?: unknown }).error ?? 'refused') }
    return got as Got<T>
  } catch (err) {
    return { ok: false, error: String(err).slice(0, 300) }
  }
}

/** An act that may run longer than a run allows (`label-run` on every record): started beside the session, which it ends
 *  with, its answer read once it exits. */
export async function actLong<T = Record<string, unknown>>(cx: Ctx, sc: Scope, kind: string, payload: Record<string, unknown>): Promise<Got<T>> {
  try {
    const r = await cx.runLong([sc.bin, 'act', kind, '--cwd', sc.cwd, JSON.stringify(payload)], { cwd: sc.cwd, env: sc.env })
    const got = parsePrinted(r)
    if (got.ok && (got.value as { ok?: unknown })?.ok === false) return { ok: false, error: String((got.value as { error?: unknown }).error ?? 'refused') }
    return got as Got<T>
  } catch (err) {
    return { ok: false, error: String(err).slice(0, 300) }
  }
}

// ------------------------------------------------------------------------------------------------ what changed

/** The parts of a workspace a surface reads, each with the folders whose listing says it changed: a folder whole, or
 *  the entries of it that `names` lists. Only listings: a file that is not there yet costs no failed call. */
export const AREAS = {
  cards: [{ dir: 'notebooks' }],
  labels: [{ dir: 'concepts' }, { dir: 'labels' }],
  // a document, and a report check made, changed or run on one (report.ts reads its name and its runs)
  docs: [{ dir: 'investigations/main' }, { dir: 'checks' }],
  chats: [{ dir: 'chats' }],
  agents: [{ dir: 'trusted', names: ['subagents.json', 'module.json'] }, { dir: 'orient', names: ['run.json'] }],
  // a view built (its folder in the local extension) or proposed (proposals.json)
  views: [{ dir: 'extension/views' }, { dir: 'views', names: ['proposals.json'] }],
  ui: [{ dir: '', names: ['ui.jsonl'] }],
} as const satisfies Record<string, readonly { dir: string; names?: readonly string[] }[]>

export type Area = keyof typeof AREAS
export type Signature = Record<Area, string>

async function stamp(cx: Ctx, path: string, names?: readonly string[]): Promise<string> {
  try {
    const entries = await cx.list(path)
    // a file's size and time, a folder's name: what an edit, an add or a remove changes
    return entries
      .filter(e => !names || names.includes(e.name))
      .map(e => `${e.name}:${e.kind === 'file' ? `${e.size}:${e.mtimeMs}` : e.kind}`)
      .sort()
      .join('|')
  } catch {
    return '-'
  }
}

/** One stamp per area: a change of any file it reads changes it. Each folder is listed once a pass. */
export async function signature(cx: Ctx, sc: Scope): Promise<Signature> {
  const out = {} as Signature
  const listed = new Map<string, Promise<string>>()
  for (const area of Object.keys(AREAS) as Area[]) {
    const parts: string[] = []
    for (const spec of AREAS[area] as readonly { dir: string; names?: readonly string[] }[]) {
      const key = `${spec.dir}|${(spec.names ?? []).join(',')}`
      if (!listed.has(key)) listed.set(key, stamp(cx, spec.dir ? `${sc.ws}/${spec.dir}` : sc.ws, spec.names))
      parts.push(await listed.get(key)!)
    }
    out[area] = parts.join('#')
  }
  return out
}

/** The areas whose stamp differs between two signatures (every area when there was none before). */
export function changed(before: Signature | null, now: Signature): Area[] {
  return (Object.keys(now) as Area[]).filter(a => !before || before[a] !== now[a])
}

files.hooks/gestures.tsx:
// One set of gestures for every target a Client of the mod draws (a card, a mark, a row, a record, a node):
//
//   click            the target's one action: open the place it cites, or a side thread about a card
//   double-click     the same as a click
//   right-click      the same as a click: there is no menu
//
// Modifier clicks and the middle button are left alone: terminals keep them for their own selection, and a gesture
// that works in one terminal and not the next is worse than none. A reply's paragraphs are the engine's Markdown, each
// citation a link a plain click presses (register.tsx), so their text selects as usual.
//
// A Client calls onPointer from its pointer listener with the target under the pointer; the gesture is posted to the
// hooks module (register.tsx), which acts on it.
import type { ClientModule, ClientPointerEvent, JsonValue } from 'claude-code'

import type { ChatTarget } from '../types'
import { chipName, citeLabel, plainCites } from './cite'
import { citations, cut, isChip, quoted } from './lib'
import type { Citation } from './lib'

export type Target = ChatTarget

export type PointerEv = { button: 'left' | 'middle' | 'right'; shift: boolean; ctrl: boolean; alt: boolean; type: 'press' | 'release' | 'double' }

/** A click's (a right-click does what a click does). */
export type Gesture = 'primary'

/** One pointer event as posted: what it was, which gesture it made (null: none), and on what. */
export type Sent = { seq: number; gesture: Gesture | null; target: Target; ev: PointerEv }

type Port = { post: (data: JsonValue) => void; every?: (ms: number, fn: () => void) => () => void }

const origin = Math.random().toString(36).slice(2, 10)
let seq = 0
let outbox: Sent[] = []
let rightDown = false // a right press reached this module and its release has not

function portOf(ctx: unknown): Port | null {
  const c = ctx as { post?: unknown; surface?: unknown } | null
  if (c && typeof c.post === 'function') return c as Port
  if (c && c.surface) return portOf(c.surface)
  return null
}

/** A Client's raw event (down/up) or an event already in this module's terms; null for moves and edges. */
export function normalize(ev: PointerEv | ClientPointerEvent): PointerEv | null {
  const t = ev.type === 'down' ? 'press' : ev.type === 'up' ? 'release' : ev.type
  if (t !== 'press' && t !== 'release' && t !== 'double') return null
  return { type: t, button: ev.button ?? 'left', shift: Boolean(ev.shift), ctrl: Boolean(ev.ctrl), alt: Boolean(ev.alt) }
}

/** The gesture a press makes: a left or right press (once or twice) its one action; the rest none (a modified click
 *  and the middle button are the terminal's). */
export function classify(ev: PointerEv): Gesture | null {
  if (ev.type === 'double') return 'primary'
  if (ev.type !== 'press') return null
  return (ev.button === 'left' || ev.button === 'right') && !ev.shift && !ev.ctrl && !ev.alt ? 'primary' : null
}

export function targetKey(t: Target): string {
  return [t.kind, t.ref ?? '', t.cardId ?? '', (t.text ?? '').slice(0, 80)].join('|')
}

/** Every post carries what this module sent since the last frame, so a post that replaces another in the same frame
 *  (the engine delivers one per frame) loses no gesture; register.tsx drops the ones it has seen. */
function emit(port: Port, entry: Omit<Sent, 'seq'>): void {
  const mine = ++seq
  outbox = [...outbox, { ...entry, seq: mine }].slice(-8)
  port.post({ type: 'gesture', origin, gestures: outbox } as unknown as JsonValue)
  if (port.every) {
    const stop = port.every(120, () => {
      stop()
      outbox = outbox.filter(x => x.seq > mine)
    })
  }
}

/** A Client's other posts (a hover, a param) go through here, so they carry the gestures not yet delivered. */
export function send(ctx: unknown, data: Record<string, JsonValue>): void {
  const port = portOf(ctx)
  if (port) port.post({ ...data, origin, gestures: outbox } as unknown as JsonValue)
}

/** Called by a Client's pointer listener with the target under the pointer, on a press and on a release. `ctx` is the
 *  Client's surface (its `post`, and its `every` for the double-click window). */
export function onPointer(target: Target, ev: PointerEv | ClientPointerEvent, ctx: unknown): void {
  const port = portOf(ctx)
  const e = normalize(ev)
  if (!port || !e) return
  if (e.type === 'release') {
    // The press picks the target. The panel it opens can reflow the transcript before the release, which then lands
    // on another target; only a right release whose press never reached this module acts, as a click.
    const lost = e.button === 'right' && !rightDown && !e.shift && !e.ctrl && !e.alt
    if (e.button === 'right') rightDown = false
    emit(port, { gesture: lost ? 'primary' : null, target, ev: e })
    return
  }
  if (e.type === 'press' && e.button === 'right') rightDown = true
  emit(port, { gesture: classify(e), target, ev: e })
}

// ------------------------------------------------------------------------------------------------ what a target means

const CARD_REF = /^card:([A-Za-z0-9_-]+)/

/** The target's citation: a full `[[value|ref]]` in `ref`, `[[text|ref]]` for a mark or a row (its text is the value
 *  shown), or `[[ref]]` (a record's or a node's text is words about it, not a value). */
export function citationOf(t: Target): Citation | null {
  if (t.kind === 'card') return t.cardId ? { raw: `[[card:${t.cardId}]]`, ref: `card:${t.cardId}`, display: null } : null
  const ref = (t.ref ?? '').trim()
  if (!ref) return null
  if (ref.startsWith('[[')) return citations(ref)[0] ?? null
  const value = t.kind === 'mark' || t.kind === 'row' ? (t.text ?? '').trim() : ''
  return value && !/[|\[\]\n]/.test(value) ? { raw: `[[${value}|${ref}]]`, ref, display: value } : { raw: `[[${ref}]]`, ref, display: null }
}

export function cardOf(t: Target): string {
  return t.cardId || CARD_REF.exec(citationOf(t)?.ref ?? '')?.[1] || ''
}

/** What a double-click or "cite" puts into the prompt: the citation, or a sentence quoted. */
export function citeText(t: Target): string {
  const c = citationOf(t)
  if (c) return c.raw
  const s = (t.text ?? '').replace(/\s+/g, ' ').trim()
  return s ? quoted(cut(s, 300)) : ''
}

/** The place a click opens: a citation's; a mark's, row's, record's or node's when it lies outside the cards. Plain
 *  words (a sentence, a reply's table row) open nothing: only what is drawn as a link opens a panel. */
export function placeOf(t: Target): Citation | null {
  if (t.kind === 'card' || t.kind === 'sentence' || (t.kind === 'row' && !t.ref)) return null
  const c = citationOf(t)
  if (!c) return null
  return t.kind === 'citation' || !CARD_REF.test(c.ref) ? c : null
}

export type Act = 'open' | 'thread' | 'verify' | 'script' | 'rerun' | 'files'
/** A short name for the target in at most `max` characters, as the mouse log and a thread's title show it: each citation by
 *  its label, never its ref; quoted words keep their closing quote when cut. */
export function targetLabel(t: Target, max = 48): string {
  const s = plainCites(t.text ?? '')
    .replace(/[`*_]+|^\s*(#+|[-*+]|\d+[.)])\s+/g, '')
    .replace(/\s+/g, ' ')
    .trim()
  const n = Math.max(8, max)
  const c = citationOf(t)
  switch (t.kind) {
    case 'card':
      return s ? `card ${quoted(cut(s, n - 7))}` : 'card'
    case 'sentence':
      return s ? quoted(cut(s, n - 2)) : 'sentence'
    case 'citation':
      // a chip by its place in full words (`card "How many…"`, `events.jsonl line 12`): no tip names it here
      return cut(c ? (isChip(c) ? chipName(c) : citeLabel(c)) : 'citation', n)
    default:
      return cut(t.label || s || (c ? citeLabel(c) : t.kind), n)
  }
}

