// Pure helpers of thimble-term (no `$`), shared by the hooks module, the surface modules and the tests.
//
// - citations(text): the [[display|ref]] and [[ref]] citations of a reply, and the link form [display](ref).
// - parseReply(text): a reply block cut into Markdown chunks, card embeds (a line holding only [[card:<id>]]) and rich
//   blocks (a paragraph, list item, heading, quote or table that holds a citation), each rich block as inline runs.
// - shownMatches / valueIn: thimble's number comparison (backend/app/cite.py), for the verification script's result.
// - cut / clip / windowAt: the one cut of thimble-term, at a word; quoted: words in quotation marks of a kind they do
//   not hold; formatted: a table column's number format, as the browser's table writes it.

export type Citation = { raw: string; ref: string; display: string | null }

export type Run = { text: string; b?: boolean; i?: boolean; code?: boolean; u?: boolean; cite?: Citation }

/** `gap`: a blank line stood before the block in the reply, so it is drawn one row below the one before it. */
export type Block =
  | { type: 'md'; text: string; gap: boolean }
  | { type: 'card'; id: string; gap: boolean; caption?: string }
  | { type: 'rich'; prefix: string; heading: number; quote: boolean; runs: Run[]; gap: boolean; table?: TableRuns }

/** A Markdown table that holds citations, drawn by thimble-term (the `|` inside `[[value|ref]]` breaks a GFM table):
 *  its rows of cells of runs, the first row the header, and each column's alignment. A table block's `runs` are its
 *  cells' runs in reading order, so its chips are numbered as a paragraph's are. */
export type TableRuns = { rows: Run[][][]; align: ('left' | 'right' | 'center')[] }

const FENCE_RE = /```[\s\S]*?```|`[^`\n]*`/g
const LINK_RE = /(?<![\[!])\[([^\[\]\n]*)\]\(\s*(?:<([^<>\n]+)>|((?:[^()\s<>]|\([^()\s]*\))+))\s*\)/g
const WEB_RE = /^(?:[a-z][a-z0-9+.-]*:\/\/|mailto:|tel:)/i
const REF_SHAPE = /^(?:call:[A-Za-z0-9_-]+(?:#L\d+(?:-L?\d+)?)?|card:[A-Za-z0-9_-]+(?:@[A-Za-z0-9_]+)?(?:#.*)?|concept:[A-Za-z0-9_-]+(?:\/[^\s()]+)?|report:[A-Za-z0-9_-]+(?:#p?[A-Za-z0-9_-]+)?|[^\s:#]+#\S+|[^\s:#()]+\.[A-Za-z][A-Za-z0-9]{0,7})$/
const LABEL_REF = /^concept:([A-Za-z0-9_-]+)(?:\/(.+))?$/
const REPORT_REF = /^report:([A-Za-z0-9_-]+)(?:#(p?[A-Za-z0-9_-]+))?$/

/** A link to a document, or to one of its paragraphs (`p<id>`), sentences or headings (`report:<slug>#<unit>`): the
 *  document's slug and the unit; null for any other ref. */
export function reportRef(ref: string): { slug: string; unit: string } | null {
  const m = REPORT_REF.exec(ref.trim())
  return m ? { slug: m[1]!, unit: m[2] ?? '' } : null
}

// what names a label and a document's passage a reply links to without words, as their resolution (term.ts
// resolveCitations) and the lists read named them: a label's name by its id; a document's title by its slug and a
// passage's words by its ref
const labelNames = new Map<string, string>()
const docTitles = new Map<string, string>()
const passages = new Map<string, string>()

/** Whether thimble's agents list a running chat that follows a run of the label named `name` (a `labels` agent titled
 *  `label <name>`): a run the session's own process holds, which `thimble state` does not show as the label's run. */
export function labelRunning(agents: readonly { label: string; state: string; role: string }[], name: string): boolean {
  return Boolean(name) && agents.some(a => a.role === 'labels' && a.state === 'running' && a.label === `label ${name}`)
}

/** How a label's runs stand, as every place that names it says it (home, the labels list, its panel, its card; live
 *  check term-fix9, quirk 4: the list and the panel said `not run yet` while home said `◌ labeling`): `running` while a
 *  run goes on (thimble's, or main's that a chat follows: labelRunning), `ran` once a run ended, `stopped` for records
 *  labeled with no run that ended (a quit stopped its first run part way), `labeled` the records labeled so far, and
 *  `total` its run's size (the run's own, else the scope's size `thimble state` counted). */
export type LabelState = { running: boolean; ran: boolean; stopped: boolean; labeled: number; total: number | null }

type LabelRunLike = { status?: string; total?: number; matched_total?: number | null; stopped?: boolean; labeled?: number } | null | undefined

export function labelState(
  l: { name?: string; last_run?: LabelRunLike; applications?: LabelRunLike[]; label_stats?: { counts?: Record<string, number>; n_labeled?: number } | null; scope_total?: number },
  agents: readonly { label: string; state: string; role: string }[],
): LabelState {
  const last = l.last_run ?? l.applications?.at(-1) ?? null
  const running = (l.last_run?.status ?? '') === 'running' || labelRunning(agents, l.name ?? '')
  const labeled = l.label_stats?.n_labeled ?? Object.values(l.label_stats?.counts ?? {}).reduce((a, b) => a + b, 0)
  const total = typeof last?.matched_total === 'number' ? last.matched_total : typeof last?.total === 'number' ? last.total : typeof l.scope_total === 'number' ? l.scope_total : null
  return { running, ran: Boolean(last) && last?.status !== 'running', stopped: !running && !last && labeled > 0, labeled, total }
}

/** A label's state in words while it has no run that ended: `◌ labeling`, with the records labeled so far and of how
 *  many when known (`◌ labeling 3,000 of 4,579`); `stopped at 3,150 of 4,579`; `not run yet`. '' once a run ended. */
export function labelStateWords(st: LabelState): string {
  const n = (x: number) => x.toLocaleString('en-US')
  const of = st.total !== null && st.total >= st.labeled ? ` of ${n(st.total)}` : ''
  if (st.running) return st.labeled ? `◌ labeling ${n(st.labeled)}${of}` : '◌ labeling'
  if (st.ran) return ''
  return st.stopped ? `stopped at ${n(st.labeled)}${of}` : 'not run yet'
}

/** A label's name, noted when the labels are read or a link to it resolves, so a link to it names it in words. */
export function noteLabelName(id: string, name: string | undefined): void {
  if (id && name) labelNames.set(id, name)
}

/** A document's title (by its slug) and a passage's words (by its ref), noted when a link to it resolves or the documents
 *  are read, so a link to it names it in words. */
export function noteDocPlace(ref: string, title: string | undefined, words = ''): void {
  const r = reportRef(ref)
  if (!r) return
  if (title) docTitles.set(r.slug, title)
  if (r.unit && words.trim()) passages.set(`report:${r.slug}#${r.unit}`, words.replace(/\s+/g, ' ').trim())
}

/** The kinds of a thread's `error` record that end its run as a stop, not a failure: the analyst's stop, and the Claude
 *  Code session that ended under it (backend threads.SESSION_ENDED, as when the analyst quits). */
export const STOP_KINDS: readonly string[] = ['stopped', 'session-ended']

/** Whether a thread's turn ended as a stop, not a failure: its record said so (`stopped`), or its words do (live check
 *  term-fix6, new quirk 2: a thread stopped by quitting showed a red failure). */
export function stoppedTurn(t: { state: string; a: string; stopped?: boolean }): boolean {
  return t.state === 'error' && (Boolean(t.stopped) || /^\s*stopped\b/i.test(t.a))
}

/** A citation of a label, or of one of its values (`[[33|concept:<id>/yes]]`, or `[33](concept:<id>/yes)` as main writes
 *  it for the terminal): the label's id and the value; null for any other ref. It is a link that opens the label at the
 *  value, never a place a check reads. */
export function labelRef(ref: string): { id: string; value: string } | null {
  const m = LABEL_REF.exec(ref.trim())
  return m ? { id: m[1]!, value: m[2] ? decodeURIComponent(m[2]) : '' } : null
}
export const EMBED_RE = /^\s*(?:\[\[card:([A-Za-z0-9_-]+)\]\]|!\[[^\]\n]*\]\(card:([A-Za-z0-9_-]+)\))\s*$/

function make(display: string | null, ref: string): Citation {
  return { raw: display === null ? `[[${ref}]]` : `[[${display}|${ref}]]`, ref, display }
}

function spanCitation(inner: string): Citation | null {
  const t = inner.trim()
  const bar = t.lastIndexOf('|')
  const display = bar >= 0 ? t.slice(0, bar).trim() : null
  const ref = (bar >= 0 ? t.slice(bar + 1) : t).trim()
  return ref ? make(display, ref) : null
}

const CITE_MAX = 2000 // characters a citation may span, so a stray [[ costs little

/** Where the citation that opens with the `[[` at `at` ends (just past its `]]`), or -1 when none opens there. A shown
 *  value may hold brackets, as a quoted line of code or JSON does (`[["counts[\"dse\"] += 1"|call:x#L2]]`); the place
 *  after its last bar holds no bracket. The citation ends at the first `]]` that closes such a place, provided the value
 *  before the bar holds `[[` only inside balanced brackets (a quoted JSON list). One that holds a bracket lies on one
 *  line, and none runs past a blank line, so code in prose is not taken for a citation. */
export function citeEnd(text: string, at: number): number {
  if (!text.startsWith('[[', at)) return -1
  const stop = Math.min(text.length, at + CITE_MAX)
  // the place since the last bar (all of it, with no bar): whether it holds a bracket, and whether any words
  let placeBracket = false
  let placeWords = false
  // the value so far, and as it stood at the last bar
  let depth = 0
  let unbalanced = false
  let double = false
  let valueOk = true
  let bracket = false
  let lined = false
  for (let k = at + 2; k < stop; k++) {
    const ch = text[k]!
    if (ch === ']' && text[k + 1] === ']' && !placeBracket && placeWords && valueOk) return k + 2
    if (ch === '|') {
      valueOk = !double || (depth === 0 && !unbalanced)
      placeBracket = false
      placeWords = false
    } else if (ch === '[' || ch === ']') {
      if (lined) return -1
      bracket = placeBracket = true
      if (ch === '[' && k > at + 2 && text[k - 1] === '[') double = true
      depth += ch === '[' ? 1 : -1
      if (depth < 0) unbalanced = true
    } else if (ch === '\n') {
      if (bracket) return -1
      lined = true
      let j = k + 1
      while (text[j] === ' ' || text[j] === '\t') j++
      if (text[j] === '\n') return -1
    } else if (ch !== ' ' && ch !== '\t') placeWords = true
  }
  return -1
}

/** Each `[[...]]` citation of a text as written, where it starts and where it ends, in order. */
export function citeSpans(text: string): { at: number; end: number }[] {
  const out: { at: number; end: number }[] = []
  for (let i = text.indexOf('[['); i >= 0; ) {
    const end = citeEnd(text, i)
    if (end >= 0) out.push({ at: i, end })
    i = text.indexOf('[[', end >= 0 ? end : i + 1)
  }
  return out
}

function linkCitation(shown: string, target: string): Citation | null {
  // a file's place with its spaces encoded (`my%20file.md#L3`) as the file names it; a label's value keeps its encoding,
  // which labelRef decodes (`concept:<id>/mentions%20June`: live check term-fix9, it drew as its raw words)
  const raw = target.trim()
  const ref = raw.startsWith('concept:') ? raw : raw.replaceAll('%20', ' ')
  if (!ref || WEB_RE.test(ref) || shown.includes('|') || !REF_SHAPE.test(ref)) return null
  const s = shown.trim()
  return make(s === '' || s === '↗' ? null : s, ref)
}

/** Every citation of a text in order, deduplicated by its `[[...]]` spelling; code spans and fences left out. */
export function citations(text: string): Citation[] {
  const found: { at: number; c: Citation }[] = []
  const clean = text.replace(FENCE_RE, m => ' '.repeat(m.length))
  for (const sp of citeSpans(clean)) {
    const c = spanCitation(text.slice(sp.at + 2, sp.end - 2))
    if (c) found.push({ at: sp.at, c })
  }
  for (const m of clean.matchAll(LINK_RE)) {
    const c = linkCitation(m[1]!, m[2] ?? m[3] ?? '')
    if (c) found.push({ at: m.index ?? 0, c })
  }
  const seen = new Set<string>()
  return found
    .sort((a, b) => a.at - b.at)
    .map(f => f.c)
    .filter(c => !seen.has(c.raw) && Boolean(seen.add(c.raw)))
}

/** A text with each Markdown link that is a citation (`[4,579](README.md#L3)`, the form main writes for the terminal)
 *  in its `[[…]]` spelling (`[[4,579|README.md#L3]]`); a web link stays as written. */
export function linksAsSpans(text: string): string {
  return text.replace(LINK_RE, (m: string, shown: string, a?: string, b?: string) => linkCitation(shown, a ?? b ?? '')?.raw ?? m)
}

/** A text with each Markdown link that is a citation (`[4,579](README.md#L3)`, the form main writes for the terminal)
 *  as its shown words; a web link stays as written. */
export function plainLinks(text: string): string {
  return text.replace(LINK_RE, (m: string, shown: string, a?: string, b?: string) => {
    const c = linkCitation(shown, a ?? b ?? '')
    return c ? (c.display ?? chipLabel(c)) : m
  })
}

/** A short stable id for a citation (FNV-1a of its raw spelling), the key of its state. */
export function cid(raw: string): string {
  let h = 0x811c9dc5
  for (let i = 0; i < raw.length; i++) {
    h ^= raw.charCodeAt(i)
    h = Math.imul(h, 0x01000193) >>> 0
  }
  return h.toString(36)
}

// the cards' questions read so far, by id (term.ts loadCards notes each): what names a card a reply cites without words
const questions = new Map<string, string>()

/** A card's question, noted when the card is read, so a citation of the card without words names it by its question. */
export function noteQuestion(id: string, question: string | undefined): void {
  if (!question) return
  questions.delete(id)
  questions.set(id, question)
  if (questions.size > 2000) questions.delete(questions.keys().next().value!)
}

/** A card's question as noted (noteQuestion); '' for a card not read yet. */
export function questionOf(id: string): string {
  return questions.get(id) ?? ''
}

/** The card a citation names whole, with no words and no place on it (`[[card:<id>]]`, as a sentence ends with it), or
 *  ''. */
export function bareCard(c: Citation): string {
  return c.display === null ? (/^(?:card|cell):([A-Za-z0-9_-]+)$/.exec(c.ref)?.[1] ?? '') : ''
}

/** A card named by its question in words: `card “<question>”`, the question cut at a word; `a card` while it is not
 *  read. */
export function cardWords(question: string, n = 40): string {
  return question.trim() ? `card ${quoted(clip(question, n))}` : 'a card'
}

/** A citation of lines a card printed (`card:<id>@out0#L1`): the card, the lines, and the place in words, `card "…"
 *  output line 1` (`a card's output line 1` while the card is not read); null for any other ref. */
export function outputLine(ref: string): { card: string; first: number; last: number; words: string } | null {
  const m = /^(?:card|cell):([A-Za-z0-9_-]+)@out\d+#L(\d+)(?:-L?(\d+))?$/.exec(ref.trim())
  if (!m) return null
  const [first, last] = [Number(m[2]), Number(m[3] ?? m[2])]
  const lines = last !== first ? `lines ${first}-${last}` : `line ${first}`
  const q = questionOf(m[1]!)
  return { card: m[1]!, first, last, words: q ? `${cardWords(q)} output ${lines}` : `a card's output ${lines}` }
}

/** A chip: a citation that names only its place, with no words of its own (`[[card:<id>]]`, `[↗](<ref>)`), which the
 *  browser draws as a chip; its own kind of citation (Matt, 2026-10-07). Every surface draws it as `[ card ]`
 *  (chipText), never as words of the sentence. */
export function isChip(c: Citation): boolean {
  return c.display === null
}

/** The most cells a chip's words take, its brackets aside. */
export const CHIP_MAX = 30

/** What a chip says inside its brackets, short (Matt, 2026-10-07): `card` for a card or one of its cells, `card output
 *  line 1` for a line it printed, `events.jsonl line 12` for a file's line (its name cut in its middle, the line kept),
 *  a label by its name (`edit purpose`, `edit purpose · yes` for a value), `report`, `slides` or `story` for a document
 *  or a passage of one, `output line 1` for a command's output. Never an id. */
export function chipWords(c: Citation): string {
  // a label's link and a document's by their names, never their ids (live check term-fix8, quirk 3: `concept:eb534ca4`
  // and `↗ (report:report#4255ef27)` showed in a reply)
  const lr = labelRef(c.ref)
  if (lr) {
    const name = labelNames.get(lr.id)
    const value = lr.value ? ` · ${lr.value}` : ''
    return name ? `${cut(name, Math.max(8, CHIP_MAX - width(value)))}${value}` : `label${value}`
  }
  const rr = reportRef(c.ref)
  if (rr) return rr.slug === 'slides' || rr.slug === 'story' ? rr.slug : 'report'
  const [base = '', frag = ''] = c.ref.split('#', 2)
  const out = outputLine(c.ref)
  if (out) return out.last !== out.first ? `card output lines ${out.first}-${out.last}` : `card output line ${out.first}`
  if (/^(?:card|cell):/.test(base)) return 'card'
  if (base.startsWith('call:')) {
    const call = /^L(\d+)(?:-L?(\d+))?$/.exec(frag)
    return call ? (call[2] && call[2] !== call[1] ? `output lines ${call[1]}-${call[2]}` : `output line ${call[1]}`) : 'output'
  }
  // a file's place in words, its name as written (`events.jsonl line 12`, `agent-chat.jsonl lines 1-2`), never
  // `events:1063`, which reads as an id (live check term-fix9, low quirk); a long name cut in its middle, its line kept
  const name = base.split('/').at(-1) ?? base
  const lines = /^L(\d+)(?:-L?(\d+)|\.b\d+(?::c\d+-\d+)?)?$/.exec(frag)
  const row = /^row=(\d+)$/.exec(frag)
  const page = /^p(\d+)$/.exec(frag)
  // a JSON list's item, counted from 1 as the file's view counts them (draw.ts placeWords)
  const item = /^\/(?:[^/]+\/)?(\d+)$/.exec(frag)
  const where = lines ? (lines[2] && lines[2] !== lines[1] ? ` lines ${lines[1]}-${lines[2]}` : ` line ${lines[1]}`) : row ? ` row ${row[1]}` : page ? ` page ${page[1]}` : item ? ` item ${Number(item[1]) + 1}` : frag ? ` ${frag}` : ''
  if (width(`${name}${where}`) <= CHIP_MAX) return `${name}${where}`
  const room = CHIP_MAX - width(where)
  return room >= 8 ? `${middleCut(name, room)}${where}` : cut(`${name}${where}`, CHIP_MAX)
}

/** A short name cut in its middle to `n` cells, its extension kept (`revis…ns.jsonl`); a longer title at its end. */
export function middleCut(name: string, n: number): string {
  if (width(name) <= n) return name
  if (name.split(/\s+/).length > 3 || n < 8) return cut(name, n)
  const dot = name.lastIndexOf('.')
  const ext = dot > 0 && name.length - dot <= 8 ? name.slice(dot) : ''
  const stem = ext ? name.slice(0, dot) : name
  const room = n - width(ext) - 1
  if (room < 4) return cut(name, n)
  const head = Math.ceil(room / 2)
  return `${stem.slice(0, head)}…${stem.slice(stem.length - (room - head))}${ext}`
}

/** A chip as every surface draws it: its words in brackets, a space inside each (`[ card ]`). */
export function chipText(c: Citation): string {
  return `[ ${chipWords(c)} ]`
}

/** What a citation's link says: the shown value, cut at a word, or a chip (chipText) for a citation without one. */
export function chipLabel(c: Citation): string {
  return c.display !== null ? clip(c.display, 40) : chipText(c)
}

/** A chip's place in full words, for its tip: a label by its name, a document by its title or a passage by its words,
 *  as they were noted (noteLabelName, noteDocPlace); '' for any other place, which the caller names. */
export function chipPlace(c: Citation): string {
  const lr = labelRef(c.ref)
  if (lr) {
    const name = labelNames.get(lr.id)
    return name ? `label ${quoted(clip(name, 40))}${lr.value ? ` at its value ${quoted(lr.value)}` : ''}` : ''
  }
  const rr = reportRef(c.ref)
  if (rr) {
    const kind = rr.slug === 'slides' || rr.slug === 'story' ? rr.slug : 'report'
    const words = rr.unit ? passages.get(`report:${rr.slug}#${rr.unit}`) : ''
    if (words) return `${kind} ${quoted(clip(words, 60))}`
    const title = docTitles.get(rr.slug)
    return title ? `${kind} ${quoted(clip(title, 60))}` : `the ${kind}`
  }
  return ''
}

/** A text's chips with the brackets main put around one of its own taken away (`([[card:<id>]])` reads `[ card ]`, never
 *  `([ card ])`): a chip carries its own brackets. */
export function withoutOwnParens(text: string): string {
  return text.replace(/\(\s*(\[\[[^\[\]\n|]+\]\]|\[\s*↗?\s*\]\([^()\s]+\))\s*\)/g, (m, inner: string) => {
    const c = citations(inner)[0]
    return c && isChip(c) ? inner : m
  })
}

// ---------------------------------------------------------------------------------------- text width and cuts

/** The cells a character takes on the grid: 2 for a wide one (CJK, emoji), 1 else. */
export function cw(ch: string): number {
  const c = ch.codePointAt(0) ?? 0
  if (c === 0) return 0
  if (
    (c >= 0x1100 && c <= 0x115f) || (c >= 0x2e80 && c <= 0xa4cf) || (c >= 0xac00 && c <= 0xd7a3) ||
    (c >= 0xf900 && c <= 0xfaff) || (c >= 0xfe30 && c <= 0xfe4f) || (c >= 0xff00 && c <= 0xff60) ||
    (c >= 0xffe0 && c <= 0xffe6) || (c >= 0x1f300 && c <= 0x1faff)
  ) return 2
  return 1
}

export function width(s: string): number {
  let n = 0
  for (const ch of s) n += cw(ch)
  return n
}

/** The longest start of `s` that fits in `n` cells, with no `…`: a word wider than its row, broken where the row ends. */
export function prefix(s: string, n: number): string {
  let out = ''
  let w = 0
  for (const ch of s) {
    if (w + cw(ch) > n) break
    out += ch
    w += cw(ch)
  }
  return out
}

// what a cut leaves out before its `…`: the space and the punctuation that ended the last word kept, and the `·` of a
// list of facts whose next item it leaves out
const CUT_TAIL = /[\s,;:.!?\-–—·]+$/

/** Where the words in quotation marks that end `s` open (`"…"`, or `“…”`), when they open after its first cell; -1
 *  when `s` does not end in quoted words. */
function quoteOpens(s: string): number {
  const close = s.at(-1)
  if (close !== '"' && close !== '”') return -1
  const at = close === '”' ? s.lastIndexOf('“') : s.lastIndexOf('"', s.length - 2)
  return at >= 0 && at < s.length - 2 ? at : -1
}

/** `s` in at most `n` cells: whole when it fits, else cut at the last word that fits, mid-word only when that keeps
 *  less than half of the room, with no space or punctuation before the `…` (SPEC.md, section 5, "Words that recur").
 *  Words in quotation marks that end `s` are cut inside the marks, which stay: `thread "Which line of…"`.
 *  The one cut of thimble-term: every row, title, preview and path step that shortens prose shortens it here. */
export function cut(s: string, n: number): string {
  if (width(s) <= n) return s
  if (n <= 1) return n === 1 ? '…' : ''
  // quoted words with a short tail after them (`card "How many…" · code`): the words inside the marks cut, the marks and
  // the tail kept (live check term-fix9, low quirk: the code view's step read `card "How many deletes does…"…`)
  const tailed = /^(.*?["“])([^"“”]+)(["”] · [^"“”]{1,16})$/.exec(s)
  if (tailed && n - width(tailed[1]!) - width(tailed[3]!) >= 5) return `${tailed[1]}${cut(tailed[2]!, n - width(tailed[1]!) - width(tailed[3]!))}${tailed[3]}`
  const open = quoteOpens(s)
  if (open >= 0) {
    // the words before the quotation and its opening mark whole, the quoted words cut, then the closing mark; when the
    // room keeps fewer than 4 cells of the quoted words, the whole is cut as any words are
    const head = s.slice(0, open + 1)
    const room = n - width(head) - 1
    if (room >= 4) return `${head}${cut(s.slice(open + 1, -1), room)}${s.at(-1)}`
  }
  // words in quotation marks that open inside the words kept and close after the cut (`citation card "How many…" output
  // line 1`) keep their closing mark too: `citation card "How…"`
  const plain = cutWords(s, n)
  const close = unclosed(plain)
  if (!close || n < 3) return plain
  const shorter = cutWords(s, n - 1)
  return unclosed(shorter) ? `${shorter}${unclosed(shorter)}` : shorter
}

/** `s` cut at a word in `n` cells (cut's last step). */
function cutWords(s: string, n: number): string {
  let head = ''
  let w = 0
  for (const ch of s) {
    if (w + cw(ch) > n - 1) break
    head += ch
    w += cw(ch)
  }
  // a word that ends right where the room does is whole
  const at = /\s/.test(s[head.length] ?? '') ? head.length : head.search(/\s\S*$/)
  const keep = at > 0 && width(head.slice(0, at)) * 2 > n ? head.slice(0, at) : head
  return `${keep.replace(CUT_TAIL, '') || keep.trimEnd()}…`
}

/** The closing quotation mark words in quotation marks that open in `s` and do not close there want, else ''. */
function unclosed(s: string): string {
  if (s.lastIndexOf('“') > s.lastIndexOf('”')) return '”'
  return (s.match(/"/g)?.length ?? 0) % 2 === 1 ? '"' : ''
}

// a terminal's escape sequence (CSI, OSC, or one character after ESC), then any other control character
const ESCAPES = /\u001b(?:\[[0-?]*[ -/]*[@-~]|\][^\u0007\u001b]*(?:\u0007|\u001b\\)?|[@-_])?/g
const CONTROLS = /[\u0000-\u0008\u000b-\u001f\u007f-\u009f]/g

/** Text as a drawing may hold it: a terminal's escape sequences (a tool's colored output kept in a transcript) and
 *  other control characters left out, a tab or a newline as a space, since a drawing whose text holds one does not
 *  validate. Pure. */
export function noControls(s: string): string {
  return /[\u0000-\u001f\u007f-\u009f]/.test(s) ? s.replace(ESCAPES, '').replace(/[\t\n]/g, ' ').replace(CONTROLS, '') : s
}

/** A file's line in at most `n` cells: a line of code or data (JSON, a tag) cut at the cell edge, so the rows of a file
 *  end together; prose cut at a word, as `cut` cuts. */
export function cutLine(s: string, n: number): string {
  if (width(s) <= n || !/^\s*[{[<]/.test(s)) return cut(s, n)
  if (n <= 1) return n === 1 ? '…' : ''
  // no space or sentence punctuation right before the `…` (live check term-fix9, low quirk: `Some …`, `alone.…`); a
  // JSON key's colon stays, so a cut value reads as one (`"page_key":…`)
  const head = prefix(s, n - 1)
  return `${head.replace(/[\s.,;!?]+$/, '') || head}…`
}

/** Items of an inline list of facts parted by ` · ` in at most `n` cells: as many whole items as fit, then ` · +N` for
 *  the N left out (never a `…` against a whole item, which would read as a cut value: `wiki dse…`); the first item cut
 *  as `cut` cuts when not even it fits whole. */
export function itemsRow(items: readonly string[], n: number): string {
  let k = items.length
  const more = (m: number) => (m < items.length ? ` · +${items.length - m}` : '')
  const row = (m: number) => `${items.slice(0, m).join(' · ')}${more(m)}`
  while (k > 0 && width(row(k)) > n) k--
  if (k > 0) return row(k)
  const tail = more(1)
  return n - width(tail) >= 8 ? `${cut(items[0] ?? '', n - width(tail))}${tail}` : cut(items[0] ?? '', n)
}

/** `s` in at most `n` cells, cut in its middle at words so its end shows: `How many deletes… of 27 June?`, for rows
 *  that share their first words and differ at their ends (live check term-fix9, quirk 8: fifteen card rows read `How
 *  many deletes does…`). As `cut` when the room keeps fewer than 6 cells of the end. */
export function cutMiddle(s: string, n: number): string {
  if (width(s) <= n) return s
  const tailRoom = Math.floor((n - 2) / 2)
  if (tailRoom < 6) return cut(s, n)
  // the end: the last words that fit its half, whole
  const words = s.split(' ')
  let tail = ''
  for (let i = words.length - 1; i > 0; i--) {
    const next = tail ? `${words[i]} ${tail}` : words[i]!
    if (width(next) > tailRoom) break
    tail = next
  }
  if (!tail) return cut(s, n)
  const head = cut(s.slice(0, s.length - tail.length).trimEnd(), n - width(tail) - 1)
  return `${head.endsWith('…') ? head : `${head}…`} ${tail}`
}

/** `s` on one line in `n` cells, cut as `cut` cuts. */
export function clip(s: string, n: number): string {
  return cut(s.replace(/\s+/g, ' ').trim(), n)
}

/** About `room` characters of a long line around position `at` (a third of the room before it), each end cut at a word
 *  with `…` right against the words; `shift` is how far a position of `text` moved to the left. A line of data (JSON, a
 *  tag) is cut at the cell edge instead, `room` characters exactly, so the lines of a file end together (live check
 *  term-fix9, low quirk: a citation's context lines were cut to uneven widths). */
export function windowAt(text: string, at: number, room: number): { text: string; shift: number } {
  if (text.length <= room) return { text, shift: 0 }
  if (/^\s*[{[<]/.test(text) && room >= 4) {
    const lo = Math.max(0, Math.min(at - Math.floor(room / 3), text.length - room + 1))
    const late = lo > 0
    const hi = Math.min(text.length, lo + room - (late ? 1 : 0) - 1)
    const body = text.slice(lo, hi)
    return { text: `${late ? '…' : ''}${body}${hi < text.length ? '…' : ''}`, shift: lo - (late ? 1 : 0) }
  }
  let lo = Math.max(0, Math.min(at - Math.floor(room / 3), text.length - room))
  const late = lo > 0
  let hi = Math.min(text.length, lo + room - (late ? 2 : 1))
  if (late) {
    // the first word whole: start after the space that ends the cut one, while that loses less than a third of the
    // room; no space after the `…`
    if (!/\s/.test(text[lo - 1]!)) {
      const sp = text.slice(lo, Math.min(at, lo + Math.floor(room / 3))).search(/\s/)
      if (sp >= 0) lo += sp + 1
    }
    while (lo < hi && /\s/.test(text[lo]!)) lo++
  }
  if (hi < text.length && !/\s/.test(text[hi]!)) {
    const sp = text.slice(lo, hi).search(/\s\S*$/)
    if (sp > (hi - lo) / 2) hi = lo + sp
  }
  const body = text.slice(lo, hi)
  const end = hi < text.length ? `${body.replace(CUT_TAIL, '') || body.trimEnd()}…` : body
  return { text: `${late ? '…' : ''}${end}`, shift: lo - (late ? 1 : 0) }
}

/** Words in quotation marks for a row: straight ones, curly when the words hold straight ones of their own, and none
 *  when they hold both kinds, so no quotation marks stand inside the same kind. */
export function quoted(s: string): string {
  const straight = s.includes('"')
  const curly = /[“”]/.test(s)
  if (straight && curly) return s
  return straight ? `“${s}”` : `"${s}"`
}

/** Straight double quotation marks as curly ones, opening after a space or a bracket and closing elsewhere: words in a
 *  tool's row, where Claude Code escapes straight ones (`\"`). */
export function curlyQuotes(s: string): string {
  return s.replace(/"/g, (_m, at: number) => (at === 0 || /[\s([{—–-]/.test(s[at - 1]!) ? '“' : '”'))
}

// ---------------------------------------------------------------------------------------- inline runs

/** A line of Markdown as styled runs: bold, italic, code, links (their text), citations (one run each). */
export function inlineRuns(text: string): Run[] {
  const out: Run[] = []
  // each citation outside code is masked to one token of its length, so the brackets, stars and underscores of a
  // quoted value neither end it nor start emphasis
  let masked = ''
  let from = 0
  for (const sp of citeSpans(text.replace(FENCE_RE, m => ' '.repeat(m.length)))) {
    masked += `${text.slice(from, sp.at)}\uE000${'\uE001'.repeat(sp.end - sp.at - 1)}`
    from = sp.end
  }
  masked += text.slice(from)
  // tokens: code span, citation, link (citation form or web), bold, italic
  const TOKEN = /(`[^`\n]+`)|(\uE000\uE001*)|((?<![\[!])\[[^\[\]\n]*\]\([^()\s]*(?:\([^()\s]*\)[^()\s]*)*\))|(\*\*[^*\n]+\*\*|__[^_\n]+__)|((?<![\w*])\*[^*\n]+\*(?!\w)|(?<![\w_])_[^_\n]+_(?![\w]))/g
  let last = 0
  const push = (r: Run) => {
    if (r.text) out.push(r)
  }
  for (const m of masked.matchAll(TOKEN)) {
    const at = m.index ?? 0
    push({ text: text.slice(last, at) })
    const tok = text.slice(at, at + m[0].length)
    if (m[1]) push({ text: tok.slice(1, -1), code: true })
    else if (m[2]) {
      const c = spanCitation(tok.slice(2, -2))
      if (c) out.push({ text: chipLabel(c), cite: c })
      else push({ text: tok })
    } else if (m[3]) {
      const lm = /^\[([^\[\]\n]*)\]\((.*)\)$/.exec(tok)
      const c = lm ? linkCitation(lm[1]!, lm[2]!) : null
      if (c) out.push({ text: chipLabel(c), cite: c })
      else push({ text: lm ? lm[1]! : tok, u: true })
    } else if (m[4]) {
      for (const r of inlineRuns(tok.slice(2, -2))) push({ ...r, b: true })
    } else if (m[5]) {
      for (const r of inlineRuns(tok.slice(1, -1))) push({ ...r, i: true })
    }
    last = at + tok.length
  }
  push({ text: text.slice(last) })
  return out
}

// ---------------------------------------------------------------------------------------- blocks

/** A table row's cells: split at each bar outside citations and code spans; an escaped bar stays in its cell. */
export function tableCells(line: string): string[] {
  let t = line.trim()
  if (t.startsWith('|')) t = t.slice(1)
  if (t.endsWith('|') && !t.endsWith('\\|')) t = t.slice(0, -1)
  const cells: string[] = []
  let cur = ''
  let code = false
  for (let i = 0; i < t.length; i++) {
    const ch = t[i]!
    if (ch === '\\' && t[i + 1] === '|') {
      cur += '|'
      i++
      continue
    }
    // a citation's bars, escaped or not, stay in its cell
    const end = code ? -1 : citeEnd(t, i)
    if (end >= 0) {
      cur += t.slice(i, end).replaceAll('\\|', '|')
      i = end - 1
      continue
    }
    if (ch === '`') code = !code
    if (ch === '|' && !code) {
      cells.push(cur.trim())
      cur = ''
      continue
    }
    cur += ch
  }
  cells.push(cur.trim())
  return cells
}

const ALIGN_ROW = /^\s*\|?\s*:?-+:?\s*(\|\s*:?-+:?\s*)*\|?\s*$/

/** A Markdown table's lines as rows of runs, the alignment row read and left out. */
export function tableRuns(lines: string[]): TableRuns {
  const rows: Run[][][] = []
  let align: TableRuns['align'] = []
  for (const line of lines) {
    if (ALIGN_ROW.test(line) && line.includes('-')) {
      align = tableCells(line).map(c => (c.startsWith(':') && c.endsWith(':') ? 'center' : c.endsWith(':') ? 'right' : 'left'))
      continue
    }
    rows.push(tableCells(line).map(c => inlineRuns(c)))
  }
  return { rows, align }
}

/** A reply block cut into what the engine draws as Markdown (no citation in it), the cards it embeds, and the rich
 *  blocks thimble-term draws itself so their citations can be chips. Fences and tables stay Markdown whole. */
export function parseReply(text: string): Block[] {
  const lines = text.split('\n')
  const out: Block[] = []
  let md: string[] = []
  let blank = false // the line before the next block was blank
  const flush = () => {
    const first = md.findIndex(l => l.trim() !== '')
    if (first >= 0) {
      let last = md.length - 1
      while (!md[last]!.trim()) last--
      out.push({ type: 'md', text: md.slice(first, last + 1).join('\n'), gap: blank || first > 0 })
      blank = last < md.length - 1
    } else if (md.length) blank = true
    md = []
  }
  let i = 0
  while (i < lines.length) {
    const line = lines[i]!
    const embed = EMBED_RE.exec(line)
    if (embed) {
      flush()
      // a figure's caption (report.ts normalizeDoc) is the italic line right under its embed
      const cap = /^\s*\*([^*\n].*?)\*\s*$/.exec(lines[i + 1] ?? '')
      out.push({ type: 'card', id: (embed[1] ?? embed[2])!, gap: blank, ...(cap ? { caption: cap[1]!.trim() } : {}) })
      blank = false
      i += cap ? 2 : 1
      continue
    }
    if (/^\s*```/.test(line)) {
      const start = i
      i++
      while (i < lines.length && !/^\s*```/.test(lines[i]!)) i++
      md.push(...lines.slice(start, Math.min(i + 1, lines.length)))
      i++
      continue
    }
    if (/^\s*\|/.test(line)) {
      const start = i
      while (i < lines.length && /^\s*\|/.test(lines[i]!)) i++
      const rows = lines.slice(start, i)
      if (citations(rows.join('\n')).length === 0) {
        md.push(...rows)
        continue
      }
      flush()
      const table = tableRuns(rows)
      out.push({ type: 'rich', prefix: '', heading: 0, quote: false, runs: table.rows.flat(2), gap: blank, table })
      blank = false
      continue
    }
    if (!line.trim()) {
      md.push(line)
      i++
      continue
    }
    // one block: a heading, a list item (with its continuation lines), a quote, or a paragraph
    const head = /^(#{1,6})\s+(.*)$/.exec(line)
    const item = /^(\s*)([-*+]|\d+[.)])\s+(.*)$/.exec(line)
    const quote = /^\s*>\s?(.*)$/.exec(line)
    const start = i
    let body: string[]
    let prefix = ''
    let heading = 0
    let isQuote = false
    if (head) {
      heading = head[1]!.length
      body = [head[2]!]
      i++
    } else if (item) {
      prefix = `${item[1]!.replace(/\t/g, '  ')}${item[2]!} `
      body = [item[3]!]
      i++
      while (i < lines.length && lines[i]!.trim() && /^\s{2,}\S/.test(lines[i]!) && !/^\s*([-*+]|\d+[.)])\s/.test(lines[i]!)) body.push(lines[i++]!.trim())
    } else if (quote) {
      isQuote = true
      body = []
      while (i < lines.length && /^\s*>/.test(lines[i]!)) body.push(lines[i++]!.replace(/^\s*>\s?/, ''))
    } else {
      // its first line whatever it starts with (an indented "# " is no heading), then up to the next block
      body = [lines[i++]!]
      while (
        i < lines.length && lines[i]!.trim() && !EMBED_RE.test(lines[i]!) && !/^\s*(```|\||#{1,6}\s|>|([-*+]|\d+[.)])\s)/.test(lines[i]!)
      ) body.push(lines[i++]!)
    }
    const joined = body.join(' ')
    if (citations(joined).length === 0) {
      md.push(...lines.slice(start, i))
      continue
    }
    flush()
    out.push({ type: 'rich', prefix, heading, quote: isQuote, runs: inlineRuns(joined), gap: blank })
    blank = false
  }
  flush()
  if (out[0]) out[0].gap = false
  return out
}

/** A chunk of Markdown cut into its paragraphs (at blank lines outside a fence), each whole: what one "ask ›" asks
 *  about. A fence, a table or a list stays one piece. */
export function mdPieces(text: string): string[] {
  const out: string[] = []
  let cur: string[] = []
  let fence = false
  for (const line of text.split('\n')) {
    if (/^\s*```/.test(line)) fence = !fence
    if (!fence && !line.trim()) {
      if (cur.length) out.push(cur.join('\n'))
      cur = []
    } else cur.push(line)
  }
  if (cur.length) out.push(cur.join('\n'))
  return out
}

const ITEM_LINE = /^([-*+]|\d+[.)])\s/

/** mdPieces with each top-level item of a list a piece of its own, so a report's "?" asks about one item; an item's
 *  indented lines stay with it. `join`: the piece follows the one before without a blank line. */
export function askPieces(text: string): { text: string; join: boolean }[] {
  const out: { text: string; join: boolean }[] = []
  for (const piece of mdPieces(text)) {
    const lines = piece.split('\n')
    if (/^\s*```/.test(lines[0]!) || !lines.some(l => ITEM_LINE.test(l))) {
      out.push({ text: piece, join: false })
      continue
    }
    let cur: string[] = []
    let join = false
    for (const l of lines) {
      if (ITEM_LINE.test(l) && cur.length) {
        out.push({ text: cur.join('\n'), join })
        cur = []
        join = true
      }
      cur.push(l)
    }
    out.push({ text: cur.join('\n'), join })
  }
  return out
}

/** Each heading of a reply text and its section: the heading, and every line up to the next heading of its level or
 *  higher (its paragraphs, lists, tables and cards), keyed by the heading line as written. What "ask ›" beside a
 *  heading asks about. Headings inside a fence are not headings. */
export function sectionsOf(text: string): Map<string, string> {
  const lines = text.split('\n')
  const heads: { at: number; level: number }[] = []
  let fence = false
  lines.forEach((l, i) => {
    if (/^\s*```/.test(l)) fence = !fence
    const m = fence ? null : /^(#{1,6})\s+\S/.exec(l)
    if (m) heads.push({ at: i, level: m[1]!.length })
  })
  const out = new Map<string, string>()
  heads.forEach((h, k) => {
    const end = heads.slice(k + 1).find(x => x.level <= h.level)?.at ?? lines.length
    out.set(lines[h.at]!.trim(), lines.slice(h.at, end).join('\n').trim())
  })
  return out
}

/** Whether a reply block needs thimble-term's drawing: it embeds a card or holds a citation. */
export function needsDrawing(text: string): boolean {
  return text.split('\n').some(l => EMBED_RE.test(l)) || citations(text).length > 0
}

// ---------------------------------------------------------------------------------------- numbers (cite.py port)

const NUM_RE = /(?<![\w:./#\-−])[-−]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?%?(?![\w%:])/g
const PLAIN_RE = /^[-−]?(?:(?:0|[1-9][0-9]*)(?:\.[0-9]*)?|\.[0-9]+)$/
const QUOTES = '"\'“”‘’'

type Num = { v: bigint; scale: number }

function parts(s: string): Num | null {
  const t = s.trim().replaceAll(',', '').replaceAll('−', '-').replace(/%+$/, '').trim()
  if (!PLAIN_RE.test(t)) return null
  const neg = t.startsWith('-')
  const body = neg ? t.slice(1) : t
  const [int = '', frac = ''] = body.split('.')
  const v = BigInt((int || '0') + frac)
  return { v: neg ? -v : v, scale: frac.length }
}

function scaled(n: Num, scale: number): bigint {
  return n.v * 10n ** BigInt(scale - n.scale)
}

function eq(a: Num, b: Num): boolean {
  const s = Math.max(a.scale, b.scale)
  return scaled(a, s) === scaled(b, s)
}

function rounded(b: Num, d: number): Num[] {
  if (d >= b.scale) return [b]
  const div = 10n ** BigInt(b.scale - d)
  const neg = b.v < 0n
  const mag = neg ? -b.v : b.v
  const q = mag / div
  const r = mag % div
  const up = r * 2n >= div ? q + 1n : q
  const even = r * 2n > div || (r * 2n === div && q % 2n === 1n) ? q + 1n : q
  const sign = (x: bigint) => (neg ? -x : x)
  return [{ v: sign(up), scale: d }, { v: sign(even), scale: d }]
}

function norm(tok: string): string {
  const s = tok.replaceAll(',', '').replaceAll('−', '-').replace(/%+$/, '').trim()
  const n = parts(s)
  if (!n) return s
  let { v, scale } = n
  while (scale > 0 && v % 10n === 0n) {
    v /= 10n
    scale -= 1
  }
  if (v === 0n) return '0'
  const neg = v < 0n
  const digits = (neg ? -v : v).toString().padStart(scale + 1, '0')
  const text = scale ? `${digits.slice(0, -scale)}.${digits.slice(-scale)}` : digits
  return neg ? `-${text}` : text
}

/** The same value, or `shown` with only decimals dropped by rounding: "91%" cites 91.2, "6,500" does not cite 6,543. */
export function shownMatches(token: string, shown: string): boolean {
  const a = parts(token)
  const b = parts(shown)
  if (!a || !b) return norm(token) !== '' && norm(token) === norm(shown)
  if (eq(a, b)) return true
  return a.scale < b.scale && rounded(b, a.scale).some(r => eq(a, r))
}

const MONTHS: Record<string, number> = Object.fromEntries(
  [['jan', 'january'], ['feb', 'february'], ['mar', 'march'], ['apr', 'april'], ['may'], ['jun', 'june'], ['jul', 'july'], ['aug', 'august'], ['sep', 'sept', 'september'], ['oct', 'october'], ['nov', 'november'], ['dec', 'december']].flatMap((names, i) => names.map(n => [n, i + 1])),
)
// a day and a month in words, as prose writes a date (`23 June`, `June 23`, `23rd June`, `Jun. 23`), with or without a
// year and a time after it (`4 June 2026 at 10:53:40 UTC`); a date as an output writes it, ISO (`2026-06-23`, also at a
// time stamp's head) or month and day (`06-23`), and the time a stamp writes right after its date
const DAY_MONTH_RE = /^(?:(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]{3,9})\.?|([A-Za-z]{3,9})\.?\s+(\d{1,2})(?:st|nd|rd|th)?)(?:,?\s+(\d{4}))?(?:,?\s+(?:at\s+)?(\d{1,2}:\d{2}(?::\d{2})?)(?:\s*(?:UTC|GMT|Z))?)?$/i
const ISO_DATE_RE = /(?<![\d-])(?:(\d{4})-)?(\d{2})-(\d{2})(?![\d-])/g
const STAMP_CLOCK_RE = /^[T ](\d{1,2}:\d{2}(?::\d{2})?)(?![\d:])/
const CLOCK_RE = /(?<![\d:])(\d{1,2}):(\d{2})(?::(\d{2}))?(?:\.\d+)?(?![\d:])/g

/** The month, day, year and time of a shown value that is a day and a month in words (`23 June`, `4 June 2026 at
 *  10:53:40 UTC`), or null for any other words (backend cite._date_words). */
export function dayMonth(display: string): { month: number; day: number; year: number | null; clock: string | null } | null {
  const m = DAY_MONTH_RE.exec(display.trim())
  if (!m) return null
  const [day, word] = m[1] ? [m[1], m[2]!] : [m[4]!, m[3]!]
  const month = MONTHS[word.toLowerCase()]
  if (!month || Number(day) < 1 || Number(day) > 31) return null
  return { month, day: Number(day), year: m[5] ? Number(m[5]) : null, clock: m[6] ?? null }
}

/** Whether every clock time the shown value writes is one the text writes: the same hour and minute, the same second
 *  when the value gives one (backend cite.clocks_in). */
export function clocksIn(display: string, text: string): boolean {
  const have = [...text.matchAll(CLOCK_RE)].map(c => [Number(c[1]), c[2], c[3] ?? ''] as const)
  return [...display.matchAll(CLOCK_RE)].every(c => have.some(([h, mi, se]) => h === Number(c[1]) && mi === c[2] && (!c[3] || c[3] === se)))
}

/** Whether a shown value that is a day and a month in words (`23 June`) names a date the text writes as ISO
 *  (`2026-06-23`) or as month and day (`06-23`): the same month and day, the year too when both give one (backend
 *  cite.date_in; live check term-fix6, new quirk 7: `23 June` citing a cell `06-23` was red). A time after the date is
 *  the time the stamp writes after that date, or with none there, a clock time of the text (live check term-fix7, new
 *  quirk 1: `4 June 2026 at 10:53:40 UTC` against 2026-06-04T10:53:40Z was not found). */
export function dateIn(display: string, text: string): boolean {
  const want = dayMonth(display)
  if (!want) return false
  for (const d of text.matchAll(ISO_DATE_RE)) {
    if (Number(d[2]) !== want.month || Number(d[3]) !== want.day || (want.year !== null && d[1] && Number(d[1]) !== want.year)) continue
    if (want.clock === null) return true
    const stamp = STAMP_CLOCK_RE.exec(text.slice(d.index! + d[0].length))
    if (clocksIn(want.clock, stamp ? stamp[1]! : text)) return true
  }
  // a date the text writes in words (`23 June`, a row named `last delete on 30 June`; backend cite.date_in, live check
  // term-fix9, quirk 11)
  return datesInWords(text).some(d => sameDate(want, d.date, text))
}

/** Whether a date in words (`got`, at its place in `text`) is the day and month `want` names, the year too when both
 *  give one, and its clock time among the text's when `want` gives one. */
function sameDate(want: NonNullable<ReturnType<typeof dayMonth>>, got: NonNullable<ReturnType<typeof dayMonth>>, text: string): boolean {
  if (got.month !== want.month || got.day !== want.day || (want.year !== null && got.year !== null && got.year !== want.year)) return false
  return want.clock === null || clocksIn(want.clock, got.clock ?? text)
}

const MONTH_WORD = `(?:${Object.keys(MONTHS).sort((a, b) => b.length - a.length).join('|')})`
// a day and a month in words inside a text, with its year and time when it has them (backend cite._DATE_IN_TEXT_RE)
const DATE_IN_TEXT_RE = new RegExp(`(?<![\\w.])(?:\\d{1,2}(?:st|nd|rd|th)?\\s+${MONTH_WORD}\\b\\.?|${MONTH_WORD}\\.?\\s+\\d{1,2}(?:st|nd|rd|th)?(?![\\d:]))(?:,?\\s+\\d{4}(?!\\d))?(?:,?\\s+(?:at\\s+)?\\d{1,2}:\\d{2}(?::\\d{2})?(?:\\s*(?:UTC|GMT|Z)\\b)?)?`, 'gi')

/** Each day and month a text writes in words, where it stands and what it names; `may` in lower case is the verb. */
export function datesInWords(text: string): { at: number; end: number; date: NonNullable<ReturnType<typeof dayMonth>> }[] {
  const out: { at: number; end: number; date: NonNullable<ReturnType<typeof dayMonth>> }[] = []
  for (const m of text.matchAll(DATE_IN_TEXT_RE)) {
    const words = m[0].replace(/[,\s]+$/, '').replace(/\.$/, '')
    const date = dayMonth(words)
    if (date && !/\bmay\b/.test(words)) out.push({ at: m.index!, end: m.index! + words.length, date })
  }
  return out
}

const STAMP_RE = /(?<![\d-])(?:\d{4}-)?\d{2}-\d{2}(?:[T ]\d{1,2}:\d{2}(?::\d{2})?(?:\.\d+)?Z?)?(?![\d-])/g

/** Where a line writes the date a shown value names in words, in digits (`23 June` at `2026-06-23`) or in words: each
 *  stamp dateIn accepts, and each date in words of the same day, as [start, end], so a citation's panel marks the date
 *  it cites. */
export function dateSpans(display: string, line: string): number[][] {
  const want = dayMonth(display)
  if (!want) return []
  const stamps = [...line.matchAll(STAMP_RE)].filter(m => dateIn(display, m[0])).map(m => [m.index!, m.index! + m[0].length])
  return [...stamps, ...datesInWords(line).filter(d => sameDate(want, d.date, line)).map(d => [d.at, d.end])].sort((a, b) => a[0]! - b[0]!)
}

/** Whether a shown value is in a text: a number must match a whole number of it, a day and a month in words a date it
 *  writes in digits (dateIn), anything else is a substring. */
export function valueIn(display: string, text: string): boolean {
  for (const m of text.matchAll(NUM_RE)) if (shownMatches(display, m[0])) return true
  if (dateIn(display, text)) return true
  const d = display.trim()
  if (new RegExp(`^(?:${NUM_RE.source})$`).test(d)) return false
  let words = d
  if (words.length > 2 && QUOTES.includes(words[0]!) && QUOTES.includes(words.at(-1)!)) words = words.slice(1, -1)
  return text.replaceAll(',', '').includes(norm(words))
}

/** The value a verification script printed: its last line of the form `RESULT: <value>`, or null. */
export function scriptResult(stdout: string): string | null {
  const hits = [...stdout.matchAll(/^RESULT:\s*(.+?)\s*$/gm)]
  return hits.length ? hits.at(-1)![1]! : null
}

/** A value as a card shows it: an integer whole, a float to at most 3 decimals. */
export function fmt(v: unknown): string {
  if (typeof v === 'number') {
    if (!Number.isFinite(v)) return String(v)
    if (Number.isInteger(v)) return String(v)
    const s = v.toFixed(3).replace(/0+$/, '').replace(/\.$/, '')
    return s === '-0' ? '0' : s
  }
  return v === null || v === undefined ? '' : String(v)
}

// the number formats thimble gives a table's columns (backend frames.default_format, which d3-format reads in the
// browser): `,d` and `d` for whole numbers, `,.N~f` and `.N~f` for the others
const FORMAT_RE = /^(,)?(?:d|\.(\d)~f)$/

/** A number in a table column's format, as the browser's table writes it (FrameTable's cellText, d3-format), for the
 *  formats thimble gives; null for any other format. A negative number takes the minus sign, as d3-format writes it. */
export function formatted(v: number, spec: string | undefined): string | null {
  const m = spec ? FORMAT_RE.exec(spec) : null
  if (!m || !Number.isFinite(v)) return null
  const places = m[2] !== undefined ? Number(m[2]) : 0
  // a tie rounds away from zero, as the backend's ROUND_HALF_UP of the float's exact value and JS's toFixed do
  let text = Math.abs(v).toFixed(places)
  const [whole = '0', frac0 = ''] = text.split('.')
  const frac = m[2] !== undefined ? frac0.replace(/0+$/, '') : ''
  const grouped = m[1] ? whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',') : whole
  const zero = Number(text) === 0
  text = `${grouped}${frac ? `.${frac}` : ''}`
  return (v < 0 || Object.is(v, -0)) && !zero ? `−${text}` : text
}

/** A record's fields as a label's example shows them, when its words are a JSON object (a line of a JSON lines file):
 *  `read`, the fields the label's rule reads (a code label's `unit['name']` or `.get('name')`, the field a pattern
 *  matches, the fields a prompt names, else the record's words), each its value as a string; `rest`, the other fields
 *  whose value is one value, in the record's order. null for words that are no JSON object. A cut record (`…` at its
 *  end) is read field by field as far as it goes. */
export function recordFields(text: string, rule: { kind?: string; spec?: string; match?: string }): { read: [string, string][]; rest: [string, string][] } | null {
  const t = text.trim()
  if (!t.startsWith('{')) return null
  let fields: [string, unknown][] = []
  try {
    const v = JSON.parse(t) as unknown
    if (!v || typeof v !== 'object' || Array.isArray(v)) return null
    fields = Object.entries(v as Record<string, unknown>)
  } catch {
    // its fields as far as the cut words go: each `"key": value` of a scalar value
    for (const m of t.matchAll(/"((?:[^"\\]|\\.)+)"\s*:\s*("(?:[^"\\]|\\.)*"|-?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?|true|false|null)/g)) {
      try {
        fields.push([JSON.parse(`"${m[1]!}"`) as string, JSON.parse(m[2]!) as unknown])
      } catch {
        // a field whose words cannot be read is left out
      }
    }
    if (!fields.length) return null
  }
  const words = (v: unknown): string => (typeof v === 'string' ? v : v === null || v === undefined ? '' : typeof v === 'object' ? JSON.stringify(v) : String(v))
  const keys = fields.map(([k]) => k)
  const spec = rule.spec ?? ''
  let read: string[] = []
  if (rule.kind === 'code') {
    for (const m of spec.matchAll(/\[\s*(['"])([^'"\n]+)\1\s*\]|\.get\(\s*(['"])([^'"\n]+)\3/g)) {
      const k = m[2] ?? m[4]!
      if (keys.includes(k) && !read.includes(k)) read.push(k)
    }
  } else if (rule.kind === 'regex') {
    const hit = (v: unknown) => {
      if (typeof v !== 'string') return false
      if (rule.match) return v.includes(rule.match)
      try {
        return new RegExp(spec).test(v)
      } catch {
        return false
      }
    }
    read = fields.filter(([, v]) => hit(v)).map(([k]) => k).slice(0, 2)
  } else if (spec) {
    const lower = spec.toLowerCase()
    read = keys.filter(k => new RegExp(`\\b${k.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/_/g, '[_ ]')}\\b`).test(lower)).slice(0, 2)
  }
  if (!read.length) {
    // a record's words: its text field, else its longest words
    const text = keys.find(k => /^(text|content|message|body|msg|comment|title|name|summary)$/i.test(k) && typeof fields.find(([x]) => x === k)?.[1] === 'string')
    const longest = fields.filter(([, v]) => typeof v === 'string').sort((a, b) => words(b[1]).length - words(a[1]).length)[0]?.[0]
    read = [text ?? longest ?? keys[0]!].filter(Boolean)
  }
  const one = (v: unknown) => v === null || ['string', 'number', 'boolean'].includes(typeof v)
  return {
    read: read.map(k => [k, words(fields.find(([x]) => x === k)?.[1])]),
    rest: fields.filter(([k, v]) => !read.includes(k) && one(v)).map(([k, v]) => [k, words(v)]),
  }
}

/** The sentence of a reply that holds a citation, for the prompt that asks for its verification script. */
export function sentenceOf(text: string, raw: string): string {
  const at = text.indexOf(raw)
  if (at < 0) return ''
  const before = text.slice(0, at)
  const start = Math.max(before.lastIndexOf('. ') + 1, before.lastIndexOf('\n') + 1, 0)
  const rest = text.slice(at)
  const m = /[.!?](\s|$)|\n/.exec(rest)
  return text.slice(start, at + (m ? m.index + 1 : rest.length)).trim()
}

// ---------------------------------------------------------------------------------------- card files

// `label` is the label tool's own card (cell.ts labelCard), never one main writes
export const CARD_KINDS = ['bar', 'line', 'timeline', 'table', 'example', 'diagram', 'label'] as const
export const MAX_DIAGRAM_NODES = 40
export const MAX_DIAGRAM_EDGES = 80

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v)
const isNum = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v)
const isStr = (v: unknown): v is string => typeof v === 'string'
const isCell = (v: unknown) => v === null || isStr(v) || isNum(v) || typeof v === 'boolean'

/** Why a card file cannot be drawn, or null when it fits its kind's spec. The mod draws only these typed specs; a card
 *  that fails is drawn as this error, and main is asked to fix it. */
export function validateCard(c: unknown, id?: string): string | null {
  if (!isObj(c)) return 'the file is not a JSON object'
  if (!isStr(c.id) || !/^[A-Za-z0-9_-]+$/.test(c.id)) return 'no valid id'
  if (id !== undefined && c.id !== id) return `its id is ${c.id}, not ${id}`
  if (!isStr(c.kind) || !(CARD_KINDS as readonly string[]).includes(c.kind)) return `kind must be one of ${CARD_KINDS.join(', ')}`
  if (!isStr(c.question) || !c.question.trim()) return 'no question'
  const list = (k: string) => (Array.isArray(c[k]) ? (c[k] as unknown[]) : null)
  switch (c.kind) {
    case 'bar':
    case 'label': {
      const rows = list('rows')
      if (!rows?.length) return `a ${c.kind} card needs rows`
      const bad = rows.findIndex(r => !isObj(r) || !isStr(r.label) || !isNum(r.value))
      if (bad >= 0) return `${c.kind} row ${bad + 1} needs a label and a finite number value`
      if (c.kind === 'bar') break
      const l = c.label
      if (!isObj(l) || !isStr(l.slug) || !isStr(l.name) || !Array.isArray(l.values) || !l.values.every(isStr)) return 'a label card needs its label: slug, name and values'
      const exs = list('examples') ?? []
      const badX = exs.findIndex(e => !isObj(e) || !isStr(e.ref) || !isStr(e.quote) || !isStr(e.value) || !(l.values as string[]).includes(e.value))
      if (badX >= 0) return `label card example ${badX + 1} needs a ref, its words and one of the label's values`
      break
    }
    case 'line': {
      const series = list('series')
      if (!series?.length) return 'a line card needs series'
      for (const s of series) {
        if (!isObj(s) || !isStr(s.name) || !Array.isArray(s.points) || s.points.length === 0) return 'each series needs a name and points'
        const bad = (s.points as unknown[]).findIndex(p => !Array.isArray(p) || p.length !== 2 || !(isStr(p[0]) || isNum(p[0])) || !isNum(p[1]))
        if (bad >= 0) return `series ${s.name}: point ${bad + 1} must be [x, number]`
      }
      break
    }
    case 'timeline': {
      const evs = list('events')
      if (!evs?.length) return 'a timeline card needs events'
      const bad = evs.findIndex(e => !isObj(e) || !isStr(e.time) || !isStr(e.label) || !isStr(e.ref) || !(e.shown === undefined || isStr(e.shown)))
      if (bad >= 0) return `event ${bad + 1} needs time, label and ref (shown is optional text)`
      break
    }
    case 'table': {
      const cols = list('columns')
      const rows = list('rows')
      if (!cols?.length || !cols.every(isStr)) return 'a table card needs columns, as strings'
      if (!rows) return 'a table card needs rows'
      const bad = rows.findIndex(r => !Array.isArray(r) || r.length !== cols.length || !r.every(isCell))
      if (bad >= 0) return `table row ${bad + 1} must have ${cols.length} plain values`
      break
    }
    case 'example': {
      const exs = list('examples')
      if (!exs?.length) return 'an example card needs examples'
      const bad = exs.findIndex(e => !isObj(e) || !isStr(e.ref) || !/#L\d+/.test(e.ref) || !isStr(e.quote))
      if (bad >= 0) return `example ${bad + 1} needs a ref to lines (file#L12) and a quote`
      break
    }
    case 'diagram': {
      const nodes = list('nodes')
      const edges = list('edges') ?? []
      if (!nodes?.length) return 'a diagram card needs nodes'
      if (nodes.length > MAX_DIAGRAM_NODES) return `a diagram card shows at most ${MAX_DIAGRAM_NODES} nodes`
      if (edges.length > MAX_DIAGRAM_EDGES) return `a diagram card shows at most ${MAX_DIAGRAM_EDGES} edges`
      const opt = (v: unknown) => v === undefined || isStr(v)
      const bad = nodes.findIndex(n => !isObj(n) || !isStr(n.id) || !n.id || !isStr(n.label) || !n.label.trim() || !opt(n.ref) || !opt(n.detail))
      if (bad >= 0) return `node ${bad + 1} needs an id and a label (ref and detail are optional text)`
      const ids = new Set(nodes.map(n => (n as { id: string }).id))
      if (ids.size !== nodes.length) return 'each node needs an id of its own'
      const badE = edges.findIndex(e => !isObj(e) || !isStr(e.source) || !isStr(e.target) || !ids.has(e.source) || !ids.has(e.target) || !opt(e.label))
      if (badE >= 0) return `edge ${badE + 1} needs a source and a target among the node ids`
      break
    }
  }
  if (c.labels !== undefined) {
    const ls = c.labels
    if (!Array.isArray(ls) || ls.some(l => !isObj(l) || !isStr(l.slug) || !isStr(l.name) || !Array.isArray(l.values) || !l.values.every(isStr) || !(l.marks === undefined || isObj(l.marks)))) {
      return 'labels must be a list of {slug, name, values, marks?}, as the card helper writes it'
    }
  }
  if (c.params !== undefined) {
    if (!Array.isArray(c.params)) return 'params must be a list'
    for (const p of c.params as unknown[]) {
      if (!isObj(p) || !isStr(p.name) || !Array.isArray(p.choices) || !p.choices.some(x => String(x) === String(p.value))) {
        return 'each param needs a name, choices and a value among them'
      }
    }
  }
  return null
}

/** The ids of the cards a reply embeds (lines holding only [[card:<id>]]), in order. */
export function embeddedCards(text: string): string[] {
  const out: string[] = []
  for (const line of text.split('\n')) {
    const m = EMBED_RE.exec(line)
    if (m) out.push((m[1] ?? m[2])!)
  }
  return out
}

/** The paragraph after a card's embed line: the card's takeaway, as the reply wrote it. */
export function takeawayAfter(text: string, id: string): string {
  const lines = text.split('\n')
  const at = lines.findIndex(l => {
    const m = EMBED_RE.exec(l)
    return m !== null && (m[1] ?? m[2]) === id
  })
  if (at < 0) return ''
  let i = at + 1
  while (i < lines.length && !lines[i]!.trim()) i++
  const out: string[] = []
  while (i < lines.length && lines[i]!.trim() && !EMBED_RE.test(lines[i]!) && !/^\s*(#{1,6}\s|```|\|)/.test(lines[i]!)) out.push(lines[i++]!)
  return out.join('\n')
}

/** A one-line version of a side thread's answer to offer main: its `FOR MAIN:` line, else its first sentence. */
export function forMain(answer: string): string {
  const m = /^\s*FOR MAIN:\s*(.+)$/m.exec(answer)
  if (m) return m[1]!.trim()
  const first = answer.replace(/\s+/g, ' ').trim()
  const end = /[.!?](\s|$)/.exec(first)
  return end ? first.slice(0, end.index + 1) : first.slice(0, 200)
}

/** A side thread's answer as the pane draws it: its `FOR MAIN:` line left out (the pane offers it as a button). */
export function threadBody(answer: string): string {
  return answer.replace(/^\s*FOR MAIN:.*$/m, '').trim()
}

files.hooks/model.ts:
// What thimble-term reads from `thimble state`, put in the forms its drawing takes (no `$`): cells, a citation's check,
// a thread's chat as a side thread's turns, the threads list, the agents, the workspace's counts; and the rules for what
// a turn of main made (the cards each tool call names) and what main's reply shows (no end token).
//
// Each reader takes the shape the server's GET route for that surface answers, and is lenient: a field it cannot read
// is left out rather than failing the drawing.
import type { ChatThread, ChatThreadTurn, TermAgent, TermHome, TermThreadRow, TermVerdict } from '../types'
import type { ThimbleCell, ThimbleLabel } from './cell'
import { STOP_KINDS, clip, curlyQuotes, dateSpans, quoted, shownMatches, valueIn } from './lib'
import type { Citation } from './lib'
import { quotedWords, showsValue } from './cite'

type Obj = Record<string, unknown>

const isObj = (v: unknown): v is Obj => Boolean(v) && typeof v === 'object' && !Array.isArray(v)
const str = (v: unknown): string => (typeof v === 'string' ? v : v === null || v === undefined ? '' : String(v))
const num = (v: unknown): number => (typeof v === 'number' && Number.isFinite(v) ? v : Array.isArray(v) ? v.length : 0)

// ------------------------------------------------------------------------------------------------ cells and labels

/** The cells `thimble state cards --since` printed: the canvas route's `{groups, cells}`, or a list of cells. */
export function cellsOf(v: unknown): ThimbleCell[] {
  const list = Array.isArray(v) ? v : isObj(v) && Array.isArray(v.cells) ? v.cells : []
  return list.filter((c): c is ThimbleCell => isObj(c) && typeof c.id === 'string')
}

/** The cell `thimble state card <id>` printed: the cell route's cell, or `{cell}`. */
export function cellOf(v: unknown): ThimbleCell | null {
  const c = isObj(v) && isObj(v.cell) ? v.cell : v
  return isObj(c) && typeof c.id === 'string' ? (c as ThimbleCell) : null
}

/** A label with its counts in `label_stats`, where the drawing reads them: the concept routes give them as `counts`
 *  and `n_labeled` beside the concept's fields (concepts.with_stats); the label's stored file holds `label_stats`. */
function withStats(c: Obj): ThimbleLabel {
  if (isObj(c.label_stats) || !isObj(c.counts)) return c as ThimbleLabel
  return { ...c, label_stats: { counts: c.counts as Record<string, number>, ...(typeof c.n_labeled === 'number' ? { n_labeled: c.n_labeled } : {}) } } as ThimbleLabel
}

/** The label `thimble state label <id>` printed: the concept route's concept, or `{concept, rows}`. */
export function labelOf(v: unknown): ThimbleLabel | null {
  if (!isObj(v)) return null
  const c = isObj(v.concept) && typeof v.concept.id === 'string' ? { ...v.concept, ...(Array.isArray(v.rows) ? { rows: v.rows } : {}) } : v
  return typeof c.id === 'string' ? withStats(c) : null
}

/** The labels `thimble state labels` printed: the concepts route's list. */
export function labelsOf(v: unknown): ThimbleLabel[] {
  const list = Array.isArray(v) ? v : isObj(v) && Array.isArray(v.labels) ? v.labels : isObj(v) && Array.isArray(v.concepts) ? v.concepts : []
  return list.filter((c): c is Obj => isObj(c) && typeof c.id === 'string').map(withStats)
}

/** The count a link to a label shows now (`concept:<id>/<value>`; the label whole, `value` '', for the records it
 *  labeled), with the analyst's verdicts, as the label card's bars read it; null when the label or the value is not
 *  known. */
export function labelCountNow(l: ThimbleLabel | null | undefined, value: string): number | null {
  if (!l) return null
  const counts = l.verdicts?.counts ?? l.label_stats?.counts
  if (!counts) return null
  if (!value) return l.label_stats?.n_labeled ?? Object.values(counts).reduce((a, b) => a + b, 0)
  return value in counts ? counts[value]! : (l.labels ?? []).includes(value) ? 0 : null
}

/** What a takeaway's link to a label says when the label no longer counts its number (a verdict, or a run, changed the
 *  counts): the count now, and that the verdicts are in it; '' when the number is the count, or no number (live check
 *  term-fix7, quirk 8: after a verdict the takeaway's 180 and 4,399 stayed blue beside bars reading 179 and 4,400). */
export function labelLinkStale(display: string | null, l: ThimbleLabel | null | undefined, value: string): string {
  const now = labelCountNow(l, value)
  if (now === null || display === null || !/^[-−]?(?:\d{1,3}(?:,\d{3})+|\d+)$/.test(display.trim())) return ''
  if (shownMatches(display.trim(), String(now))) return ''
  return `the label counts ${now.toLocaleString('en-US')} now${l?.verdicts?.set ? ', with your verdicts' : ''}`
}

/** The label a label card counts: its payload's concept, else the first label it carries. */
export function labelIdOf(cell: ThimbleCell): string {
  const p = cell.payload
  const c = p && typeof p === 'object' ? str((p as Obj).concept) : ''
  return c || (cell.kind === 'label' ? str(cell.labels?.[0]) : '')
}

// ------------------------------------------------------------------------------------------------ main's turn

const CARD_TOOLS = /^mcp__plugin_thimble_thimble__(add_card|edit_card|add_cell|edit_cell)$/
const LABEL_TOOL = /^mcp__plugin_thimble_thimble__apply_label$/
const RUN_RE = /(?:^|[\s/'"])thimble-run['"]?\s+(card|label|stale)\b\s*['"]?([A-Za-z0-9_-]*)/g

/** The cards a call of main's names as its own: add_card's and edit_card's card, apply_label's label card; for a Bash
 *  command that runs `thimble-run` (`thimble-run card <id>`, or several in a shell loop), each card it names and each
 *  card its output names on a line of its own (`card:<id>`, as add_card prints it), the label card of a code label's
 *  `thimble-run label`. */
export function cardsOfCall(tool: string, input: unknown, text: string): string[] {
  const inp = isObj(input) ? input : {}
  if (CARD_TOOLS.test(tool)) {
    const own = /^card:([A-Za-z0-9_-]+)\s*$/m.exec(text)?.[1] ?? /\bcard:([A-Za-z0-9_-]+)/.exec(text)?.[1]
    const named = str(inp.card).replace(/^(?:card|cell):/, '')
    return [...new Set([own, named].filter((x): x is string => Boolean(x)))].slice(0, 1)
  }
  if (LABEL_TOOL.test(tool)) {
    const card = /The label's card is \[\[card:([A-Za-z0-9_-]+)\]\]/.exec(text)?.[1]
    return card ? [card] : []
  }
  if (tool === 'Bash') {
    const cmd = str(inp.command)
    if (!/thimble-run\b/.test(cmd)) return []
    const out = new Set<string>()
    for (const m of cmd.matchAll(RUN_RE)) if (m[1] === 'card' && m[2]) out.add(m[2])
    for (const m of text.matchAll(/^card:([A-Za-z0-9_-]+)\s*$/gm)) out.add(m[1]!)
    const card = /The label's card is \[\[card:([A-Za-z0-9_-]+)\]\]/.exec(text)?.[1]
    if (card) out.add(card)
    return [...out]
  }
  return []
}

/** The card ids a Bash command that runs `thimble-run card` names: after `thimble-run card`, or in a shell loop's list
 *  (`for c in 2d10d7f3 9b4bb0cb; do $B card $c; done`). */
export function runIds(command: string): string[] {
  if (!/thimble-run\b/.test(command) || !/\bcard\b/.test(command)) return []
  return [...new Set([...command.matchAll(/(?:card:)?\b([0-9a-f]{8})\b/g)].map(m => m[1]!))]
}

/** A Bash command that runs `thimble-run`, as its row shows it: the verb, and for `card` each card by its question
 *  (`questionOf`), never the install path or an id; a shell loop's cards too. Cards not read yet are counted. */
export function runShown(command: string, questionOf: (id: string) => string | undefined): string {
  const verb = /(?:thimble-run|\$\{?\w+\}?)['"]?\s+['"]?(card|label|stale)\b/.exec(command)?.[1]
  if (verb !== 'card') return verb ? `thimble-run ${verb}` : 'thimble-run'
  const ids = runIds(command)
  const named = ids.map(questionOf).filter((q): q is string => Boolean(q))
  // each question cut at a word, never mid-word
  const short = (q: string) => quoted(clip(q, 40))
  if (named.length && named.length === ids.length) return `thimble-run card ${named.map(short).join(', ')}`
  return ids.length > 1 ? `thimble-run card · ${ids.length} cards` : 'thimble-run card'
}

type NamedRow = { id: string; title: string; question?: string; fork?: string }

/** A thread's first question as its rows name it: one line, its citations as their words. */
function questionWords(q: string | undefined): string {
  return (q ?? '').replace(/\[\[([^|\]]*)\|[^\]]*\]\]/g, '$1').replace(/\s+/g, ' ').trim()
}

/** The thread a fork's name names: the slug its forks run under (`fork_name`), its title or its id. */
function bySlug(rows: readonly NamedRow[], name: string): NamedRow | undefined {
  return rows.find(x => x.fork === name || x.title === name || x.id === name)
}

/** main's `↳ thread <name>: …` lines (main.md's form, `<name>` the fork's slug) with each thread named by its first
 *  question in quotation marks, as the chat names a thread everywhere else. */
export function namedThreads(text: string, rows: readonly NamedRow[]): string {
  if (!/↳\s*thread\s+[A-Za-z0-9_-]/.test(text)) return text
  return text.replace(/(↳\s*thread\s+)([A-Za-z0-9_-]+)(\s*:)/g, (m, lead: string, name: string, colon: string) => {
    const q = questionWords(bySlug(rows, name)?.question)
    if (!q) return m
    return `${lead}${quoted(clip(q, 40))}${colon}`
  })
}

/** main's own `↳ thread <name>: …` lines left out for each thread whose row thimble-term drew in main's chat (`told`,
 *  by id): the row says the thread answered, so the chat does not say it twice. `<name>` is the fork's slug, or the
 *  thread's first question in quotation marks. */
export function withoutToldThreads(text: string, rows: readonly NamedRow[], told: ReadonlySet<string>): string {
  if (!told.size || !/↳\s*thread\s/.test(text)) return text
  const lines = text.split('\n')
  const kept = lines.filter(l => {
    const m = /^\s*↳\s*thread\s+("[^"]*"|“[^”]*”|[A-Za-z0-9_:,.-]+?)\s*:/.exec(l)
    if (!m) return true
    const name = m[1]!
    const words = /^["“]/.test(name) ? questionWords(name.slice(1, -1)).replace(/…$/, '') : ''
    const r = words ? rows.find(x => words.length >= 8 && questionWords(x.question).startsWith(words)) : bySlug(rows, name)
    return !(r && told.has(r.id))
  })
  if (kept.length === lines.length) return text
  return kept.join('\n').replace(/\n{3,}/g, '\n\n').trim()
}

// main's own line about a writer's end (prompts/main.md: `↳ The writer finished; thimble shows it.`, also `↳ The report
// writer finished, …`), which it writes once for the writer's message and again for Claude Code's task notification
const WRITER_LINE = /^\s*↳\s*(?:the\s+)?(?:[\w-]+\s+)?writer\b/i

/** Whether a reply holds main's `↳ The writer …` line. */
export function saysWriter(text: string): boolean {
  return text.split('\n').some(l => WRITER_LINE.test(l))
}

/** A reply without main's `↳ The writer …` lines: for a row whose writer's end an earlier row said already (live check
 *  term-fix6, new quirk 6: `↳ The writer finished the report; thimble shows it.` once after the writer's message and
 *  again after the task notification). */
export function withoutWriterLines(text: string): string {
  if (!saysWriter(text)) return text
  return text.split('\n').filter(l => !WRITER_LINE.test(l)).join('\n').replace(/\n{3,}/g, '\n\n').trim()
}

/** An Agent call's description or a task notification's words with each thread's fork (`thread:<slug>`, in quotation
 *  marks or not) named by the thread's first question, as everywhere else: `thread "How many of the 2,994…"`. A fork
 *  of a thread not listed keeps its words. */
export function namedForks(text: string, rows: readonly NamedRow[], n = 40): string {
  if (!/\bthread:/.test(text)) return text
  return text.replace(/"?\bthread:([^\s"]+?)([.,;:]*)"?(?=\s|$)/g, (m, slug: string, tail: string) => {
    const q = questionWords(bySlug(rows, slug)?.question)
    return q ? `thread ${quoted(clip(q, n))}${tail}` : m
  })
}

/** A reply without main's own `↳` lines (a hand-back's or a thread's note to the terminal): the answer a thread about
 *  it is told. */
export function withoutNotes(text: string): string {
  return text.split('\n').filter(l => !/^\s*↳/.test(l)).join('\n').replace(/\n{3,}/g, '\n\n').trim()
}

/** The description main's Agent call for a thread's fork runs with: the thread's first question, `thread: How many…`,
 *  in place of `thread:<slug>`, so that Claude Code's agent tray and exit dialog name the thread as the chat does. No
 *  quotation marks around the question, since Claude Code puts the description in its own (`Agent "thread: How
 *  many…" finished`); straight ones inside it are curly. null
 *  for any other call, for a thread not listed, and when the call's prompt is not `thread:<name>`, which must stay to
 *  name the fork (backend threads.fork_ref). */
export function forkDescription(input: Record<string, unknown>, rows: readonly NamedRow[]): string | null {
  if (input.subagent_type !== 'fork') return null
  const ref = /^\s*thread:([A-Za-z0-9_-]{1,64})\s*$/
  const prompt = typeof input.prompt === 'string' ? ref.exec(input.prompt) : null
  if (!prompt || typeof input.description !== 'string' || !ref.test(input.description)) return null
  const q = questionWords(bySlug(rows, prompt[1]!)?.question)
  return q ? `thread: ${curlyQuotes(clip(q, 40))}` : null
}

/** main's end token: what it ends a turn with when it has nothing for the analyst, which no chat shows (session.py). */
export const END_TOKEN = '(shown in the dashboard)'
const END_RE = /[ \t]*[*_]*\(shown in the dashboard\)\.?[*_]*\.?\s*$/i

/** A reply block as the analyst reads it: without main's end token. */
export function withoutEnd(text: string): string {
  const m = END_RE.exec(text)
  return m ? text.slice(0, m.index).replace(/\s+$/, '') : text
}

// ------------------------------------------------------------------------------------------------ a citation's check

type Resolution = Obj & { error?: unknown; excerpt?: unknown; meta?: unknown; path?: unknown; line?: unknown; kind?: unknown; record?: unknown; context?: unknown; blocks?: unknown; end_line?: unknown }

/** The resolution of one ref out of what `thimble state resolve` printed: `{ref: resolution}`, a list of resolutions
 *  (each naming its `ref`), or `{refs: …}` around either. */
export function resolutionOf(v: unknown, ref: string): Resolution | null {
  const inner = isObj(v) && (isObj(v.refs) || Array.isArray(v.refs)) ? v.refs : v
  if (Array.isArray(inner)) {
    const hit = inner.find(x => isObj(x) && x.ref === ref)
    return isObj(hit) ? (hit as Resolution) : null
  }
  if (isObj(inner) && isObj(inner[ref])) return inner[ref] as Resolution
  return null
}

function blocksText(b: unknown): string {
  return Array.isArray(b) ? b.map(x => (isObj(x) ? str(x.text) : str(x))).join('\n') : ''
}

function recordText(r: unknown): string {
  if (!isObj(r)) return str(r)
  const blocks = blocksText(r.blocks)
  return blocks || str(r.text) || (isObj(r.record) ? JSON.stringify(r.record) : str(r.record))
}

/** Where the shown value stands in a line: each [start, end) of it. */
function spansIn(line: string, display: string | null): number[][] {
  const words = quotedWords(display) || (display ?? '').trim()
  if (!words) return []
  const out: number[][] = []
  const lower = line.toLowerCase()
  const w = words.toLowerCase()
  for (let i = lower.indexOf(w); i >= 0 && out.length < 4; i = lower.indexOf(w, i + w.length)) out.push([i, i + w.length])
  if (out.length) return out
  // a date in words (`23 June`) where the line writes it in digits (2026-06-23)
  const dates = dateSpans(words, line)
  if (dates.length) return dates.slice(0, 4)
  // a number written another way (3,908 against 3908): each number of the line that matches it
  for (const m of line.matchAll(/[-−]?\d[\d,]*(?:\.\d+)?%?/g)) if (shownMatches(m[0], words)) out.push([m.index!, m.index! + m[0].length])
  return out.slice(0, 4)
}

/** A value as one line of JSON written as Python writes it (`{"a": 1, "b": [2, 3]}`), the way a JSON lines file holds
 *  its records. */
export function jsonLine(v: unknown): string {
  if (Array.isArray(v)) return `[${v.map(jsonLine).join(', ')}]`
  if (isObj(v)) return `{${Object.entries(v).map(([k, x]) => `${JSON.stringify(k)}: ${jsonLine(x)}`).join(', ')}}`
  return JSON.stringify(v) ?? 'null'
}

/** A record around a cited one as one line, as Raw draws the file's lines: a JSON record as its line of JSON, a text
 *  line as its words. */
export function recordLine(r: unknown): string {
  if (!isObj(r)) return str(r).replace(/\s*\n\s*/g, ' ')
  const rec = r.record
  if (isObj(rec) && Object.keys(rec).length === 1 && typeof rec._raw === 'string') return rec._raw
  if (isObj(rec) && Object.keys(rec).length === 1 && typeof rec.text === 'string') return rec.text
  if (isObj(rec) || Array.isArray(rec)) return jsonLine(rec)
  return recordText(r).replace(/\s*\n\s*/g, ' ')
}

/** A record around a cited one as one line, drawn as the cited record is drawn: its words, as the file's reader shows
 *  them (a transcript's message, an event's params), when thimble reads words in it; else as Raw draws it (recordLine: a
 *  JSON record as its line of JSON). Live check term-fix10, low quirk: the cited line read as its words and the lines
 *  around it as raw JSON. */
export function aroundLine(r: unknown): string {
  const blocks = isObj(r) && Array.isArray(r.blocks) ? r.blocks.filter(isObj) : []
  const words = blocks.length && blocks.every(b => typeof b.kind === 'string' && b.kind !== 'raw') ? blocksText(blocks) : ''
  return words.trim() ? words.replace(/\s*\n\s*/g, ' ') : recordLine(r)
}

/** The lines of a resolved place, the cited ones hit (a record over its rows, at most 31), each record around them one
 *  line, drawn as the cited one is (aroundLine). */
function linesOf(res: Resolution, display: string | null): TermVerdict['lines'] {
  const out: TermVerdict['lines'] = []
  const line = typeof res.line === 'number' ? res.line : 0
  const ctx = isObj(res.context) ? res.context : {}
  const push = (n: number, text: string, hit: boolean) => {
    for (const [k, t] of text.split('\n').entries()) {
      if (k > 30) break
      out.push({ n: k === 0 ? n : 0, text: t, hit, ...(hit ? { spans: spansIn(t, display) } : {}) })
    }
  }
  const before = Array.isArray(ctx.before) ? ctx.before : []
  const after = Array.isArray(ctx.after) ? ctx.after : []
  const around = (n: number, r: unknown) => out.push({ n, text: aroundLine(r), hit: false })
  before.forEach((r, i) => around(isObj(r) && typeof r.line === 'number' ? r.line : line - before.length + i, r))
  if (Array.isArray(res.records) && res.records.length) res.records.forEach((r, i) => push(isObj(r) && typeof r.line === 'number' ? r.line : line + i, recordText(r), true))
  else push(line, line ? blocksText(res.blocks) || str(res.excerpt) : str(res.excerpt), true)
  after.forEach((r, i) => around(isObj(r) && typeof r.line === 'number' ? r.line : line + 1 + i, r))
  return out
}

/** A citation's check from its resolution: missing when the place does not resolve (or a card's cited cell or line is
 *  gone), differs when it resolves and its shown value (a number or quoted words) is not there, else ok. */
export function verdictOf(c: Citation, res: Resolution | null, at = 0): TermVerdict {
  const base = { ref: c.ref, display: c.display, kind: '', lines: [] as TermVerdict['lines'], at }
  if (!res) return { ...base, status: 'pending', why: 'not checked yet' }
  if (res.error !== undefined) return { ...base, status: 'missing', why: `the place does not resolve: ${str(res.error)}` }
  const kind = str(res.kind)
  const meta = isObj(res.meta) ? res.meta : {}
  const span = isObj(meta.span) ? meta.span : null
  const out: TermVerdict = { ...base, kind, status: 'ok', why: 'the place resolves', lines: [] }
  if (kind === 'cell') {
    out.card = str(res.cell_id)
    if (span && 'col' in span) {
      out.column = str(span.col)
      out.row = str(span.row)
      out.value = str(span.value)
    }
    if (meta.span_missing) return { ...out, status: 'missing', why: 'the card no longer shows the cited cell or line' }
    // lines the card printed: the cited ones lit among the two on each side the excerpt holds (refs.SPAN_CONTEXT_LINES)
    if (span && 'line' in span && typeof span.line === 'number') {
      const first = span.line
      const last = typeof span.end_line === 'number' ? span.end_line : first
      const start = Math.max(1, first - 2)
      out.lines = str(res.excerpt).split('\n').map((t, k) => {
        const n = start + k
        const hit = n >= first && n <= last
        // the value marked where it stands; a citation of the line with no words marks the line
        return { n, text: t, hit, ...(hit ? { spans: c.display === null ? [[0, t.length]] : spansIn(t, c.display) } : {}) }
      })
    }
  } else {
    out.path = str(res.path)
    if (typeof res.line === 'number') out.line = res.line
    out.lines = linesOf(res, c.display)
  }
  if (!showsValue(c.display)) return { ...out, why: 'the place resolves; the citation shows no value' }
  const where = span && 'value' in span ? str(span.value) : span && 'text' in span ? str(span.text) : kind === 'cell' ? str(res.excerpt) : out.lines.filter(l => l.hit).map(l => l.text).join('\n') || str(res.excerpt)
  const holds = span && 'value' in span ? shownMatches(str(span.value), c.display!) || valueIn(c.display!, where) : valueIn(c.display!, where)
  return holds ? { ...out, why: 'the value is at its place' } : { ...out, status: 'differs', why: span && 'value' in span ? `the place shows ${str(span.value)}` : 'the value is not at its place' }
}

// ------------------------------------------------------------------------------------------------ threads and agents

/** A chat's meta and events as `thimble state thread` printed them (`{meta, events}`). */
export function chatOf(v: unknown): { meta: Obj; events: Obj[] } {
  if (!isObj(v)) return { meta: {}, events: [] }
  return { meta: isObj(v.meta) ? v.meta : {}, events: Array.isArray(v.events) ? v.events.filter(isObj) : [] }
}

/** A chat as a side thread's turns: each analyst message a question, the text after it its answer, its tool calls
 *  counted, answered by its first reply (`reply_in_thread`'s `text` record, marked `reply`) or `done`, failed (or
 *  stopped) by `error`. In terminal mode main often answers with `reply_in_thread` alone, and no `done` follows. The
 *  answer is that first reply (SPEC.md, "The threads panel"): what the fork writes after it, as it makes a card, is its
 *  working, not the answer. Two texts a tool call or a whole message parts are two paragraphs, never one run of words.
 *  `cards`: the cards the turn made or changed, by its tool results' `cell_id`. */
export function threadOf(meta: Obj, events: readonly Obj[]): ChatThread {
  const turns: ChatThreadTurn[] = []
  let cur: ChatThreadTurn | null = null
  // a tool call since the turn's last text: the next text starts a paragraph
  let parted = false
  const open = (q: string) => {
    cur = { q, a: '', state: 'running', tools: 0, partial: '', cards: [] }
    turns.push(cur)
    parted = false
  }
  for (const e of events) {
    const t = str(e.type)
    if (t === 'user') {
      open(str(e.text))
      continue
    }
    if (t === 'again' && (!cur || (cur as ChatThreadTurn).state !== 'running')) open(str(e.text))
    if (!cur) open(str(meta.anchor_text) || str(meta.title))
    const c = cur as unknown as ChatThreadTurn
    if (t === 'text') {
      // words after an end that said the turn went unanswered (main's turn ended before its fork replied): the
      // answer, which replaces what the end said
      if (c.state === 'error') {
        c.state = 'running'
        c.a = ''
        delete c.stopped
      }
      // the answer is the turn's first reply: later words are the fork's working
      if (c.state === 'done') continue
      const words = str(e.delta ?? e.text)
      const whole = e.reply === true || Boolean(e.by)
      // the reply alone is the answer, without the working words before it
      if (e.reply === true) c.a = ''
      const sep = c.a.trim() && (parted || whole) ? '\n\n' : ''
      c.a = `${sep ? c.a.trimEnd() : c.a}${sep}${sep ? words.trimStart() : words}`
      c.partial = c.a
      parted = false
      if (e.reply === true && c.state === 'running') c.state = 'done'
    } else if (t === 'tool_use') {
      c.tools++
      parted = true
    } else if (t === 'tool_result') {
      const card = str(e.cell_id)
      if (card && !c.cards!.includes(card)) c.cards!.push(card)
    } else if (t === 'done') {
      c.state = 'done'
      if (!c.a.trim() && e.result) c.a = str(e.result)
    } else if (t === 'error') {
      c.state = 'error'
      c.a = str(e.error ?? e.message ?? e.text) || c.a
      if (STOP_KINDS.includes(str(e.kind))) c.stopped = true
    }
  }
  const last = turns.at(-1)
  if (last && last.state === 'running' && meta.running === false && last.a.trim()) last.state = 'done'
  const at = Date.parse(str(meta.last_ts) || str(meta.created_at))
  return {
    id: str(meta.id),
    label: str(meta.anchor_text) || str(meta.title) || 'the analyst\'s question',
    ref: str(meta.anchor),
    context: '',
    agentId: '',
    engine: '',
    turns,
    file: '',
    parent: str(meta.parent) === 'main' ? '' : str(meta.parent),
    ...(Number.isFinite(at) ? { at } : {}),
  }
}

/** How many answers a chat has given (`done` records), from its meta's count when the list gives one. */
function answersOf(meta: Obj): number {
  for (const k of ['answers', 'n_answers']) if (typeof meta[k] === 'number') return meta[k] as number
  return meta.status === 'done' ? 1 : 0
}

/** The side threads `thimble state threads` listed (the chats route's metas), oldest first, each with what the rows
 *  above the prompt and the home panel need. Unread: the meta's `unread`, else its answers past `seen`. */
export function threadRowsOf(v: unknown): TermThreadRow[] {
  const list = Array.isArray(v) ? v : isObj(v) && Array.isArray(v.chats) ? v.chats : isObj(v) && Array.isArray(v.threads) ? v.threads : []
  return list
    .filter(isObj)
    .filter(m => str(m.kind) === 'thread')
    .map(m => {
      const answers = answersOf(m)
      const seen = typeof m.seen === 'number' ? (m.seen as number) : answers
      const unread = typeof m.unread === 'number' ? (m.unread as number) : typeof m.unread === 'boolean' ? (m.unread ? 1 : 0) : Math.max(0, answers - seen)
      return {
        id: str(m.id),
        title: str(m.title),
        anchor: str(m.anchor),
        anchorText: str(m.anchor_text),
        running: Boolean(m.running),
        answers,
        seen,
        unread,
        at: str(m.last_ts) || str(m.created_at),
        parent: str(m.parent),
        created: str(m.created_at),
        element: str(m.anchor_element),
        question: str(m.question),
        fork: str(m.fork_name),
        turn: str(m.turn),
      }
    })
}

/** thimble's agents as `thimble state agents` listed them (the agents route's `{rows}`). */
export function agentsOf(v: unknown): TermAgent[] {
  const rows = Array.isArray(v) ? v : isObj(v) && Array.isArray(v.rows) ? v.rows : isObj(v) && Array.isArray(v.agents) ? v.agents : []
  return rows.filter(isObj).map(r => ({
    name: str(r.name),
    label: str(r.label) || str(r.name),
    state: str(r.state) || str(r.status),
    kind: str(r.kind),
    chat: str(r.chat),
    role: str(r.role),
    started: str(r.started ?? r.started_at ?? r.created_at),
  }))
}

/** The workspace's counts from `thimble state home`: a number or a list for each kind. */
export function homeOf(v: unknown, at = 0): TermHome | null {
  if (!isObj(v)) return null
  const counts = isObj(v.counts) ? v.counts : v
  const docs = counts.docs ?? counts.reports ?? counts.documents
  return {
    cards: num(counts.cards),
    labels: num(counts.labels),
    docs: isObj(docs) ? Object.values(docs).filter(d => !isObj(d) || d.exists !== false).length : num(docs),
    threads: num(counts.threads),
    views: num(counts.views),
    files: num(counts.files),
    at,
  }
}

/** The documents `thimble state docs` listed (the types route's `{slug: {exists, title, …}}`, or a list), those that
 *  exist or are being written. */
export function docsOf(v: unknown): { slug: string; title: string; renderer: string; status: string; generation: number; at: string }[] {
  const entries: [string, Obj][] = Array.isArray(v) ? v.filter(isObj).map(d => [str(d.slug ?? d.type), d]) : isObj(v) ? Object.entries(v).filter((e): e is [string, Obj] => isObj(e[1])) : []
  return entries
    .filter(([, d]) => d.exists !== false || d.status === 'generating')
    .map(([slug, d]) => ({ slug, title: str(d.title) || str(d.name) || slug, renderer: str(d.renderer) || 'document', status: str(d.status) || (d.exists === false ? 'generating' : 'written'), generation: typeof d.generation === 'number' ? d.generation : 0, at: str(d.generated_at) }))
}

/** One ui.jsonl record as `thimble state ui --after <n>` printed it. */
export type UiRecord = { n: number; kind: string; args: Obj }

export function uiRecordsOf(v: unknown): UiRecord[] {
  const list = Array.isArray(v) ? v : isObj(v) && Array.isArray(v.records) ? v.records : []
  return list.filter(isObj).map(r => ({ n: typeof r.n === 'number' ? r.n : 0, kind: str(r.kind), args: isObj(r.args) ? r.args : {} }))
}

// ------------------------------------------------------------------------------------------------ documents

export type DocSentence = { id?: string; text?: string; bullet?: string }
export type DocFigure = { cell?: string; caption?: string; after_paragraph?: string }
// a unit of a document: a report's or a story's section (paragraphs), a deck's slide or a story's beat (sentences, and
// one `figure` or a list of `figures`), as report_types.units reads them
export type DocSection = { id?: string; heading?: string; paragraphs?: { id?: string; sentences?: DocSentence[] }[]; sentences?: DocSentence[]; figures?: DocFigure[]; figure?: DocFigure | null }
const UNIT_KEYS = [['sections', 'section'], ['slides', 'slide'], ['beats', 'beat'], ['lines', 'line']] as const

/** The document's units (report_types.units) and their word, a slide's sentences as one paragraph each bullet a line. */
export function docUnits(doc: Obj): { units: DocSection[]; word: string } {
  for (const [key, word] of UNIT_KEYS) {
    const v = doc[key]
    if (!Array.isArray(v)) continue
    const units = (v as DocSection[]).filter(u => u && typeof u === 'object').map(u => {
      if (Array.isArray(u.paragraphs)) return { ...u, figures: u.figures ?? (u.figure ? [u.figure] : []) }
      const sentences = (u.sentences ?? []).map(x => ({ ...x, text: x.bullet ? `${x.bullet} ${String(x.text ?? '')}` : String(x.text ?? '') }))
      return { ...u, paragraphs: sentences.length ? [{ id: `${u.id ?? ''}-s`, sentences }] : [], figures: u.figures ?? (u.figure ? [u.figure] : []) }
    })
    return { units, word }
  }
  return { units: [], word: 'section' }
}

files.hooks/home.ts:
// The home panel (/thimble-home, and the title row's first step): one panel listing what this folder's sessions made,
// as thimble's workbench lists them in its tabs: views (built, building, proposed), reports, side threads (those with
// answers not yet read first), cards grouped by the question that made them, labels with their counts, and the files
// by folder with what this session read of them. Each is a click away from the panel that opens it. A file in the
// `listed` state counts neither its records nor its reading: it shows its kind and its size.
//
// This file lays the panel out as styled lines and their hit regions, without `$`; register.tsx gathers the data
// (homeData), draws the lines in the Client homeview.tsx and acts on a click or a key. It follows the visual system
// (SPEC.md, section 7, "Home"): one column under the title row's `Home`; a section heading bold with its count dim in
// parentheses and `N new` in green, a blank row above it; an item's state glyph at A0 and its name at A2, regular,
// its metadata dim against the right edge and `new` in green there while it is new; card groups and folders that fold
// with `▸ ▾`, the newest group and the first folder open. Each line starts with the 2-cell margin, where `❯` marks the
// row the keys chose.
import type { Line, Seg } from './draw'
import { lineWidth, share as pct, valueColour, width, wrapRows } from './draw'
import { FRESH, MARGIN_W, fitTo, headingLine, hintLines, pointed, ruleLine, spread } from './chrome'
import { COLORS } from './paint'
import { cutMiddle, quoted } from './lib'

export type SectionId = 'views' | 'reports' | 'threads' | 'cards' | 'labels' | 'files'

/** What a click opens: an item in its own panel, or a section's own panel. */
export type HomeOpen =
  | { kind: 'view'; slug: string; built: boolean }
  | { kind: 'report'; slug: string; title?: string }
  | { kind: 'thread'; id: string }
  | { kind: 'card'; id: string }
  | { kind: 'label'; name: string }
  | { kind: 'file'; path: string }
  | { kind: 'pane'; view: 'views' | 'reports' | 'threads' | 'labels' | 'coverage'; title: string; folder?: string }

/** A click's act: open something, fold or unfold a card group or a folder (`key`, `open` as it is drawn now), show a
 *  section whole. */
export type HomeAct = { op: 'open'; open: HomeOpen } | { op: 'fold'; key: string; open: boolean } | { op: 'more'; sec: SectionId; next?: string }

/** What the analyst chose: the groups and folders folded or unfolded against their default (the newest group and the
 *  first folder open), the sections shown whole, and the row the keys chose (its key). */
export type HomeUi = { folded: string[]; unfolded: string[]; more: string[]; pick: string }

export const HOME_UI_EMPTY: HomeUi = { folded: [], unfolded: [], more: [], pick: '' }

// ------------------------------------------------------------------------------------------------ the data

/** `term`: built with a terminal program (view.term.js), so the panel draws it (hooks/viewhost.ts). */
export type HomeView = { slug: string; name: string; state: string; words: string; files: string[]; unit: string; drawable: boolean; left: number; at: number; fresh?: boolean; term?: boolean }
export type HomeReport = { slug: string; title: string; form: string; state: string; cards: number; tools: number; at: number; fresh?: boolean }
export type HomeThread = { id: string; title: string; about: string; words: string; tone: string; unread: number; earlier: boolean; at: number }
/** `fresh`: made since home was last opened, `new` in green at R as every new item. */
export type HomeCard = { id: string; kind: string; question: string; fresh?: boolean }
/** Cards by the question they answered: an answer's prompt, a side thread's question, a report's title, or none. */
export type HomeCardGroup = { head: string; from: 'answer' | 'thread' | 'report' | 'other'; cards: HomeCard[]; at: number }
/** `ran`: whether the label has a run, as its panel's `last run on …` or `not run yet` says (a label a stopped thread
 *  left is none); absent is true. */
export type HomeLabel = { slug: string; name: string; kind: string; trial: boolean; counts: Record<string, number>; values: string[]; paths: string[]; running: boolean; ran?: boolean; state?: string; fresh?: boolean; colors?: Record<string, number> }
/** thimble-term: a file whose reading thimble does not count (`listed`) has no state glyph and shows its kind. */
export type HomeFile = { file: string; records: number | null; size: number; seen: number; state: 'read' | 'scanned' | 'untouched' | 'listed'; ranges: number[][]; kind?: string }
export type HomeData = {
  views: HomeView[]
  reports: HomeReport[]
  threads: HomeThread[]
  cardGroups: HomeCardGroup[]
  labels: HomeLabel[]
  files: HomeFile[]
  coverage: string
  /** the folder's own name, which heads the files at its top */
  root?: string
}

/** The cards of answers, threads and reports, each under the first question that made it (`groups` in the order the
 *  questions were asked), then the cards no question names. A group whose cards all stand under an earlier one is
 *  left out. Newest first. */
export function groupCards(groups: readonly HomeCardGroup[], all: readonly HomeCard[]): HomeCardGroup[] {
  const placed = new Set<string>()
  const out: HomeCardGroup[] = []
  for (const g of [...groups].sort((a, b) => a.at - b.at)) {
    const cards = g.cards.filter(c => !placed.has(c.id))
    for (const c of cards) placed.add(c.id)
    if (cards.length) out.push({ ...g, cards })
  }
  const rest = all.filter(c => !placed.has(c.id))
  const sorted = out.reverse()
  if (rest.length) sorted.push({ head: 'other cards', from: 'other', cards: rest, at: 0 })
  return sorted
}

// ------------------------------------------------------------------------------------------------ the rows

type Glyph = { mark: string; fg?: string }

/** One row of a section: its glyph (or fold marker) at A0, its name at A2 (or A4 under a folder), its metadata dim
 *  against the right edge, `new` in green there, a bar before the figure; a secondary row at A2; what a click does. A
 *  row with `kids` folds (`fold`: its key, `open`: shown open). */
export type HomeRow = {
  key: string
  glyph: Glyph | null
  title: string
  /** dim words right after the title (a folder's count of files) */
  after?: Seg[]
  /** what stands at R in place of `right` when `right` would cut the title (a thread's row without its subject) */
  short?: Seg[]
  /** cut in its middle, so its end shows: a card of a group whose questions share their first words (lib.ts cutMiddle) */
  middle?: boolean
  fresh?: boolean
  right?: Seg[]
  bar?: { n: number; fg: string }[]
  meta?: Seg[]
  kids?: HomeRow[]
  fold?: string
  open?: boolean
  depth?: number
  more?: number
  act: HomeAct
}

/** A section: its heading's name and count, what is new, the panel its heading opens, the column heads at the right,
 *  and its rows. `summary` says in words what the glyphs show (for the tests and a thread about the panel). */
export type HomeSection = { id: SectionId; name: string; count: number; news?: number; heads?: Seg[]; summary: Seg[]; rows: HomeRow[]; pane?: HomeOpen; coverage?: string }

// state glyphs (SPEC.md, "The visual system", section 5): done ● and working ◌ in the text colour, not started ○
// dim, a problem × or ! in red
const DONE: Glyph = { mark: '●' }
const WORKING: Glyph = { mark: '◌' }
const NOT_STARTED: Glyph = { mark: '○', fg: COLORS.dim }

export function num(n: number): string {
  return Math.round(n).toLocaleString('en-US')
}

function plural(n: number, one: string, many = `${one}s`): string {
  return `${num(n)} ${n === 1 ? one : many}`
}

const dim = (s: string): Seg => ({ s, fg: COLORS.dim })

/** Words parted by a dim dot, each dim unless it is a segment of its own. */
function joined(parts: (Seg | string | null | undefined | false)[]): Seg[] {
  const out: Seg[] = []
  for (const p of parts) {
    if (!p) continue
    if (out.length) out.push(dim(' · '))
    out.push(typeof p === 'string' ? dim(p) : p)
  }
  return out
}

const ACTIVE_VIEW = new Set(['building', 'checking', 'reviewing', 'revising'])

function viewGlyph(v: HomeView): Glyph {
  if (v.state === 'failed') return { mark: '×', fg: COLORS.problem }
  if (v.left) return { mark: '!', fg: COLORS.problem }
  if (ACTIVE_VIEW.has(v.state)) return WORKING
  if (v.state === 'built' || (v.state === 'stopped' && v.drawable)) return DONE
  return NOT_STARTED
}

/** A view's state words where its glyph already says what they would: without "built", "proposed", "not built" or
 *  "failed". */
function afterMark(words: string): string {
  return words.replace(/^(built|proposed|not built)(\s·\s|$)/, '').replace(/^failed:\s*/, '')
}

function countBy(words: readonly string[], order: readonly string[]): string[] {
  const by = new Map<string, number>()
  for (const w of words) by.set(w, (by.get(w) ?? 0) + 1)
  return order.filter(w => by.has(w)).map(w => `${by.get(w)} ${w}`)
}

/** What stands against the right edge: the metadata dim, then `new` in green while the item is new. */
function rightOf(meta: (string | null | undefined | false)[], fresh?: boolean): Seg[] {
  const m = joined(meta)
  return [...m, ...(fresh ? [...(m.length ? [{ s: '  ' }] : []), { s: 'new', fg: FRESH }] : [])]
}

function viewsSection(vs: readonly HomeView[]): HomeSection {
  const sorted = [...vs].sort((a, b) => b.at - a.at)
  const word = (v: HomeView) => (v.state === 'failed' ? 'failed' : v.state === 'built' || (v.state === 'stopped' && v.drawable) ? 'built' : ACTIVE_VIEW.has(v.state) ? (v.drawable ? 'built' : 'building') : 'proposed')
  return {
    id: 'views',
    name: 'Views',
    count: vs.length,
    news: vs.filter(v => v.fresh).length,
    summary: joined(countBy(sorted.map(word), ['built', 'building', 'proposed', 'failed'])),
    pane: { kind: 'pane', view: 'views', title: 'Views' },
    rows: sorted.map(v => ({
      key: `view:${v.slug}`,
      glyph: viewGlyph(v),
      title: v.name,
      fresh: v.fresh,
      right: rightOf([v.files.join(', '), afterMark(v.words)], v.fresh),
      // without its files where they would cut its name
      short: rightOf([afterMark(v.words)], v.fresh),
      act: { op: 'open', open: { kind: 'view', slug: v.slug, built: v.drawable } },
    })),
  }
}

function reportsSection(rs: readonly HomeReport[]): HomeSection {
  const sorted = [...rs].sort((a, b) => b.at - a.at)
  const word = (r: HomeReport) => (r.state === 'writing' ? 'writing' : r.state === 'error' ? 'failed' : 'written')
  return {
    id: 'reports',
    // the browser's word for them, which the list panel and the path use too
    name: 'Documents',
    count: rs.length,
    news: rs.filter(r => r.fresh).length,
    summary: joined(countBy(sorted.map(word), ['written', 'writing', 'failed'])),
    pane: { kind: 'pane', view: 'reports', title: 'Documents' },
    rows: sorted.map(r => ({
      key: `report:${r.slug}`,
      glyph: r.state === 'writing' ? WORKING : r.state === 'error' ? { mark: '×', fg: COLORS.problem } : DONE,
      title: r.title,
      fresh: r.fresh,
      // what the glyph does not say (◌ writing, × failed, ● written): its kind, its tool calls while writing, its cards
      right: rightOf([r.form, r.state === 'writing' && r.tools ? plural(r.tools, 'tool call') : '', r.cards ? plural(r.cards, 'card') : ''], r.fresh),
      act: { op: 'open', open: { kind: 'report', slug: r.slug, title: r.title } },
    })),
  }
}

function threadsSection(ts: readonly HomeThread[]): HomeSection {
  // the threads with answers not yet read first, then the newest
  const sorted = [...ts].sort((a, b) => Number(b.unread > 0) - Number(a.unread > 0) || b.at - a.at)
  const fresh = ts.filter(t => t.unread).length
  const running = ts.filter(t => t.tone === 'run').length
  return {
    id: 'threads',
    name: 'Threads',
    count: ts.length,
    news: fresh,
    summary: joined([fresh ? `${fresh} with new answers` : '', running ? `${running} answering` : '', ts.some(t => t.earlier) ? `${ts.filter(t => t.earlier).length} from earlier sessions` : '']),
    pane: { kind: 'pane', view: 'threads', title: 'Threads' },
    rows: sorted.map(t => ({
      key: `thread:${t.id}`,
      glyph: t.tone === 'run' ? WORKING : t.tone === 'problem' ? { mark: '×', fg: COLORS.problem } : t.tone === 'ok' || t.unread ? DONE : NOT_STARTED,
      title: t.title,
      fresh: t.unread > 0,
      // what it is about, then `earlier session`, dim at R (on its one row); without its subject when that would cut
      // its question
      right: rightOf([t.about, t.earlier ? 'earlier session' : ''], t.unread > 0),
      short: rightOf([t.earlier ? 'earlier session' : ''], t.unread > 0),
      act: { op: 'open', open: { kind: 'thread', id: t.id } },
    })),
  }
}

/** What a group of cards holds, in words: the question it answered, the report or the thread it stands in. */
function groupName(g: HomeCardGroup): string {
  const head = g.head.replace(/\s+/g, ' ').trim()
  if (g.from === 'answer') return `answer to ${quoted(head)}`
  if (g.from === 'report') return `in the report ${quoted(head)}`
  if (g.from === 'thread') return `in the thread ${/^["“]/.test(head) ? head : quoted(head)}`
  return head
}

/** The fewest characters of first words a group's questions share before its rows are cut in their middle. */
const SHARED_HEAD = 16

/** Whether two or more questions share their first SHARED_HEAD characters or more, whole words, and differ after. */
function sharedHead(qs: readonly string[]): boolean {
  if (qs.length < 2) return false
  let n = 0
  const first = qs[0]!
  while (n < first.length && qs.every(q => q[n] === first[n])) n++
  const head = first.slice(0, n)
  const words = head.includes(' ') ? head.slice(0, head.lastIndexOf(' ')) : ''
  return words.length >= SHARED_HEAD && qs.some(q => q !== first)
}

function cardsSection(groups: readonly HomeCardGroup[], ui: HomeUi): HomeSection {
  const n = groups.reduce((k, g) => k + g.cards.length, 0)
  const by = (from: HomeCardGroup['from']) => groups.filter(g => g.from === from).reduce((k, g) => k + g.cards.length, 0)
  return {
    id: 'cards',
    name: 'Cards',
    count: n,
    news: groups.reduce((k, g) => k + g.cards.filter(c => c.fresh).length, 0),
    summary: joined([by('answer') ? `${num(by('answer'))} in answers` : '', by('thread') ? `${num(by('thread'))} in side threads` : '', by('report') ? `${num(by('report'))} in reports` : '']),
    rows: groups.map((g, i) => {
      const fold = `cards:${g.from}:${g.head}`
      const open = isOpen(ui, fold, i === 0)
      return {
        key: `group:${fold}`,
        glyph: { mark: open ? '▾' : '▸' },
        title: groupName(g),
        right: [dim(plural(g.cards.length, 'card'))],
        fold,
        open,
        kids: g.cards.map(c => ({ key: `card:${c.id}`, glyph: null, title: c.question, fresh: c.fresh, right: rightOf([c.kind], c.fresh), ...(sharedHead(g.cards.map(x => x.question)) ? { middle: true } : {}), act: { op: 'open', open: { kind: 'card', id: c.id } } })),
        act: { op: 'fold', key: fold, open },
      }
    }),
  }
}

/** The cells a label's bar takes at most, and the fewest it is drawn in: a narrower bar is left out. */
const BAR_W = 20
const BAR_MIN = 6
/** The cells of a row's name a bar leaves it at least, or the whole name when it is shorter: a name is cut at a word,
 *  so a bar that left it fewer cells cut most names to their first word. */
const NAME_KEEP = 24

/** A label's counts, each value with its colour as the label panel draws it (draw.ts valueColour): the bar's parts,
 *  their cells set when the row is laid out at its width (barCells). */
function countBar(values: readonly string[], counts: Record<string, number>, colors?: Record<string, number>): { n: number; fg: string }[] {
  return values.map(v => ({ n: counts[v] ?? 0, fg: valueColour(values, v, colors)! })).filter(x => x.n > 0)
}

/** A bar's parts in `w` cells by their counts, the cells left over given to the largest remainders, so the bar is `w`
 *  wide. */
function barCells(parts: readonly { n: number; fg: string }[], w: number): { n: number; fg: string }[] {
  const total = parts.reduce((k, p) => k + p.n, 0)
  if (!total || w <= 0) return []
  const cells = parts.map(p => (p.n * w) / total)
  const out = cells.map(c => Math.floor(c))
  const order = cells.map((c, i) => ({ i, r: c - Math.floor(c) })).sort((a, b) => b.r - a.r)
  for (let k = 0, left = w - out.reduce((a, b) => a + b, 0); k < left; k++) out[order[k % order.length]!.i]!++
  return parts.map((p, i) => ({ n: out[i]!, fg: p.fg })).filter(x => x.n > 0)
}

/** A label's color, as the label panel's ● beside its name shows it: its first value's (its class's color when it has
 *  `colors`), else the first series hue. */
export function labelHue(values: readonly string[], colors?: Record<string, number>): string {
  const hue = values.length ? valueColour(values, values[0]!, colors) : undefined
  return hue && hue !== COLORS.dim ? hue : COLORS.series[0]!
}

function labelsSection(ls: readonly HomeLabel[]): HomeSection {
  return {
    id: 'labels',
    name: 'Labels',
    count: ls.length,
    // the labels new since home was last seen, as the toast counts them (live check term-fix9, low quirk)
    news: ls.filter(l => l.fresh).length,
    summary: joined(countBy(ls.map(l => (l.running ? 'running' : l.ran === false ? (l.state?.startsWith('stopped') ? 'stopped' : 'not run yet') : l.trial ? 'on a sample' : 'on every record')), ['on every record', 'on a sample', 'running', 'stopped', 'not run yet'])),
    pane: { kind: 'pane', view: 'labels', title: 'Labels' },
    rows: ls.map(l => {
      const labeled = l.values.reduce((k, v) => k + (l.counts[v] ?? 0), 0)
      // a label with no run says so, as its panel does, with no bar and no counts (live check term-fix7, new quirk 6:
      // home showed `yes 0 · no 0` and 0 for a label a stopped thread left)
      // one whose first run is going says so (no counts yet)
      if (l.ran === false && !labeled)
        return {
          key: `label:${l.slug}`,
          glyph: l.running ? WORKING : NOT_STARTED,
          title: l.name,
          fresh: l.fresh,
          right: rightOf([l.running ? 'labeling' : 'not run yet'], l.fresh),
          meta: joined([l.kind, l.paths.join(', ')]),
          act: { op: 'open', open: { kind: 'label', name: l.name } },
        }
      // a legend: each value's ● in its hue, its word and count dim as the rest of the secondary row
      const legend: Seg[] = []
      l.values.forEach((v, i) => {
        if (i) legend.push(dim('  '))
        legend.push({ s: '● ', fg: valueColour(l.values, v, l.colors) }, dim(`${v} ${num(l.counts[v] ?? 0)}`))
      })
      // what its runs say: a run going (`◌ labeling 3,000 of 4,579`), a first run stopped part way (`stopped at 3,150 of
      // 4,579`), else what the last run covered (live check term-fix9, quirk 4)
      const runWords = l.state || (l.trial ? `a sample of ${num(labeled)}` : 'every record')
      return {
        key: `label:${l.slug}`,
        // its ● in the label's color, as the label panel draws it beside its name
        glyph: l.running ? WORKING : { mark: '●', fg: labelHue(l.values, l.colors) },
        title: l.name,
        fresh: l.fresh,
        bar: countBar(l.values, l.counts, l.colors),
        right: [{ s: num(labeled) }, ...(l.fresh ? [{ s: '  ' }, { s: 'new', fg: FRESH }] : [])],
        meta: [...joined([l.kind, runWords, l.paths.join(', ')]), dim('  '), ...legend],
        act: { op: 'open', open: { kind: 'label', name: l.name } },
      }
    }),
  }
}

/** A share of records read, in whole percent as every share (draw.ts share). */
function share(seen: number, total: number): string {
  if (!total || !seen) return ''
  return pct(seen, total)
}

/** thimble-term: a size in words (`756 KB`), for a file whose records are not counted. */
function sizeWords(n: number): string {
  return n >= 1e9 ? `${(n / 1e9).toFixed(1)} GB` : n >= 1e6 ? `${(n / 1e6).toFixed(1)} MB` : n >= 1e3 ? `${Math.round(n / 1e3)} KB` : `${n} B`
}

/** The files at most an open folder lists before `… N more`. */
const FOLDER_FILES = 20

function filesSection(fs: readonly HomeFile[], root: string, ui: HomeUi): HomeSection {
  const by = new Map<string, HomeFile[]>()
  // a folder by the name the file browser gives it: its path in the corpus (`collusion-wiki/`), and the corpus's own
  // files under the corpus folder's name
  for (const f of fs) {
    const cut = f.file.lastIndexOf('/')
    const folder = cut < 0 ? `${root}/` : `${f.file.slice(0, cut)}/`
    by.set(folder, [...(by.get(folder) ?? []), f])
  }
  // the corpus's own folder first, the others in natural order, as the file browser lists them
  const top = `${root}/`
  const folders = [...by.entries()].sort(([a], [b]) => (a === b ? 0 : a === top ? -1 : b === top ? 1 : a.localeCompare(b, undefined, { numeric: true })))
  const recs = (xs: readonly HomeFile[]) => xs.reduce((k, f) => k + (f.records ?? 0), 0)
  const seen = (xs: readonly HomeFile[]) => xs.reduce((k, f) => k + Math.min(f.seen, f.records ?? 0), 0)
  const cols = (records: string, read: string): Seg[] => [{ s: records }, { s: '  ' }, dim(read)]
  // thimble-term: where no reading is counted, the columns are the files' kind (text, left) then size (a number, on R)
  const listed = fs.length > 0 && fs.every(f => f.state === 'listed')
  return {
    id: 'files',
    name: 'Files',
    count: fs.length,
    heads: listed ? [dim('type'), { s: '  ' }, dim('size')] : [dim('records'), { s: '  ' }, dim('read')],
    summary: joined([fs.length && !listed ? `${num(fs.filter(f => f.state === 'read').length)} of ${num(fs.length)} read` : '']),
    pane: { kind: 'pane', view: 'coverage', title: 'Coverage' },
    rows: folders.map(([folder, files], i) => {
      const fold = `files:${folder}`
      const open = isOpen(ui, fold, i === 0)
      const sorted = [...files].sort((a, b) => a.file.localeCompare(b.file, undefined, { numeric: true }))
      return {
        key: `folder:${folder}`,
        glyph: { mark: open ? '▾' : '▸' },
        title: folder,
        // its count of files dim after its name, as the file browser shows it; under the columns only what they head
        after: [dim(`  ${num(files.length)}`)],
        right: listed ? [{ s: '' }, { s: '  ' }, dim(sizeWords(files.reduce((k, f) => k + f.size, 0)))] : cols(num(recs(files)), share(seen(files), recs(files)) || '0%'),
        fold,
        open,
        // a folder of 21 shows all 21: `… 1 more` would take the row the file takes
        more: sorted.length > FOLDER_FILES + 1 ? sorted.length - FOLDER_FILES : 0,
        kids: sorted.slice(0, sorted.length > FOLDER_FILES + 1 ? FOLDER_FILES : sorted.length).map(f => ({
          key: `file:${f.file}`,
          // a listed file has no state glyph: a blank in its place keeps its name at A4
          glyph: f.state === 'listed' ? { mark: ' ' } : f.state === 'read' ? DONE : NOT_STARTED,
          title: f.file.split('/').at(-1) ?? f.file,
          right: f.state === 'listed' ? [dim(f.kind ?? ''), { s: '  ' }, dim(sizeWords(f.size))] : cols(f.records !== null ? num(f.records) : `${num(f.size)} B`, f.state === 'read' ? share(f.seen, f.records ?? 0) || '0%' : f.state === 'scanned' ? 'counted' : ''),
          act: { op: 'open', open: { kind: 'file', path: f.file } } as HomeAct,
        })),
        act: { op: 'fold', key: fold, open },
      }
    }),
  }
}

/** Whether a group or folder shows open: its default unless the analyst folded or unfolded it. */
function isOpen(ui: HomeUi, key: string, byDefault: boolean): boolean {
  return byDefault ? !ui.folded.includes(key) : ui.unfolded.includes(key)
}

/** Every section, in the order of thimble's workbench: what it built, what it wrote, what it asked, then its parts. */
export function homeSections(d: HomeData, ui: HomeUi = HOME_UI_EMPTY): HomeSection[] {
  return [viewsSection(d.views), reportsSection(d.reports), threadsSection(d.threads), cardsSection(d.cardGroups, ui), labelsSection(d.labels), { ...filesSection(d.files, d.root || 'folder', ui), ...(d.coverage ? { coverage: d.coverage } : {}) }]
}

// ------------------------------------------------------------------------------------------------ the layout

/** A region a click acts on: its line, its cells, and whether the pointer lights its row (else it is a control, which
 *  the pointer inverts). `pick`: the key of the row it stands for, which the keys step through. */
export type HomeHit = { y: number; x0: number; x1: number; row: boolean; act: HomeAct; pick?: string }
/** `hintRows`: how many of its last lines are the key hints (chrome.ts hintLines); `heads`: the line of each section's
 *  heading. */
export type HomeLayout = { lines: Line[]; hits: HomeHit[]; picks: { key: string; act: HomeAct }[]; hintRows: number; heads: number[] }

/** The items a section shows before `… N more` (card groups and folders count as items). */
export const FIRST = 5

export const HOME_HINTS = ['↑↓ to choose', 'Enter to open', 'Space to fold', 'x to close']

class Lines {
  lines: Line[] = []
  hits: HomeHit[] = []
  picks: HomeLayout['picks'] = []
  constructor(readonly pick: string) {}
  /** A line of the type area, its margin before it: `❯` when it is the row the keys chose. */
  push(l: Line, hit?: Omit<HomeHit, 'y'>): void {
    const on = Boolean(hit?.pick) && hit!.pick === this.pick
    if (hit) this.hits.push({ ...hit, x0: hit.x0 + MARGIN_W, x1: hit.x1 + MARGIN_W, y: this.lines.length })
    if (hit?.pick) this.picks.push({ key: hit.pick, act: hit.act })
    this.lines.push(pointed(l, on))
  }
  blank(): void {
    if (this.lines.length && lineWidth(this.lines.at(-1)!) > MARGIN_W) this.lines.push([])
  }
}

/** The two cells a glyph or fold marker hangs in, or two spaces. */
function glyphSeg(g: Glyph | null): Seg[] {
  if (!g) return [{ s: '  ' }]
  return [{ s: g.mark, ...(g.fg ? { fg: g.fg } : {}) }, { s: ' ' }]
}

/** The fewest cells of a row's title kept beside its full right part (itemLine). */
const TITLE_MIN = 32

/** An item's line at `x`: its glyph hanging, its name, its bar and figure against the right edge. The bar takes what
 *  the name leaves (NAME_KEEP cells of it, or all of a shorter one), up to BAR_W cells, and is left out under BAR_MIN:
 *  in a narrow pane the name stays readable (live check term-fix10, new quirk 6: `● age…  ████████████████████  1,900`). */
function itemLine(row: HomeRow, x: number, w: number): Line {
  const lead: Line = [...(x ? [{ s: ' '.repeat(x) }] : []), ...glyphSeg(row.glyph)]
  const barRoom = w - lineWidth(lead) - Math.min(NAME_KEEP, width(row.title)) - lineWidth(row.after ?? []) - 2 - lineWidth(row.right ?? []) - 2
  const barW = Math.min(BAR_W, barRoom)
  const bar: Line = row.bar?.length && barW >= BAR_MIN ? [...barCells(row.bar, barW).map(b => ({ s: '█'.repeat(b.n), fg: b.fg })), { s: '  ' }] : []
  const left: Line = [...lead, { s: row.title }, ...(row.after ?? [])]
  // the full right part (a thread's subject) whenever the title keeps TITLE_MIN cells beside it, the title cut at a word
  // to make room; else the shorter right part (live check term-fix6, quirk 10: `about 602` was left out beside a long
  // question)
  const full: Line = [...bar, ...(row.right ?? [])]
  const room = w - lineWidth(full) - 2 - (lineWidth(left) - width(row.title))
  const chosen = row.short && lineWidth(left) + 2 + lineWidth(full) > w && room < Math.min(TITLE_MIN, width(row.title)) ? [...bar, ...row.short] : full
  // the right part never takes the title's first cells: it is cut where it would leave the title fewer than 12
  const keep = Math.min(width(row.title), 12) + lineWidth(left) - width(row.title)
  const right = lineWidth(chosen) + 2 + keep > w ? fitTo(chosen, Math.max(0, w - 2 - keep)) : chosen
  // a row whose end tells it from the rows beside it, cut in its middle
  if (row.middle) {
    const fit = w - lineWidth(right) - 2 - (lineWidth(left) - width(row.title))
    if (fit > 0 && width(row.title) > fit) return spread([...lead, { s: cutMiddle(row.title, fit) }, ...(row.after ?? [])], right, w)
  }
  return spread(left, right, w)
}

/** The figures of a section's rows set in shared columns: each row's right part padded so its last column ends on R
 *  and the columns before it line up (the files' records and share). */
function alignRight(sec: HomeSection): void {
  if (sec.id !== 'files') return
  const rows = sec.rows.flatMap(r => [r, ...(r.kids ?? [])])
  // the files' right parts are [count?, gap, records, gap, read]: pad records and read to their columns
  const parts = rows.map(r => r.right ?? [])
  const first = sec.heads?.[0]?.s.trim() || 'records'
  const recW = Math.max(width(first), ...parts.map(p => width(p.at(-3)?.s ?? '')))
  const readW = Math.max(width(sec.heads?.at(-1)?.s.trim() || 'read'), ...parts.map(p => width(p.at(-1)?.s ?? '')))
  // text aligns left, numbers right: a listed file's kind is text (its first column), its size a number
  const textFirst = first === 'type'
  for (const r of rows) {
    const p = r.right ?? []
    if (p.length < 3) continue
    const rec = p.at(-3)!
    const read = p.at(-1)!
    r.right = [...p.slice(0, -3), { ...rec, s: textFirst ? rec.s.padEnd(recW) : rec.s.padStart(recW) }, { s: '  ' }, { ...read, s: read.s.padStart(readW) }]
  }
  const last = sec.heads?.at(-1)?.s.trim() || 'read'
  sec.heads = [dim(textFirst ? first.padEnd(recW) : first.padStart(recW)), { s: '  ' }, dim(last.padStart(readW))]
}

/** A row without `new` in a section where some row has it: its right part ends where the others' words end, before the
 *  cells `new` takes (live check term-fix9, low quirk: `table  new` beside `table` put the kinds in two columns). */
function besideNew(r: HomeRow): HomeRow {
  const pad = (xs: Seg[] | undefined) => (xs?.length ? [...xs, { s: ' '.repeat(NEW_W) }] : xs)
  return r.fresh ? r : { ...r, right: pad(r.right), short: pad(r.short) }
}
const NEW_W = '  new'.length

/** The cells of a file's name the type column never cuts: a name up to this long is whole beside the column, or the
 *  column goes. */
export const NAME_WHOLE = 32

/** The files section without its type column, when beside it a file's name (up to NAME_WHOLE cells) would be cut (live
 *  check term-fix10, new quirk 6: `agent-c…` beside the column); else as it is. */
function withoutType(sec: HomeSection, w: number): HomeSection {
  if (sec.id !== 'files' || sec.heads?.[0]?.s.trim() !== 'type') return sec
  const files = sec.rows.flatMap(r => r.kids ?? [])
  const longest = Math.max(0, ...files.map(f => width(f.title)))
  const rightW = Math.max(0, ...files.map(f => lineWidth(f.right ?? [])))
  if (w - 4 - 2 - rightW >= Math.min(NAME_WHOLE, longest)) return sec
  const sizeOnly = (r: HomeRow): HomeRow => ({ ...r, ...(r.right && r.right.length >= 3 ? { right: [...r.right.slice(0, -3), r.right.at(-1)!] } : {}), ...(r.kids ? { kids: r.kids.map(sizeOnly) } : {}) })
  return { ...sec, heads: sec.heads.slice(-1), rows: sec.rows.map(sizeOnly) }
}

function sectionLines(out: Lines, sec: HomeSection, ui: HomeUi, w: number): void {
  alignRight(sec)
  sec = withoutType(sec, w)
  if (sec.rows.some(r => r.fresh || (r.open && r.kids?.some(k => k.fresh)))) sec = { ...sec, rows: sec.rows.map(r => ({ ...besideNew(r), ...(r.kids ? { kids: r.kids.map(besideNew) } : {}) })) }
  const head = headingLine(sec.name, sec.count, sec.news ?? 0)
  out.push(spread(head, sec.heads ?? [], w), sec.pane ? { x0: 0, x1: lineWidth(head), row: false, act: { op: 'open', open: sec.pane } } : undefined)
  // the orientation's coverage line, dim under the Files heading, whole up to four rows
  if (sec.coverage) for (const l of wrapRows(sec.coverage, Math.max(10, w - 2), 4)) out.push([{ s: '  ' }, dim(l)])
  if (!sec.rows.length) {
    out.push([{ s: '  ' }, dim('none')])
    return
  }
  const whole = ui.more.includes(sec.id) || sec.rows.length <= FIRST + 1
  const shown = whole ? sec.rows : sec.rows.slice(0, FIRST)
  for (const r of shown) {
    out.push(itemLine(r, 0, w), { x0: 0, x1: w, row: true, act: r.act, pick: r.key })
    if (r.meta?.length) out.push([{ s: '  ' }, ...fitTo(r.meta, w - 2)], { x0: 0, x1: w, row: true, act: r.act })
    if (r.kids && r.open) {
      // a group's cards at A2 under its name; a folder's files with their glyphs at A2 and their names at A4
      for (const k of r.kids) out.push(itemLine(k, k.glyph ? 2 : 0, w), { x0: 2, x1: w, row: true, act: k.act, pick: k.key })
      // a folder's `… N more` is a row the keys choose too: Enter shows the folder whole in the file browser
      if (r.more) out.push([{ s: '    ' }, dim(`… ${num(r.more)} more`)], { x0: 4, x1: 4 + width(`… ${num(r.more)} more`), row: false, act: { op: 'open', open: { kind: 'pane', view: 'coverage', title: 'Coverage', folder: r.title } }, pick: `more:${r.key}` })
    }
  }
  // the section's `… N more` is a row the keys choose: Enter or Space shows the section whole, the choice on its first
  // row shown then (live check term-fix9, quirk 6: ↑↓ skipped it, so two groups of 18 cards could not be reached)
  const left = sec.rows.length - shown.length
  if (left > 0) out.push([{ s: '  ' }, dim(`… ${num(left)} more`)], { x0: 2, x1: 2 + width(`… ${num(left)} more`), row: false, act: { op: 'more', sec: sec.id, next: sec.rows[shown.length]!.key }, pick: `more:${sec.id}` })
}

/** The whole panel below its title row (`Home`, the path's one step): the rule, every section, the key hints
 *  (`hints`: HOME_HINTS while the panel holds the keys, else what gives it them). */
export function homeLayout(d: HomeData, ui: HomeUi, w: number, hints: readonly string[] = HOME_HINTS): HomeLayout {
  const sections = homeSections(d, ui)
  // the row the keys chose: the one named, else the first
  const first = sections.flatMap(s => s.rows.slice(0, 1).map(r => r.key))[0] ?? ''
  const out = new Lines(ui.pick || first)
  out.push(ruleLine(w))
  const heads: number[] = []
  sections.forEach((sec, i) => {
    if (i) out.blank()
    heads.push(out.lines.length)
    sectionLines(out, sec, ui, w)
  })
  const hintRows = hintLines(hints, w)
  for (const l of hintRows) out.push(l)
  return { lines: out.lines, hits: out.hits, picks: out.picks, hintRows: hintRows.length, heads }
}

/** The UI state after an act that changes it (an act that opens something leaves it as it is). */
export function homeReduce(ui: HomeUi, act: HomeAct): HomeUi {
  const without = (xs: string[], x: string) => xs.filter(y => y !== x)
  switch (act.op) {
    case 'fold':
      return act.open ? { ...ui, folded: [...without(ui.folded, act.key), act.key], unfolded: without(ui.unfolded, act.key) } : { ...ui, folded: without(ui.folded, act.key), unfolded: [...without(ui.unfolded, act.key), act.key] }
    case 'more':
      return { ...ui, more: ui.more.includes(act.sec) ? without(ui.more, act.sec) : [...ui.more, act.sec] }
    default:
      return ui
  }
}

/** The row the keys choose after `key` (up or down, home or end), from the layout's rows in order. */
export function homePick(lay: HomeLayout, ui: HomeUi, key: string): string {
  const keys = lay.picks.map(p => p.key)
  if (!keys.length) return ui.pick
  const at = Math.max(0, keys.indexOf(ui.pick || keys[0]!))
  const to = key === 'up' || key === 'k' ? at - 1 : key === 'down' || key === 'j' ? at + 1 : key === 'home' ? 0 : key === 'end' ? keys.length - 1 : at
  return keys[Math.max(0, Math.min(keys.length - 1, to))]!
}

/** The lines as plain text, for the tests: without the margin's two cells. */
export function plainLines(lines: readonly Line[]): string[] {
  return lines.map(l => l.map(s => s.s).join('').slice(MARGIN_W).replace(/\s+$/, ''))
}

files.hooks/kept.ts:
// What main's chat draws under its rows, kept in the workspace so a resumed session draws it again. Claude Code keeps a
// row's uuid across `--continue` and `--resume`, and the drawings stand under rows by that uuid (their `requestId`), but
// the plugin's state lives only as long as its process. So each row's cards, its answer's footer, its `↳ thread` rows
// and its `↳ view` rows are written to `<workspace>/terminal/chat.json` as they are set, and read back into the state
// when the session starts. The file is the renderer's own: browser mode does not read it.
//
// No `$` here: register.tsx reads and writes through the context (hooks/ctx.ts).
import type { ChatSignal, TermAnswer, TermHome } from '../types'
import type { Ctx } from './ctx'

/** What the file is read and written with. */
type Io = Pick<Ctx, 'read' | 'write'>

/** What one row of main's chat carries under it; `writer`, the writer run its `↳ The writer …` line reports (its chat)
 *  and whether it said that run's end first. */
export type KeptRow = { cards?: string[]; answer?: TermAnswer; threads?: ChatSignal[]; views?: string[]; writer?: { chat: string; first: boolean } }

/** The file: each row's drawings by its uuid, oldest first, the last turn's text and cards (`/thimble cite` and
 *  `/thimble card` open them by number), and what the workspace held when home was last seen (`seen`), so the row above
 *  the prompt counts what came after across a relaunch. */
export type Kept = { rows: Record<string, KeptRow>; last: { reply: string; cards: string[] }; seen?: TermHome }

/** The workspace file, under the workspace folder. */
export const KEPT_FILE = 'terminal/chat.json'
/** The rows kept, the newest. */
const ROWS_MAX = 400

export const keptEmpty = (): Kept => ({ rows: {}, last: { reply: '', cards: [] } })

const strings = (v: unknown): string[] => (Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string' && x !== '') : [])

function signalsOf(v: unknown): ChatSignal[] {
  return Array.isArray(v) ? v.filter((s): s is ChatSignal => Boolean(s) && typeof (s as ChatSignal).thread === 'string' && typeof (s as ChatSignal).turn === 'number').map(s => ({ thread: s.thread, turn: s.turn })) : []
}

function answerOf(v: unknown): TermAnswer | undefined {
  const a = v as Partial<TermAnswer> | null | undefined
  if (!a || typeof a !== 'object' || typeof a.text !== 'string') return undefined
  return { rows: strings(a.rows), text: a.text, cards: strings(a.cards) }
}

/** The file's text as Kept: lenient, a part it cannot read is left out. */
export function parseKept(raw: string): Kept {
  let v: unknown
  try {
    v = JSON.parse(raw)
  } catch {
    return keptEmpty()
  }
  const o = (v ?? {}) as { rows?: unknown; last?: { reply?: unknown; cards?: unknown } }
  const rows: Record<string, KeptRow> = {}
  for (const [k, r] of Object.entries(o.rows && typeof o.rows === 'object' ? (o.rows as Record<string, unknown>) : {})) {
    const x = (r ?? {}) as Record<string, unknown>
    const row: KeptRow = {}
    const cards = strings(x.cards)
    const threads = signalsOf(x.threads)
    const views = strings(x.views)
    const answer = answerOf(x.answer)
    const writer = x.writer as { chat?: unknown; first?: unknown } | null | undefined
    if (writer && typeof writer === 'object' && typeof writer.chat === 'string' && writer.chat) row.writer = { chat: writer.chat, first: writer.first === true }
    if (cards.length) row.cards = cards
    if (threads.length) row.threads = threads
    if (views.length) row.views = views
    if (answer) row.answer = answer
    if (Object.keys(row).length) rows[k] = row
  }
  const seen = seenOf((o as { seen?: unknown }).seen)
  return { rows, last: { reply: typeof o.last?.reply === 'string' ? o.last.reply : '', cards: strings(o.last?.cards) }, ...(seen ? { seen } : {}) }
}

function seenOf(v: unknown): TermHome | undefined {
  const o = v as Partial<Record<keyof TermHome, unknown>> | null | undefined
  if (!o || typeof o !== 'object') return undefined
  const n = (x: unknown) => (typeof x === 'number' && Number.isFinite(x) ? x : 0)
  return { cards: n(o.cards), labels: n(o.labels), docs: n(o.docs), threads: n(o.threads), views: n(o.views), files: n(o.files), at: n(o.at) }
}

/** The file's text: the newest ROWS_MAX rows. */
export function keptJson(k: Kept): string {
  const keys = Object.keys(k.rows)
  const rows = Object.fromEntries(keys.slice(Math.max(0, keys.length - ROWS_MAX)).map(key => [key, k.rows[key]!]))
  return JSON.stringify({ rows, last: k.last, ...(k.seen ? { seen: k.seen } : {}) })
}

/** `kept` with one row's part set (a row moves to the end, the newest). */
export function withRow(k: Kept, row: string, part: KeptRow): Kept {
  const rows = { ...k.rows }
  const cur = rows[row] ?? {}
  delete rows[row]
  rows[row] = { ...cur, ...part }
  return { ...k, rows }
}

// what this process holds of the file, and the writes in order
let kept: Kept = keptEmpty()
let writes: Promise<void> = Promise.resolve()

function pathOf(ws: string): string {
  return `${ws.replace(/\/+$/, '')}/${KEPT_FILE}`
}

/** The file as earlier sessions left it, merged under what this process set already (a reload keeps its own). */
export async function loadKept(cx: Io, ws: string): Promise<Kept> {
  const got = parseKept(await cx.read(pathOf(ws)).catch(() => ''))
  const seen = kept.seen ?? got.seen
  kept = { rows: { ...got.rows, ...kept.rows }, last: kept.last.reply || kept.last.cards.length ? kept.last : got.last, ...(seen ? { seen } : {}) }
  return kept
}

/** What the workspace held when home was last seen, kept. */
export async function keepSeen(cx: Io, ws: string, seen: TermHome): Promise<void> {
  const k = kept.seen
  if (k && (Object.keys(seen) as (keyof TermHome)[]).every(x => k[x] === seen[x])) return
  kept = { ...kept, seen }
  await save(cx, ws)
}

/** What the workspace held when home was last seen, as the file read at the session's start (or this process) keeps it. */
export function keptSeen(): TermHome | null {
  return kept.seen ?? null
}

/** One row's part kept, and the file written (one write at a time, in order). */
export async function keepRow(cx: Io, ws: string, row: string, part: KeptRow): Promise<void> {
  if (!row) return
  kept = withRow(kept, row, part)
  await save(cx, ws)
}

/** The last turn's text and cards kept. */
export async function keepLast(cx: Io, ws: string, reply: string, cards: string[]): Promise<void> {
  kept = { ...kept, last: { reply, cards } }
  await save(cx, ws)
}

async function save(cx: Io, ws: string): Promise<void> {
  const text = keptJson(kept)
  writes = writes.then(() => cx.write(pathOf(ws), text)).catch(() => undefined)
  await writes
}

/** For the tests: what this process holds, and a fresh start. */
export function keptNow(): Kept {
  return kept
}
export function resetKept(): void {
  kept = keptEmpty()
  writes = Promise.resolve()
}

files.hooks/lines.tsx:
// Parts of the panel and the chat drawn from styled lines by the Client homeview.tsx (no `$`): the home panel, the
// threads tree, the lists, a link (a citation's title, a record's place, a passage's ↳). A click on a hit runs its
// closure, kept here by the drawing's stamp; a key goes to the drawing's key handler once a click gave it the keyboard.
import type { RenderElement, ResolveInput } from 'claude-code'

import type { Ctx } from './ctx'
import type { Line } from './draw'
import { noControls } from './lib'

/** A region of a part drawn from lines (homeview.tsx) and what a click on it does. */
export type LineHit = { y: number; x0: number; x1: number; row: boolean; run: () => Promise<void> | void }
// what each drawing's hits and keys do, by its stamp; the oldest are let go
const lineStamps = new Map<string, { runs: (() => Promise<void> | void)[]; key?: (k: string) => Promise<void> | void }>()
const lineSeen = new Map<string, number>()

function stampOf(key: string, lines: readonly Line[], hits: readonly LineHit[]): string {
  let h = 0x811c9dc5
  const s = `${key}\u0000${JSON.stringify(lines)}\u0000${hits.map(x => `${x.y},${x.x0},${x.x1},${x.row ? 1 : 0}`).join(';')}`
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 0x01000193)
  return `${key}:${(h >>> 0).toString(36)}`
}

// the key handler of the panel's list drawn last (a part whose key starts `m:`), which the panel's own keys reach too
// while the pane holds the keyboard (panel.tsx listKeysEl): a Client takes keys only once a click gave it them
let listKeys: ((k: string) => Promise<void> | void) | null = null

/** The key handler of a part the panel drew that takes the list's keys without a list of lines (a terminal view,
 *  panel.tsx drawView). */
export function setListKeys(fn: (k: string) => Promise<void> | void): void {
  listKeys = fn
}

/** The key handler of the list the panel drew since the last call, and none from then on. */
export function takeListKeys(): ((k: string) => Promise<void> | void) | null {
  const k = listKeys
  listKeys = null
  return k
}

/** A part drawn from styled lines by the Client homeview.tsx, `cols` wide: a click (left or right) on a hit runs it; its
 *  keys go to `onKey` once a click gave it the keyboard. Its key starts with `m:` when its lines bring the margin. */
export function linesEl(cx: Ctx, e: ResolveInput, key: string, lines: Line[], hits: LineHit[], cols: number, onKey?: (k: string) => Promise<void> | void): RenderElement {
  if (e.surface !== 'terminal' && e.surface !== 'desktop') {
    const { Text } = cx.els(e)
    return <Text key={key}>{lines.map(l => l.map(x => x.s).join('')).join('\n')}</Text>
  }
  const { Client } = cx.els(e)
  if (onKey && key.startsWith('m:')) listKeys = onKey
  const stamp = stampOf(key, lines, hits)
  lineStamps.delete(stamp)
  lineStamps.set(stamp, { runs: hits.map(h => h.run), ...(onKey ? { key: onKey } : {}) })
  for (const k of [...lineStamps.keys()].slice(0, Math.max(0, lineStamps.size - 400))) lineStamps.delete(k)
  const packed = hits.flatMap((h, i) => [h.y, h.x0, h.x1, h.row ? 1 : 0, i])
  // a control character a record's words still hold would make the drawing fail to validate
  const shown = lines.map(l => l.map(x => (noControls(x.s) === x.s ? x : { ...x, s: noControls(x.s) })))
  return <Client key={key} module="./homeview.tsx" width={cols} height={Math.max(1, lines.length)} props={JSON.parse(JSON.stringify({ lines: shown, hits: packed, stamp, cols, ...(onKey ? { keys: true } : {}) })) as never} />
}

/** What homeview.tsx posts for a click on no hit of a list with keys, which gave its Client the keyboard. */
export const CLIENT_CLICK = '\u0000click'
let onClientClick: ((cx: Ctx) => Promise<void>) | null = null

/** What a click on no hit of a list does (term.ts takeKeys: the keys back to the pane). */
export function onListClick(fn: (cx: Ctx) => Promise<void>): void {
  onClientClick = fn
}

/** A post of homeview.tsx: each click and key not seen yet, by the drawing it was made in. */
export async function linesMessage(cx: Ctx, origin: unknown, raw: unknown): Promise<void> {
  if (!Array.isArray(raw) || typeof origin !== 'string') return
  for (const a of raw as { seq?: unknown; i?: unknown; k?: unknown; s?: unknown }[]) {
    if (typeof a?.seq !== 'number' || a.seq <= (lineSeen.get(origin) ?? 0)) continue
    lineSeen.set(origin, a.seq)
    const got = lineStamps.get(String(a.s))
    if (!got) continue
    if (a.k === CLIENT_CLICK) await onClientClick?.(cx)
    else if (typeof a.k === 'string') await got.key?.(a.k)
    else {
      await got.runs[Number(a.i)]?.()
      // a click on a row of a list with keys gave its Client the keyboard too: the keys go back to the pane (live check
      // term-fix8, quirk 2: after a click on a home row x did nothing and the hint said to click the panel)
      if (got.key) await onClientClick?.(cx)
    }
    await cx.bumpPanel()
  }
}

files.hooks/panel.tsx:
// The panel: thimble-term's one pane, drawn by the view `panel` names (hooks/term.ts), on the panel's look in SPEC.md
// ("The visual system": rules 1 to 15, sections 2 and 7). A cell of padding at each side,
// then the 2-cell margin where `❯`, `?` and `↳` hang, then the type area. Every view opens with its title row, the path
// from home with the current step last in the accent colour and bold (`home › Threads`; on home `show all threads` and
// `N new` in green at R), a dim subtitle, a rule; its actions sit at its bottom after a second rule; a dim italic row of
// key hints ends it.
// A right-click does what a click does: there is no menu.
//
//   home      everything the workspace holds (home.ts laid out, homeview.tsx drawn): views, documents, threads, cards by
//             group (the newest open, the others folded), labels, files by folder
//   card      a card in its border, its takeaway; its code (`mode: code`)
//   cite      a citation: its value as a link, its status in plain words, its lines with the value marked, or the card
//             it names in its border with the cited mark lit; red when its place does not hold it
//   ask       the question field of a new side thread about what was asked about
//   threads   the threads as a tree under main, the selected one (`thread`) under the second rule, the ask field
//   label     a label after the browser's label editor: its name, type and scope; its prompt (or pattern or code) to edit;
//             run on a sample or on all; counts, examples and cards folded. labels: every label
//   docs      the documents; doc, one document drawn as main's chat draws a reply, its figures as cards, its comments
//             under the passages they are on (report.ts); its edit as Markdown (`mode: edit`, docedit.tsx)
//   files     the file browser and a file: filesview.tsx, through drawsView
//   agent     one of thimble's agents: what it is doing and its latest steps
//   views     the views, one row each; view, one view as one line (the browser draws views)
import type { BoxProps, ButtonProps, ElementConstructor, MatchedEvent, RenderElement, TextProps } from 'claude-code'

import type { ChatNavStep, ChatThread, TermPanel, TermThread, TermVerdict } from '../types'
import type { ThimbleLabel } from './cell'
import { ACCENT, FRESH, LINK, MARGIN_W, controlsEl, fieldEls, fitHints, fitTo, freshSeg, hasMargin, headerEls, hintLines, hintsEl, lineEl, linkSeg, marginKey, pointed, ruleEl, setHead, spread, subLine, takeHead } from './chrome'
import { chipLook, chipName, citeLabel, plainCites, quoteSpan, quotedWords, wrapAround } from './cite'
import { MAX_BARS, MAX_NODES, MAX_TABLE_ROWS, amount, cardLayout, cut, cutRef, demojibake, labelHead, lineWidth, placeWords, shade, share, shares, turnTimes, valueColour, width, wrapRows } from './draw'
import type { BarRow, CardData, Cell, Item, Layout, Line, Seg } from './draw'
import { fileRef, fileType, filesOf } from './files'
import { citationOf, placeOf, targetLabel } from './gestures'
import type { Gesture, Target } from './gestures'
import { FIRST as HOME_FIRST, HOME_HINTS, groupCards, homeLayout, homePick, homeReduce, labelHue, NAME_WHOLE } from './home'
import type { HomeAct, HomeCardGroup, HomeData, HomeFile, HomeLabel, HomeLayout, HomeOpen, HomeReport, HomeThread, HomeUi, HomeView } from './home'
import { chipLabel, chipWords, cid, clip, cutLine, fmt, itemsRow, labelRef, middleCut, labelState, labelStateWords, noControls, outputLine, quoted, recordFields, reportRef, stoppedTurn, windowAt } from './lib'
import type { Citation } from './lib'
import { linesEl, setListKeys, takeListKeys } from './lines'
import type { LineHit } from './lines'
import { aroundLine, docUnits, docsOf, labelOf, labelsOf, threadOf } from './model'
import type { DocFigure, DocSection } from './model'
import { TITLE_ID, beginEdit, checksOf, commentFacts, commentLines, commentWho, commentsOf, discardEdit, draftEdit, editChanged, editOf, flipResolved, passageWords, pickOf, resolvedShown, saveEdit, setComment, setPick, shownComments, stepPick, unitOf, unitParts } from './report'
import type { DocComment } from './report'
import { focusFromRef } from './anim'
import type { Focus } from './anim'
import { NAV_EMPTY, backTarget, crumbSteps, fitPath, pathWidth, threadBehind, threadOnTrail, threadTitle, threadTree, withBack } from './nav'
import { COLORS, paintLines } from './paint'
