// The panels' chrome, after Claude Code's own panels (its Artifacts and Background panels): a title in the accent
// colour and bold with a dim subtitle under it, tabs with the selected one inverse, a bordered search box, bold section
// headings with a dim count, `❯` and the accent on the selected row, metadata dim against the right edge, and a dim
// italic row of key hints at the end (SPEC.md, "The visual system", rules 5 to 9 and section 7).
//
// Two forms of each part: as styled lines (Line), for the panels a Client draws from lines and hits (home.ts, the
// threads tree, the lists), and as elements, for the panels register.tsx, harness.tsx and reports.tsx draw with Box and
// Text. viewdraw.ts draws a view's header itself, since tools/render_view.mjs runs it under Node, which reads no .tsx.
import type { BoxProps, ButtonProps, ElementConstructor, RenderElement, TextProps } from 'claude-code'

import type { Line, Seg } from './draw'
import { cut, lineWidth, width } from './draw'
import { COLORS } from './paint'

// the theme keys of paint.ts COLORS that the chrome draws with
export const LINK = COLORS.link
export const ACCENT = COLORS.accent
export const FRESH = COLORS.fresh
export const TIP = COLORS.tip
export const CHROME = { link: LINK, accent: ACCENT, fresh: FRESH, tip: TIP } as const

/** The cells a mark hangs in, left of a panel's type area: `❯`, `?`, `↳`, a highlight's `●`. */
export const MARGIN_W = 2

// ------------------------------------------------------------------------------------------------ as lines

const dim = (s: string): Seg => ({ s, fg: COLORS.dim })

/** `left` with `right` set against the right edge at `w`, the left cut first so the right stays whole. */
export function spread(left: Line, right: Line, w: number): Line {
  const rw = lineWidth(right)
  if (!rw) return fitTo(left, w)
  const l = fitTo(left, Math.max(0, w - rw - 2))
  return [...l, { s: ' '.repeat(Math.max(2, w - lineWidth(l) - rw)) }, ...right]
}

/** A line cut to `w` cells, its last segment ending in "…" where cut. */
export function fitTo(l: Line, w: number): Line {
  if (lineWidth(l) <= w) return l
  const out: Line = []
  let left = w
  for (const s of l) {
    if (left <= 0) break
    const sw = width(s.s)
    if (sw <= left) {
      out.push(s)
      left -= sw
    } else {
      out.push({ ...s, s: cut(s.s, left) })
      left = 0
    }
  }
  return out
}

/** A panel's title row: the subject's name in the accent and bold, navigation (`1 file ›`) against the right edge. */
export function titleLine(title: string, w: number, right: Line = []): Line {
  return spread([{ s: title, fg: ACCENT, b: true }], right, w)
}

/** A panel's subtitle: its facts dim, parted by ` · `; a part given as a segment keeps its own colour (a problem's red). */
export function subLine(parts: readonly (string | Seg | null | undefined | false)[]): Line {
  const out: Line = []
  for (const p of parts) {
    if (!p) continue
    if (out.length) out.push(dim(' · '))
    out.push(typeof p === 'string' ? dim(p) : p)
  }
  return out
}

/** A rule across the type area, in the rule grey. */
export function ruleLine(w: number): Line {
  return [{ s: '─'.repeat(Math.max(1, w)), fg: COLORS.rule }]
}

/** A section heading: its name bold, its count dim in parentheses, `N new` in green after it. */
export function headingLine(name: string, count?: number, fresh = 0): Line {
  return [{ s: name, b: true }, ...(count !== undefined ? [dim(` (${count.toLocaleString('en-US')})`)] : []), ...(fresh ? [{ s: '  ' }, { s: `${fresh.toLocaleString('en-US')} new`, fg: FRESH }] : [])]
}

/** Where a key hint stands on its row, the same on every panel: choosing (↑↓), Enter, Space, then the panel's own keys
 *  in the order it gives them, then going back and closing. */
function hintRank(h: string): number {
  return /^↑↓/.test(h) ? 0 : /^Enter\b/.test(h) ? 1 : /^Space\b/.test(h) ? 2 : /^b to go back\b/.test(h) ? 8 : /^x to close\b/.test(h) ? 9 : 5
}

/** The key hints in the order every panel gives them (hintRank). */
export function orderedHints(hints: readonly string[]): string[] {
  return hints.map((h, i) => ({ h, i })).sort((a, b) => hintRank(a.h) - hintRank(b.h) || a.i - b.i).map(x => x.h)
}

/** The key-hint row: the bound keys in Claude Code's words, in one order on every panel, dim and italic, parted by
 *  ` · `. */
export function hintLine(hints: readonly string[], w: number): Line {
  return fitTo([{ s: orderedHints(hints).join(' · '), fg: COLORS.dim, i: true }], w)
}

/** The key hints as rows of `w` cells, whole hints parted by ` · ` on each: a hint row that does not fit goes on to a
 *  second row, never cut (live check term-fix9, quirk 5: `b to go back…` at 210 columns, `Space to fold…` at 120); only
 *  a hint wider than the row alone is cut. */
export function hintLines(hints: readonly string[], w: number): Line[] {
  const rows: string[] = []
  for (const h of orderedHints(hints)) {
    const last = rows.at(-1)
    if (last !== undefined && width(`${last} · ${h}`) <= w) rows[rows.length - 1] = `${last} · ${h}`
    else rows.push(h)
  }
  return (rows.length ? rows : ['']).map(r => fitTo([{ s: r, fg: COLORS.dim, i: true }], w))
}

// what a view's hint row keeps first where it has no room for every hint: ↑↓, Enter, the way back, `?` (every key),
// closing, then the view's own keys
function hintNeed(h: string): number {
  return /^↑↓/.test(h) ? 0 : /^Enter\b/.test(h) ? 1 : /^b to go back\b/.test(h) ? 2 : /^\? /.test(h) ? 3 : /^x to close\b/.test(h) ? 4 : 5
}

/** A view's key hints on one row of `w` cells (docs/terminal-views.md, "Keys"): whole hints, the most needed kept
 *  (hintNeed), in the panel's order; `?` lists the keys the row leaves out. */
export function fitHints(hints: readonly string[], w: number): string[] {
  const order = orderedHints(hints)
  const keep = new Set<number>()
  let used = 0
  for (const { h, i } of order.map((h, i) => ({ h, i })).sort((a, b) => hintNeed(a.h) - hintNeed(b.h) || a.i - b.i)) {
    const add = width(h) + (keep.size ? 3 : 0)
    if (used + add > w) continue
    keep.add(i)
    used += add
  }
  return order.filter((_, i) => keep.has(i))
}

/** `new` in green, the word that follows a new item's name; `N new` after a count. */
export function freshSeg(n?: number): Seg {
  return { s: n === undefined ? 'new' : `${n.toLocaleString('en-US')} new`, fg: FRESH }
}

/** A line with its margin: `❯` in the accent and the line's own words in the accent when `on` (the selected row), else
 *  two spaces. A segment with a colour of its own (a state glyph, a value's hue, a problem, a dim secondary part) keeps
 *  it; `whole` recolours the dim parts too, as a table's selected row is accent across its whole width. */
export function pointed(l: Line, on: boolean, whole = false): Line {
  if (!on) return [{ s: ' '.repeat(MARGIN_W) }, ...l]
  return [{ s: '❯ ', fg: ACCENT }, ...l.map(s => (s.fg === undefined || s.fg === COLORS.text || (whole && s.fg === COLORS.dim) ? { ...s, fg: ACCENT } : s))]
}

/** A line with an empty margin. */
export function margined(l: Line): Line {
  return [{ s: ' '.repeat(MARGIN_W) }, ...l]
}

/** A link: blue and underlined (a citation's value, the place after `↗`, a label's name). */
export function linkSeg(s: string): Seg {
  return { s, fg: LINK, u: true }
}

// ------------------------------------------------------------------------------------------------ as elements

type El = { Box: ElementConstructor<BoxProps>; Text: ElementConstructor<TextProps>; Button: ElementConstructor<ButtonProps> }

/** A styled line as one Text, each segment a nested Text (paint.ts paintLine, wrapped when `wrap`). */
export function lineEl(els: El, l: Line, key?: string, wrap = false): RenderElement {
  const { Text } = els
  const seg = (s: Seg) => {
    const p: TextProps = {}
    if (s.fg) p.color = s.fg
    if (s.bg) p.backgroundColor = s.bg
    if (s.b) p.bold = true
    if (s.d) p.dimColor = true
    if (s.i) p.italic = true
    if (s.u) p.underline = true
    if (s.inv) p.inverse = true
    return Text({ ...p, children: s.s })
  }
  const line = Text({ wrap: wrap ? 'wrap' : 'truncate-end', children: l.length ? l.map(seg) : ' ' })
  return key ? els.Box({ key, flexDirection: 'row', children: [line] }) : line
}

/** What a view's header gives the panel's title row, which is its path (panel.tsx wayRow: `home › threads › "…"`, the
 *  current step last, in the accent and bold): the subject's name as the view names it, or the words it draws in its
 *  place (`line`, a citation's link, `press` what a click on them does, `key` the key of the list that draws them), and
 *  what stands against R (`right`). A view sets it as it draws (headerEls, setHead); the title row takes it once. */
export type Head = { title?: string; line?: Line; press?: () => void; key?: string; right?: RenderElement | null }
let head: Head = {}

export function setHead(h: Head): void {
  head = h
}

/** The head the view drawn last set, once: a view that set none gets the step's own words. */
export function takeHead(): Head {
  const h = head
  head = {}
  return h
}

/** A panel's header under its title row (Matt, 2026-10-07: one row for the path and the title, `home › Threads`): the
 *  dim subtitle when it has facts, then any rows the panel adds (tabs, a search box), then the rule. The title, its
 *  own line and what stands against R go to the title row (setHead). */
export function headerEls(els: El, o: { title: string; cols: number; right?: RenderElement | null; sub?: Line; titleLine?: Line; more?: RenderElement[]; rule?: boolean }): RenderElement[] {
  const { Box, Text } = els
  const out: RenderElement[] = []
  setHead({ title: o.title, ...(o.titleLine ? { line: o.titleLine } : {}), ...(o.right ? { right: o.right } : {}) })
  if (o.sub?.length) out.push(<Box key="h-sub">{lineEl(els, o.sub, undefined, true)}</Box>)
  out.push(...(o.more ?? []))
  if (o.rule !== false) out.push(<Text key="h-rule" color={COLORS.rule}>{'─'.repeat(Math.max(1, o.cols))}</Text>)
  return out
}

/** A rule across the type area. */
export function ruleEl(els: El, cols: number, key: string): RenderElement {
  return els.Box({ key, flexDirection: 'row', children: [els.Text({ color: COLORS.rule, children: '─'.repeat(Math.max(1, cols)) })] })
}

/** The key-hint rows, the panel's last (hintLines). */
export function hintsEl(els: El, hints: readonly string[], cols: number): RenderElement {
  const rows = hintLines(hints, cols)
  if (rows.length === 1) return lineEl(els, rows[0]!, 'h-hints')
  return els.Box({ key: 'h-hints', flexDirection: 'column', children: rows.map((l, i) => lineEl(els, l, `h-hints-${i}`)) })
}

/** Label/value rows and fields (rule 27): each label dim and lower case in a column as wide as the longest label plus
 *  a gutter, its value or field on L. */
export function fieldEls(els: El, rows: readonly [string, RenderElement | string, string?][], keyPrefix = 'f'): RenderElement | null {
  if (!rows.length) return null
  const { Box, Text } = els
  const w = Math.max(...rows.map(([k]) => width(k))) + 2
  return (
    <Box key={`${keyPrefix}-rows`} flexDirection="column">
      {rows.map(([k, v, colour]) => (
        <Box key={`${keyPrefix}:${k}`} flexDirection="row">
          <Box width={w} flexShrink={0}>
            <Text dimColor>{k}</Text>
          </Box>
          <Box flexShrink={1} flexGrow={1}>{typeof v === 'string' ? <Text wrap="wrap" {...(colour ? { color: colour } : {})}>{v}</Text> : v}</Box>
        </Box>
      ))}
    </Box>
  )
}

/** A row of controls at A0, 2 cells apart (rule 25): plain words, inverse under the pointer. */
export function controlsEl(els: El, controls: readonly (RenderElement | null | false)[], key = 'controls'): RenderElement | null {
  const kept = controls.filter((c): c is RenderElement => Boolean(c))
  if (!kept.length) return null
  return els.Box({ key, flexDirection: 'row', columnGap: 2, flexWrap: 'wrap', children: kept })
}

/** A row that brings its own margin (`❯`, a passage's `?` or `↳`): the panel draws it as it is, where every other row
 *  gets an empty margin (register.tsx withWay). */
export function marginKey(key: string): string {
  return key.startsWith('m:') ? key : `m:${key}`
}

export function hasMargin(el: unknown): boolean {
  const k = (el as { key?: unknown; props?: { key?: unknown } } | null)?.props?.key ?? (el as { key?: unknown } | null)?.key
  return typeof k === 'string' && k.startsWith('m:')
}

files.hooks/homeview.tsx:
// A panel drawn from styled lines (the home panel, home.ts; the threads tree and the lists of register.tsx and
// harness.tsx): a Client surface module (no `$`) that draws the lines the hooks module laid out and maps the pointer
// to their hit regions. Rows have no hover state; any other region under the pointer (a heading, a link, "… N more") is
// a control, drawn in inverse. A click (left or right: a right-click does what a click does) posts the hit's index and
// the stamp of the drawing it was in; a key, once a click has given the Client the keyboard, posts the key; the hooks
// module acts on both.
import type { ClientModule } from 'claude-code'

import { lineWidth, width } from './draw'
import type { Line } from './draw'
import { send } from './gestures'
import { paintLine } from './paint'

type Props = { lines: Line[]; hits: number[]; stamp: string; cols: number; keys?: boolean }
type S = { hover: number }
type H = { y: number; x0: number; x1: number; row: boolean; g: number }
type Out = { seq: number; s: string; i?: number; k?: string }
// the key a click on no hit posts (lines.tsx CLIENT_CLICK)
const CLICK = '\u0000click'

// every post carries the clicks and keys not yet seen, under this instance's name, so a reload's count starts afresh
const horigin = Math.random().toString(36).slice(2, 10)
let seq = 0
let outbox: Out[] = []

function unpack(packed: readonly number[] | undefined): H[] {
  const out: H[] = []
  const p = Array.isArray(packed) ? packed : []
  for (let i = 0; i + 4 < p.length; i += 5) out.push({ y: p[i]!, x0: p[i + 1]!, x1: p[i + 2]!, row: p[i + 3] === 1, g: p[i + 4]! })
  return out
}

function inverse(l: Line, x0: number, x1: number): Line {
  const out: Line = []
  let x = 0
  for (const s of l) {
    const parts: [string, string, string] = ['', '', '']
    for (const ch of s.s) {
      parts[x < x0 ? 0 : x < x1 ? 1 : 2] += ch
      x += width(ch)
    }
    if (parts[0]) out.push({ ...s, s: parts[0] })
    if (parts[1]) out.push({ ...s, s: parts[1], inv: true })
    if (parts[2]) out.push({ ...s, s: parts[2] })
  }
  return out
}

function post(surface: unknown, o: Omit<Out, 'seq'>): void {
  outbox = [...outbox, { seq: ++seq, ...o }].slice(-8)
  send(surface, { type: 'home', horigin, hacts: outbox as never })
}

const HomeView: ClientModule<Props, S> = (props, surface) => {
  const { Box, Text } = surface.elements
  const st = surface.state ?? { hover: -1 }
  const hits = unpack(props.hits)
  const at = (x: number, y: number) => hits.findIndex(h => h.y === y && x >= h.x0 && x < h.x1)
  surface.onPointer(ev => {
    if (ev.type === 'down') {
      const i = at(ev.x, ev.y)
      const button = ev.button ?? 'left'
      // a click on no hit of a list with keys gave this Client the keyboard, which the hooks module hands back to the pane,
      // whose own keys reach the list (panel.tsx RELAY)
      if (i < 0 && props.keys && button === 'left' && !ev.shift && !ev.ctrl && !ev.alt) return post(surface, { k: CLICK, s: props.stamp })
      if (i < 0 || button === 'middle' || ev.shift || ev.ctrl || ev.alt) return
      post(surface, { i, s: props.stamp })
      return
    }
    if (ev.type === 'up') return
    const i = ev.type === 'leave' ? -1 : at(ev.x, ev.y)
    if (i !== st.hover) surface.setState({ hover: i })
  })
  if (props.keys) surface.onKey(ev => post(surface, { k: ev.key, s: props.stamp }))
  if (surface.state === undefined) surface.setState(st)
  let lines = props.lines
  const h = st.hover >= 0 ? hits[st.hover] : undefined
  if (h && !h.row) lines = lines.map((l, y) => (y === h.y ? inverse(l, h.x0, h.x1) : l))
  return Box({ flexDirection: 'column', width: props.cols, children: lines.map(l => paintLine(Text, lineWidth(l) ? l : [{ s: ' ' }])) })
}

export default HomeView

files.hooks/files.ts:
// The file browser's pure parts: which refs name a file of the folder and the record they cite, the folder tree and
// its rows, which turns a whole-file JSON transcript's view reads, the modes a file's records read in, the labels that
// are on and the values they gave a file's records, and what a search found. filesview.tsx draws them.
import { classColors } from './labels'
import type { LabelClass } from './labels'

/** The file a ref cites and the record in it: a line (`#L<n>`, a range's first), a JSON list's item (`#/<i>` or
 *  `#/<key>/<i>`, counted from 1 as the file's view counts them), or the whole file. Null for a ref of no file of the
 *  folder: a card, a Bash call's output, a database row, a path outside the folder. */
export function fileRef(ref: string): { path: string; line?: number; item?: number } | null {
  const r = ref.trim().replace(/^\[\[(?:[^|\]]*\|)?/, '').replace(/\]\]$/, '')
  if (!r || /^(card|call|view):/.test(r)) return null
  const hash = r.indexOf('#')
  const path = (hash < 0 ? r : r.slice(0, hash)).replace(/^\.\//, '')
  const frag = hash < 0 ? '' : r.slice(hash + 1)
  if (!path || path.startsWith('/') || path.split('/').includes('..')) return null
  if (!frag) return { path }
  const line = /^L(\d+)(?:-L?\d+)?$/.exec(frag)
  if (line) return { path, line: Number(line[1]) }
  const item = /^\/(?:[^/]+\/)?(\d+)$/.exec(frag)
  if (item) return { path, item: Number(item[1]) + 1 }
  if (/^row=\d+$/.test(frag) || frag.startsWith('/')) return { path }
  // `<db>#<table>/<key>`: a database's row, which the file browser does not open
  return null
}

/** The folder a path stands in, with its slash (`logs/`), '' for the corpus's own files. */
export function dirOf(path: string): string {
  return path.includes('/') ? path.slice(0, path.lastIndexOf('/') + 1) : ''
}

/** Paths in the file browser's order: the corpus's own files first, then each folder in natural order (`run-2` before
 *  `run-10`), each folder's files in natural order. */
export function sortPaths<T extends { path: string }>(files: readonly T[]): T[] {
  const natural = (a: string, b: string) => a.localeCompare(b, undefined, { numeric: true })
  return [...files].sort((a, b) => {
    const da = dirOf(a.path)
    const db = dirOf(b.path)
    return da === db ? natural(a.path, b.path) : !da ? -1 : !db ? 1 : natural(da, db)
  })
}

/** Whether the file browser shows a folder open: the first folder unless folded, any other once unfolded. */
export function folderOpen(ui: { folded: readonly string[]; unfolded: readonly string[] }, dir: string, first: boolean): boolean {
  return first ? !ui.folded.includes(`dir:${dir}`) : ui.unfolded.includes(`dir:${dir}`)
}

/** The row the file browser chooses when the analyst chose none: the first file its tree shows (the first open
 *  folder's), else the first folder's row (`dir:<folder>`); '' for no files (live check term-fix9, quirk 7: no row was
 *  chosen as it opened). */
export function firstChoice(files: readonly { path: string }[], ui: { folded: readonly string[]; unfolded: readonly string[]; whole?: readonly string[] }): string {
  const rows = treeRows(fileTree(files.map(f => ({ path: f.path, kind: '', size: 0 })), ''), ui)
  return rows.find(r => r.file)?.key ?? rows.find(r => r.folder)?.key ?? ''
}

/** Whether a file's page is of a whole-file JSON transcript (thimble's sniff says `json`): a chat export or an agent's
 *  store of messages, whose turns only a parse of the whole file finds (`thimble state turns`), not its lines. */
export function wholeJson(page: Record<string, unknown>): boolean {
  const hint = page.transcript
  return typeof hint === 'object' && hint !== null && (hint as { format?: unknown }).format === 'json' && !page.binary
}

/** The page of turns a file's panel reads of a whole-file JSON transcript: from its turn `from`, else around the
 *  first turn on its `line` (a citation's), else from the first; the surface's key and `thimble state turns`'s
 *  arguments. */
export function turnsRead(p: { path?: string; from?: number; line?: number }): { key: string; args: string[] } {
  const path = p.path ?? ''
  if (p.from !== undefined) return { key: `turns:${path}:${p.from}`, args: [path, '--start', String(p.from)] }
  if (p.line) return { key: `turns:${path}:L${p.line}`, args: [path, '--line', String(p.line)] }
  return { key: `turns:${path}:0`, args: [path] }
}

// ------------------------------------------------------------------------------------------------ the file browser

/** A file as `thimble state files` lists it: its path, thimble's kind, its size in bytes. */
export type FileEntry = { path: string; kind: string; size: number }

type Obj = Record<string, unknown>
const isObj = (v: unknown): v is Obj => Boolean(v) && typeof v === 'object' && !Array.isArray(v)
const str = (v: unknown): string => (typeof v === 'string' ? v : v === null || v === undefined ? '' : String(v))

/** The files a `thimble state files` (or `find`) read gives: a list, or `{files}`. */
export function filesOf(got: { ok: true; value: unknown } | { ok: false; error: string } | undefined): FileEntry[] {
  const list = got?.ok ? (Array.isArray(got.value) ? got.value : isObj(got.value) && Array.isArray(got.value.files) ? got.value.files : []) : []
  return (list as unknown[]).filter(isObj).map(f => ({ path: str(f.path), kind: str(f.kind), size: typeof f.size_bytes === 'number' ? f.size_bytes : typeof f.size === 'number' ? f.size : 0 }))
}

/** What the type column says of a file: thimble's kind for the kinds it reads in its own way (an agent's transcript, a
 *  board, events, a database, a prompt); for a file it knows only as text, what it opens as when that is not its lines
 *  (`transcript`, as its preview and its view say), else its format by its extension (`jsonl`, `md`); never the bare
 *  `text` that a transcript or a table of records would contradict. */
export function fileType(path: string, kind: string, opens = ''): string {
  if (kind && kind !== 'text') return kind === 'forge' ? 'database' : kind
  if (opens) return opens
  const name = path.split('/').at(-1) ?? path
  const dot = name.lastIndexOf('.')
  return dot > 0 && name.length - dot <= 9 ? name.slice(dot + 1).toLowerCase() : 'text'
}

/** A size in bytes as the file browser writes it: `5.4 MB`, `600 B`. */
export function fmtSize(n: number): string {
  return n >= 1e9 ? `${(n / 1e9).toFixed(1)} GB` : n >= 1e6 ? `${(n / 1e6).toFixed(1)} MB` : n >= 1e3 ? `${Math.round(n / 1e3)} KB` : `${n} B`
}

/** Whether a file is a database thimble reads by its tables (backend corpus.source_kind `forge`): `.db`, `.sqlite`,
 *  `.sqlite3`. */
export function isDatabase(path: string, kind = ''): boolean {
  return kind === 'forge' || /\.(db|sqlite3?)$/i.test(path)
}

/** An open folder shows its first FOLDER_FILES files, then `… N more`. */
export const FOLDER_FILES = 20

/** A folder of the file browser's tree: `dir` its path with its slash (`logs/2026/`, '' for the corpus's own files),
 *  `name` as its row names it (a folder within one folder alone, with no files of its own, joins it: `runs/a/`), its
 *  depth, its folders and files, and how many files it holds in all and their size. */
export type Folder = { dir: string; name: string; depth: number; folders: Folder[]; files: FileEntry[]; count: number; size: number }

/** The file browser's tree: the corpus's own files under the corpus folder's name (`rootName`) first, then each folder
 *  of the corpus in natural order; in each folder its folders first, then its files, in natural order, as the browser's
 *  tree lists them. A folder whose one entry is a folder joins it (`runs/a/`), so a deep path takes one row. */
export function fileTree(files: readonly FileEntry[], rootName: string): Folder[] {
  const root: Folder = { dir: '', name: rootName, depth: 0, folders: [], files: [], count: 0, size: 0 }
  const made = new Map<string, Folder>([['', root]])
  const top: Folder[] = []
  const folderOf = (dir: string): Folder => {
    const have = made.get(dir)
    if (have) return have
    const parts = dir.split('/').filter(Boolean)
    const parentDir = parts.length > 1 ? `${parts.slice(0, -1).join('/')}/` : ''
    const f: Folder = { dir, name: parentDir ? `${parts.at(-1)}/` : dir, depth: parts.length - 1, folders: [], files: [], count: 0, size: 0 }
    made.set(dir, f)
    if (parentDir) folderOf(parentDir).folders.push(f)
    else top.push(f)
    return f
  }
  for (const f of sortPaths(files)) {
    const dir = dirOf(f.path)
    folderOf(dir).files.push(f)
    // the count and size of every folder it stands in
    const parts = dir.split('/').filter(Boolean)
    for (let i = 1; i <= parts.length; i++) {
      const at = made.get(`${parts.slice(0, i).join('/')}/`)!
      at.count++
      at.size += f.size
    }
    if (!dir) {
      root.count++
      root.size += f.size
    }
  }
  const natural = (a: Folder, b: Folder) => a.dir.localeCompare(b.dir, undefined, { numeric: true })
  // a folder of one folder and no files joins that folder, its depth kept
  const join = (f: Folder): Folder => {
    while (!f.files.length && f.folders.length === 1) {
      const kid = f.folders[0]!
      f = { ...kid, name: `${f.name}${kid.name}`, depth: f.depth }
    }
    const depth = f.depth
    return { ...f, folders: f.folders.map(k => join({ ...k, depth: depth + 1 })).sort(natural) }
  }
  return [...(root.files.length ? [root] : []), ...top.sort(natural).map(join)]
}

/** A row of the file browser's tree: a folder's (`dir:<folder>`), a file's (its path), or a folder's `… N more`
 *  (`more:<folder>`). */
export type TreeRow = { key: string; depth: number; folder?: Folder; file?: FileEntry; more?: number }

/** The rows the tree shows: each folder, then, while it is open, its folders' rows and its first FOLDER_FILES files
 *  (`… N more`, unless the analyst showed it whole); the first folder open unless folded, any other once unfolded. */
export function treeRows(top: readonly Folder[], ui: { folded: readonly string[]; unfolded: readonly string[]; whole?: readonly string[] }): TreeRow[] {
  const out: TreeRow[] = []
  const walk = (f: Folder, first: boolean) => {
    out.push({ key: `dir:${f.dir}`, depth: f.depth, folder: f })
    if (!folderOpen(ui, f.dir, first)) return
    for (const k of f.folders) walk(k, false)
    const whole = (ui.whole ?? []).includes(f.dir)
    const shown = !whole && f.files.length > FOLDER_FILES + 1 ? f.files.slice(0, FOLDER_FILES) : f.files
    for (const file of shown) out.push({ key: file.path, depth: f.depth + 1, file })
    if (f.files.length > shown.length) out.push({ key: `more:${f.dir}`, depth: f.depth + 1, more: f.files.length - shown.length })
  }
  top.forEach((f, i) => walk(f, i === 0))
  return out
}

/** The folders a path stands in, outermost first (`a/`, `a/b/`), the keys a row's folders are unfolded by. */
export function foldersOf(path: string): string[] {
  const parts = dirOf(path).split('/').filter(Boolean)
  return parts.map((_p, i) => `dir:${parts.slice(0, i + 1).join('/')}/`)
}

/** The file browser's state with every folder `path` stands in open, so its row shows (a file opened from a search, a
 *  citation, or Backspace from its view). */
export function unfoldTo<T extends { folded: string[]; unfolded: string[] }>(ui: T, path: string): T {
  const keys = new Set([`dir:${dirOf(path)}`, ...foldersOf(path)])
  return { ...ui, folded: ui.folded.filter(k => !keys.has(k)), unfolded: [...ui.unfolded.filter(k => !keys.has(k)), ...keys] }
}

// ------------------------------------------------------------------------------------------------ a file's modes

/** The ways a file's records read, as the browser's Files offers them: a table of their keys (records, CSV rows), a
 *  transcript, its text wrapped (Markdown rendered), one record as JSON, the lines as the file holds them. */
export type FileMode = 'table' | 'transcript' | 'text' | 'json' | 'raw'

const isScalar = (v: unknown) => v === null || v === undefined || typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean'

/** How well records read as a table, as the browser's Table view scores them (frontend views/table.tsx tableScore):
 *  every record an object, at most 40 keys, values mostly scalars and no widely shared key mostly holding objects;
 *  uniform records (fill >= 0.7) 0.85, records sharing a spine of keys (fill >= 0.4, two keys in every record) 0.7,
 *  other records of objects 0.05; else 0. */
export function tableScore(sample: readonly unknown[]): number {
  if (!sample.length || !sample.every(isObj)) return 0
  const objs = sample as Obj[]
  const count = new Map<string, number>()
  const nested = new Map<string, number>()
  let present = 0
  let scalars = 0
  for (const o of objs) {
    for (const [k, v] of Object.entries(o)) {
      count.set(k, (count.get(k) ?? 0) + 1)
      present++
      if (isScalar(v)) scalars++
      else if (!Array.isArray(v)) nested.set(k, (nested.get(k) ?? 0) + 1)
    }
  }
  if (!count.size || !present) return 0
  if (count.size > 40 || scalars / present < 0.5) return 0.05
  for (const [k, n] of count) if (n * 2 >= objs.length && (nested.get(k) ?? 0) * 2 >= n) return 0.05
  const fill = present / (objs.length * count.size)
  const shared = [...count.values()].filter(n => n === objs.length).length
  return fill >= 0.7 ? 0.85 : fill >= 0.4 && shared >= 2 ? 0.7 : 0.05
}

/** The separator of a delimited file's cells (`,` for CSV, a tab for TSV), null for any other file. */
export function delimiterOf(path: string): string | null {
  return /\.csv$/i.test(path) ? ',' : /\.tsv$/i.test(path) ? '\t' : null
}

/** A line of a delimited file as its cells: quoted cells keep their separators, `""` is a quotation mark. */
export function csvCells(line: string, sep: string): string[] {
  const out: string[] = []
  let cur = ''
  let quoted = false
  for (let i = 0; i < line.length; i++) {
    const ch = line[i]!
    if (quoted) {
      if (ch === '"' && line[i + 1] === '"') {
        cur += '"'
        i++
      } else if (ch === '"') quoted = false
      else cur += ch
    } else if (ch === '"' && !cur) quoted = true
    else if (ch === sep) {
      out.push(cur)
      cur = ''
    } else cur += ch
  }
  out.push(cur.replace(/\r$/, ''))
  return out
}

/** Whether a file reads as text to wrap first (the browser's Rendered view: a prompt, Markdown, a .txt file). */
export function readsAsText(path: string, kind = ''): boolean {
  return kind === 'prompt' || /\.(md|markdown|txt)$/i.test(path)
}

/** A record's text as JSON when it holds a JSON object or list (a line of a `.json` file), else undefined. */
export function jsonOf(text: string): unknown {
  const t = text.trim()
  if (!/^[[{]/.test(t)) return undefined
  try {
    const v = JSON.parse(t) as unknown
    return typeof v === 'object' && v !== null ? v : undefined
  } catch {
    return undefined
  }
}

// ------------------------------------------------------------------------------------------------ labels on records

/** A label that is on in Files (`shown`, show_label) over a corpus's records or files: its id, name and values, the
 *  values it highlights (litValues), and each value's color from its classes (labels.ts classColors), as the label
 *  panel draws them. */
export type OnLabel = { id: string; name: string; values: string[]; lit: string[]; paths: string[]; glob: string; colors?: Record<string, number> }

// the browser's negatives (frontend files/labels.ts QUIET, isNegative): a quiet word, or the second of two
const QUIET = new Set(['no', 'none', 'other', 'no match', 'not', 'neither', 'n/a', 'unknown'])
const isNegative = (name: string, i: number, n: number): boolean => QUIET.has(name.trim().toLowerCase()) || (n === 2 && i === 1)

/** The values a label highlights, as the browser's Files reads them (frontend files/labels.ts classesOf and litClass):
 *  with classes, those whose class has `highlight` (a class with no `highlight` field highlights nothing; thimble
 *  fills the field for every class it sends); with no classes, every value but the negative. */
export function litValues(values: readonly string[], classes: readonly LabelClass[] | null | undefined): string[] {
  if (Array.isArray(classes) && classes.length) return values.filter(v => classes.some(c => c && c.name === v && Boolean(c.highlight)))
  return values.filter((v, i) => !isNegative(v, i, values.length))
}

/** The labels over files that are on, in the order the labels list gives them. */
export function onLabels(labels: readonly Obj[]): OnLabel[] {
  return labels
    .filter(l => l.shown === true && (!l.unit || ['record', 'agent', 'run'].includes(str(l.unit))))
    .map(l => {
      const run = isObj(l.last_run) ? l.last_run : null
      const classes = l.classes as LabelClass[] | undefined
      const colors = classColors(classes)
      const values = Array.isArray(l.labels) ? (l.labels as unknown[]).map(String) : []
      return { id: str(l.id), name: str(l.name) || str(l.id), values, lit: litValues(values, classes), paths: run && Array.isArray(run.paths) ? (run.paths as unknown[]).map(String) : [], glob: str(l.glob), ...(colors ? { colors } : {}) }
    })
}

/** A glob of a label's scope (comma-separated patterns: `*` within a folder, `**` across folders) as a test of a path. */
export function globTest(glob: string): (path: string) => boolean {
  const res = glob
    .split(',')
    .map(p => p.trim())
    .filter(Boolean)
    .map(p => new RegExp(`^${p.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*\*\/?/g, '\u0000').replace(/\*/g, '[^/]*').replace(/\?/g, '[^/]').replace(/\u0000/g, '.*')}$`))
  return path => res.some(r => r.test(path))
}

/** Whether a label that is on marks a file: its last run read it, or its scope's glob names it. */
export function labelCovers(l: OnLabel, path: string): boolean {
  return l.paths.includes(path) || (Boolean(l.glob) && globTest(l.glob)(path))
}

/** The values the labels that are on gave a file's records (`thimble state marks`: each label's rows on a page of its
 *  lines), by line and then by label, only those the label highlights (litValues), as the browser's Files marks a
 *  record; and those they gave the file whole (a label over files: a row whose ref is the path), by label, highlighted
 *  or not, which the file's label row shows; a value the analyst set stands for the classifier's. */
export function recordMarks(marks: unknown, on: readonly OnLabel[], path: string): { lines: Map<number, Map<string, string>>; file: Map<string, string> } {
  const lines = new Map<number, Map<string, string>>()
  const file = new Map<string, string>()
  const ids = new Set(on.map(l => l.id))
  const lit = new Map(on.map(l => [l.id, new Set(l.lit)]))
  for (const k of Array.isArray(marks) ? marks : []) {
    if (!isObj(k) || !ids.has(str(k.concept_id))) continue
    for (const r of Array.isArray(k.rows) ? k.rows : []) {
      if (!isObj(r)) continue
      const value = str(r.analyst) || str(r.label)
      const ref = str(r.ref)
      if (!value) continue
      if (ref === path) {
        file.set(str(k.concept_id), value)
        continue
      }
      const m = /#L(\d+)/.exec(ref)
      const n = m ? Number(m[1]) : typeof r.line === 'number' ? r.line : 0
      if (!n || !lit.get(str(k.concept_id))?.has(value)) continue
      if (!lines.has(n)) lines.set(n, new Map())
      lines.get(n)!.set(str(k.concept_id), value)
    }
  }
  return { lines, file }
}

// ------------------------------------------------------------------------------------------------ search

/** A file whose text holds the words searched for (`thimble state grep`): how many matches, whether its count is
 *  whole, its first matching lines each with the words around the match and where the match stands in them. */
export type GrepFile = { path: string; total: number; complete: boolean; matches: { line: number; text: string; hit: [number, number] }[] }

/** What `thimble state grep` found: the files, and how many files it read of how many, and whether it read them all. */
export function grepOf(v: unknown): { files: GrepFile[]; scanned: number; of: number; complete: boolean } {
  const o = isObj(v) ? v : {}
  const files = (Array.isArray(o.files) ? o.files : []).filter(isObj).map(f => ({
    path: str(f.path),
    total: typeof f.total === 'number' ? f.total : 0,
    complete: f.complete !== false,
    matches: (Array.isArray(f.matches) ? f.matches : []).filter(isObj).map(m => {
      const hit = Array.isArray(m.hit) && m.hit.length === 2 ? [Number(m.hit[0]) || 0, Number(m.hit[1]) || 0] : [0, 0]
      return { line: typeof m.line === 'number' ? m.line : 1, text: str(m.text), hit: hit as [number, number] }
    }),
  }))
  const d = isObj(o.done) ? o.done : {}
  return { files, scanned: typeof d.scanned === 'number' ? d.scanned : 0, of: typeof d.of === 'number' ? d.of : 0, complete: d.complete !== false }
}

/** The fewest letters the search inside the files starts on, as the browser's (one letter matches nearly every line). */
export const GREP_MIN = 2

files.hooks/report.ts:
// The report in terminal mode: a written document read as Markdown with its cards drawn where it places them, the
// comments on it (a check's, Claude's note from add_comment, the analyst's) at the passages they are on, and the document
// edited as Markdown, saved through the route the browser's editor saves through (PUT …/blocks), so every passage the
// edit kept keeps its id and its comments as the browser keeps them.
//
// Pure, but for the acts at the end (`thimble act comment-resolve | comment-reopen | doc-save`, backend term_report.py).
// panel.tsx draws (drawDoc, drawDocEdit) and docedit.tsx is the editor's field.
import type { Ctx } from './ctx'
import type { Line, Seg } from './draw'
import { width, wrapRows } from './draw'
import { MARGIN_W, pointed, spread } from './chrome'
import { plainCites } from './cite'
import { act, readState } from './data'
import type { Scope } from './data'
import { chipText } from './lib'
import type { DocSection, DocSentence } from './model'
import { docUnits } from './model'
import { COLORS, SERIES } from './paint'

type Obj = Record<string, unknown>
const isObj = (v: unknown): v is Obj => Boolean(v) && typeof v === 'object' && !Array.isArray(v)
const str = (v: unknown): string => (typeof v === 'string' ? v : v === null || v === undefined ? '' : String(v))
const flat = (s: string) => s.replace(/\s+/g, ' ').trim()

/** The title's passage id (backend report_types.TITLE_BLOCK). */
export const TITLE_ID = 'title'
/** The author of a note main left with add_comment (backend comments.py AUTHOR). */
const CLAUDE = 'claude'
/** The check the citation check's unverified tag belongs to. */
const UNVERIFIED = 'unverified'

// ------------------------------------------------------------------------------------------------ comments

/** A report check as `thimble state checks` lists it: its name, its palette place, whether it is on, its runs. */
export type DocCheck = { id: string; name: string; colour: number; shown: boolean; running: string[] }

/** One comment as the document draws it: the passage it is on (`sid`), the check that left it (null for a note), its
 *  name (the check's, `Claude` or `You`), what it is (`check`, `comment`, `citation check`), its words, the refs it
 *  rests on, whether it is open, and whether it is the citation check's tag (nothing to resolve). */
export type DocComment = { id: string; sid: string; check: string | null; name: string; meta: string; text: string; evidence: string[]; open: boolean; tag: boolean; colour: number }

export function checksOf(v: unknown): DocCheck[] {
  return (Array.isArray(v) ? v : []).filter(isObj).map(c => ({
    id: str(c.id),
    name: str(c.name) || str(c.id),
    colour: typeof c.colour === 'number' ? c.colour : 1,
    shown: c.shown === true,
    running: isObj(c.runs) ? Object.entries(c.runs).filter(([, r]) => isObj(r) && r.status === 'running').map(([doc]) => doc) : [],
  }))
}

/** The passages of a document in reading order: the title, then each unit's heading and its sentences. */
export function passageOrder(doc: Obj): string[] {
  const out = [TITLE_ID]
  for (const u of docUnits(doc).units) {
    if (u.id) out.push(u.id)
    for (const p of u.paragraphs ?? []) for (const x of p.sentences ?? []) if (x.id) out.push(x.id)
  }
  return out
}

/** The refs a comment rests on, from its `evidence` (refs parted by spaces), each once. */
export function evidenceRefs(evidence: unknown): string[] {
  const out: string[] = []
  for (const raw of str(evidence).split(/\s+/)) {
    const ref = raw.replace(/^[[(]+|[\]),;:.]+$/g, '')
    if (ref && !out.includes(ref)) out.push(ref)
  }
  return out
}

/** The comments the document shows, in reading order, as the browser's margin shows them (checkComments.ts
 *  openComments, shownComments): the analyst's and Claude's notes always, a check's while the check is on, the citation
 *  check's unverified tag on a sentence its check left no open comment on; and, where the browser shows none, the
 *  resolved ones (`open` false). A comment on a passage the document no longer holds is not shown. */
export function commentsOf(doc: Obj, checks: readonly DocCheck[]): DocComment[] {
  const by = new Map(checks.map(c => [c.id, c]))
  const on = (check: string | null) => check === null || by.get(check)?.shown !== false
  const order = passageOrder(doc)
  const rank = new Map(order.map((id, i) => [id, i]))
  const out: DocComment[] = []
  const marked = new Set<string>()
  for (const cm of Array.isArray(doc.comments) ? doc.comments : []) {
    if (!isObj(cm)) continue
    const sid = str(cm.sentence_id)
    const text = plainCites(str(cm.text)).trim()
    if (!sid || !text || !rank.has(sid)) continue
    const check = cm.check ? str(cm.check) : null
    const open = (str(cm.status) || 'open') === 'open'
    if (check === UNVERIFIED && open) marked.add(sid)
    if (!on(check)) continue
    const name = check !== null ? (by.get(check)?.name ?? check) : str(cm.author) === CLAUDE ? 'Claude' : 'You'
    out.push({ id: str(cm.id), sid, check, name, meta: check !== null ? 'check' : 'comment', text, evidence: evidenceRefs(cm.evidence), open, tag: false, colour: by.get(check ?? '')?.colour ?? 0 })
  }
  if (on(UNVERIFIED) && by.has(UNVERIFIED)) {
    for (const u of docUnits(doc).units)
      for (const p of u.paragraphs ?? [])
        for (const x of (p.sentences ?? []) as (DocSentence & { tags?: unknown; tag_notes?: Record<string, unknown> })[]) {
          if (!x.id || marked.has(x.id) || !Array.isArray(x.tags) || !x.tags.includes(UNVERIFIED)) continue
          const note = str(isObj(x.tag_notes) ? x.tag_notes[UNVERIFIED] : '').trim()
          out.push({ id: `tag:${x.id}`, sid: x.id, check: UNVERIFIED, name: by.get(UNVERIFIED)?.name ?? 'Unverified', meta: 'citation check', text: note || 'Not checked', evidence: [], open: true, tag: true, colour: by.get(UNVERIFIED)?.colour ?? 0 })
        }
  }
  return out.map((c, i) => ({ c, i })).sort((a, b) => rank.get(a.c.sid)! - rank.get(b.c.sid)! || a.i - b.i).map(x => x.c)
}

/** The comments a document draws: every open one, and the resolved ones too when `resolved`. */
export function shownComments(all: readonly DocComment[], resolved: boolean): DocComment[] {
  return all.filter(c => c.open || resolved)
}

/** The unit (its index among the document's units) that holds a passage; -1 for the title or none. */
export function unitOf(doc: Obj, sid: string): number {
  return docUnits(doc).units.findIndex(u => u.id === sid || (u.paragraphs ?? []).some(p => (p.sentences ?? []).some(x => x.id === sid)))
}

/** A comment's hue: its check's place in the palette (the label palette's 1-8 over the seven series hues); a note's
 *  `●` is dim, as the browser draws it grey. */
export function commentHue(c: DocComment): string {
  return c.check === null || !c.colour ? COLORS.dim : SERIES[(c.colour - 1) % SERIES.length]!
}

/** A comment as rows with their margin (SPEC.md, rules 2, 12 and 20): `❯` on the chosen one; at A2 the `●` in its
 *  check's hue and its name (the accent when chosen), what it is dim against R (`check`, `comment`, `citation check`,
 *  then `resolved`); its words under its name at A4, wrapped, dim once resolved; the chosen one's refs as chips under
 *  them. `cols` is the type area's width. Returns the rows and where each chip stands on them. */
export function commentLines(c: DocComment, chosen: boolean, cols: number): { lines: Line[]; chips: { ref: string; x0: number; x1: number; y: number }[] } {
  const dimmed = !c.open
  const name: Seg = { s: c.name, ...(dimmed && !chosen ? { fg: COLORS.dim } : {}) }
  const meta = `${c.meta}${c.open ? '' : ' · resolved'}`
  const head = spread([{ s: '  ' }, { s: '●', fg: dimmed ? COLORS.dim : commentHue(c) }, { s: ' ' }, name], [{ s: meta, fg: COLORS.dim }], cols)
  const lines: Line[] = [pointed(head, chosen)]
  for (const row of wrapRows(c.text, Math.max(10, cols - 4), 12)) lines.push(pointed([{ s: '    ' }, { s: row, ...(dimmed ? { fg: COLORS.dim } : {}) }], false))
  const chips: { ref: string; x0: number; x1: number; y: number }[] = []
  if (chosen && c.evidence.length) {
    const row: Line = [{ s: '    ' }]
    let x = MARGIN_W + 4
    for (const ref of c.evidence.slice(0, 6)) {
      const words = chipText({ raw: `[[${ref}]]`, ref, display: null })
      if (x + width(words) > cols + MARGIN_W) break
      if (row.length > 1) {
        row.push({ s: '  ' })
        x += 2
      }
      row.push({ s: words, fg: COLORS.link })
      chips.push({ ref, x0: x, x1: x + width(words), y: lines.length })
      x += width(words)
    }
    if (chips.length) lines.push(pointed(row, false))
  }
  return { lines, chips }
}

/** What the document's subtitle says of its comments: `N open comments`, `N resolved`; '' with none. */
export function commentFacts(all: readonly DocComment[]): string[] {
  const open = all.filter(c => c.open).length
  const done = all.length - open
  const out: string[] = []
  if (open) out.push(`${open.toLocaleString('en-US')} open ${open === 1 ? 'comment' : 'comments'}`)
  if (done) out.push(`${done.toLocaleString('en-US')} resolved`)
  return out
}

// ------------------------------------------------------------------------------------------------ the document as parts

/** A unit's Markdown in parts: each part ends at a passage that has comments, which stand under it; a unit with none is
 *  one part. Its heading, its paragraphs (a list one item a row), each figure where it stands as its card's line
 *  (`[[card:<id>]]`) with its caption italic under it. */
export function unitParts(s: DocSection, comments: readonly DocComment[] = []): { md: string; after: DocComment[] }[] {
  const figs = s.figures ?? []
  const placed = new Set<number>()
  const parts: { md: string[]; after: DocComment[] }[] = [{ md: [], after: [] }]
  const add = (lines: string[]) => {
    const p = parts.at(-1)!
    p.md.push(...(p.md.length ? [''] : []), ...lines)
  }
  const close = (ids: readonly string[]) => {
    const on = comments.filter(c => ids.includes(c.sid))
    if (!on.length) return
    parts.at(-1)!.after.push(...on)
    parts.push({ md: [], after: [] })
  }
  const figure = (k: number) => {
    const f = figs[k]!
    placed.add(k)
    const cell = str(f.cell).replace(/^(?:card|cell):/, '')
    if (cell) add([`[[card:${cell}]]`, ...(f.caption ? [`*${str(f.caption).replace(/\*/g, '')}*`] : [])])
  }
  // a section with no heading (a report's opening summary) starts with its words: no empty heading line
  if (plainCites(str(s.heading)).trim()) add([`## ${str(s.heading)}`])
  close(s.id ? [s.id] : [])
  for (const para of s.paragraphs ?? []) {
    const ss = para.sentences ?? []
    // sentences with bullets are a list, one item a line: a slide's (docUnits put each bullet before its words) and a
    // report paragraph's (its bullet in `bullet`, not in its words)
    const item = (x: DocSentence) => {
      const t = str(x.text).trim()
      const b = str(x.bullet).trim() || '-'
      return t.startsWith(`${b} `) ? t : `${b} ${t}`
    }
    const words = ss.some(x => x.bullet) ? ss.map(item).join('\n') : ss.map(x => str(x.text)).join(' ')
    if (words.trim()) add([words])
    close(ss.map(x => str(x.id)).filter(Boolean))
    figs.forEach((f, k) => (f.after_paragraph === para.id && !placed.has(k) ? figure(k) : undefined))
  }
  figs.forEach((_f, k) => (!placed.has(k) ? figure(k) : undefined))
  if (parts.length > 1 && !parts.at(-1)!.md.length) parts.pop()
  return parts.map(p => ({ md: p.md.join('\n'), after: p.after }))
}

// ------------------------------------------------------------------------------------------------ editing as Markdown

/** One of the browser editor's blocks (backend report_types.BlockIn), with the id of the unit it was built from; '' for a
 *  new one, which the save gives an id. */
export type DocBlock = { id: string; type: 'heading' | 'paragraph' | 'bullet' | 'figure'; text?: string; level?: number; marker?: '-' | '1.'; cell?: string; caption?: string }

type RawSection = { id?: string; heading?: string; level?: number; paragraphs?: { id?: string; sentences?: (DocSentence & { id?: string })[] }[]; figures?: { id?: string; cell?: string; caption?: string; after_paragraph?: string | null; lead?: boolean }[] }

/** A document's blocks as the browser's editor builds them (frontend/src/report/model.ts blocksFromDoc, backend
 *  editor_blocks): per section its heading, its lead figures, its paragraphs (a block per item for a list) with the
 *  figures after each, then its other figures. */
export function docBlocks(doc: Obj): DocBlock[] {
  const out: DocBlock[] = []
  const figure = (f: NonNullable<RawSection['figures']>[number]): DocBlock => ({ id: str(f.id), type: 'figure', cell: str(f.cell), caption: str(f.caption) })
  for (const sec of (Array.isArray(doc.sections) ? doc.sections : []).filter(isObj) as RawSection[]) {
    if (str(sec.heading).trim()) out.push({ id: str(sec.id), type: 'heading', text: str(sec.heading), level: Math.max(typeof sec.level === 'number' ? sec.level : 2, 2) })
    const figs = (sec.figures ?? []).filter(f => isObj(f))
    const paras = (sec.paragraphs ?? []).filter(p => isObj(p))
    out.push(...figs.filter(f => f.lead).map(figure))
    for (const p of paras) {
      const items = (p.sentences ?? []).filter(x => isObj(x))
      if (items.length && items.every(x => x.bullet)) for (const x of items) out.push({ id: str(x.id), type: 'bullet', text: str(x.text).trim(), marker: x.bullet === '1.' ? '1.' : '-' })
      else out.push({ id: str(p.id), type: 'paragraph', text: items.map(x => str(x.text).trim()).filter(Boolean).join(' ') })
      out.push(...figs.filter(f => str(f.after_paragraph) === str(p.id) && str(p.id)).map(figure))
    }
    const known = new Set(paras.map(p => str(p.id)))
    out.push(...figs.filter(f => !f.lead && !known.has(str(f.after_paragraph))).map(figure))
  }
  return out
}

/** A figure's line: `![caption](card:<id>)`, as write_document's Markdown places a card. */
function figureLine(b: DocBlock): string {
  const id = str(b.cell).replace(/^(?:card|cell):/, '').replace(/#.*$/, '')
  return `![${flat(str(b.caption)).replace(/\]\(/g, '] (')}](card:${id})`
}

/** A document as the Markdown the panel edits: `# title`, then its blocks, a blank line between them and none between
 *  the items of one list; a heading `##` (`###` and deeper for a subheading), a list item `- ` or `1. `, a figure its
 *  card's line `![caption](card:<id>)`. Citations stay as written (`[[4579|card:<id>#pages/TOTAL]]`). */
export function docMarkdown(title: string, blocks: readonly DocBlock[]): string {
  const out: string[] = [`# ${flat(title)}`]
  let prev: DocBlock | null = null
  for (const b of blocks) {
    const line = b.type === 'heading' ? `${'#'.repeat(Math.min(6, Math.max(2, b.level ?? 2)))} ${flat(str(b.text))}` : b.type === 'bullet' ? `${b.marker === '1.' ? '1.' : '-'} ${flat(str(b.text))}` : b.type === 'figure' ? figureLine(b) : flat(str(b.text))
    const sameList = prev?.type === 'bullet' && b.type === 'bullet' && prev.marker === b.marker
    out.push(...(sameList ? [] : ['']), line)
    prev = b
  }
  return `${out.join('\n')}\n`
}

const FIGURE_RE = /^!\[(.*)\]\((?:card|cell):([A-Za-z0-9_-]+)(?:#[^)\s]*)?(?:\s+"[^"]*")?\)$/
const CHIP_FIGURE_RE = /^\[\[(?:card|cell):([A-Za-z0-9_-]+)\]\]$/
const HEADING_RE = /^(#{1,6})\s+(.*)$/
const BULLET_RE = /^\s{0,3}[-*+]\s+(.*)$/
const NUMBER_RE = /^\s{0,3}\d{1,3}[.)]\s+(.*)$/

/** The Markdown the panel edited, as the title (null when its first line names none) and blocks with no ids yet: a
 *  `# ` line first is the title; `##` and deeper a heading (`#` later on is one too); a card's line alone,
 *  `![caption](card:<id>)` or `[[card:<id>]]`, a figure, an italic line right under it its caption; `- `, `* `, `+ ` a
 *  list item, `1. ` a numbered one, an indented line under an item more of its words; other lines a paragraph, a blank
 *  line ending it. */
export function parseMarkdown(text: string): { title: string | null; blocks: DocBlock[] } {
  const lines = text.replace(/\r\n?/g, '\n').split('\n')
  const blocks: DocBlock[] = []
  let title: string | null = null
  let para: string[] = []
  let seen = false
  const flush = () => {
    if (para.length) blocks.push({ id: '', type: 'paragraph', text: flat(para.join(' ')) })
    para = []
  }
  for (const raw of lines) {
    const line = raw.replace(/\s+$/, '')
    if (!line.trim()) {
      flush()
      continue
    }
    const first = !seen
    seen = true
    const h = HEADING_RE.exec(line.trim())
    if (h) {
      flush()
      if (first && h[1] === '#') title = flat(h[2]!)
      else blocks.push({ id: '', type: 'heading', text: flat(h[2]!), level: Math.max(2, h[1]!.length) })
      continue
    }
    const fig = FIGURE_RE.exec(line.trim())
    const chip = CHIP_FIGURE_RE.exec(line.trim())
    if (fig || chip) {
      flush()
      blocks.push({ id: '', type: 'figure', cell: `card:${fig ? fig[2] : chip![1]}`, caption: fig ? flat(fig[1]!) : '' })
      continue
    }
    // a caption written under a card's line, as the viewer draws it
    const last = blocks.at(-1)
    const italic = /^\*([^*].*)\*$|^_([^_].*)_$/.exec(line.trim())
    if (!para.length && last?.type === 'figure' && !last.caption && italic) {
      last.caption = flat(italic[1] ?? italic[2] ?? '')
      continue
    }
    const b = BULLET_RE.exec(line)
    const n = b ? null : NUMBER_RE.exec(line)
    if (b || n) {
      flush()
      blocks.push({ id: '', type: 'bullet', text: flat((b ?? n)![1]!), marker: b ? '-' : '1.' })
      continue
    }
    // an indented line under a list item is more of its words
    if (!para.length && last?.type === 'bullet' && /^\s+\S/.test(raw)) {
      last.text = flat(`${last.text ?? ''} ${line}`)
      continue
    }
    para.push(line.trim())
  }
  flush()
  return { title, blocks }
}

/** What two spellings of a block share, for matching an edited block to the one it was built from. */
function blockKey(b: DocBlock): string {
  if (b.type === 'figure') return `figure|${str(b.cell).replace(/^(?:card|cell):/, '').replace(/#.*$/, '')}|${flat(str(b.caption))}`
  return `${b.type}|${b.type === 'heading' ? (b.level ?? 2) : b.type === 'bullet' ? b.marker : ''}|${flat(str(b.text))}`
}

/** The edited blocks with the ids of the blocks they were built from, as the browser's editor keeps a block's id while
 *  it is edited in place: a block whose words the edit left as they were keeps its id (the longest run of such blocks
 *  in order); between two kept ones, each changed block takes the id of the next unkept block of its type there, in
 *  order; any other block is new (''). The save reconciles them (backend report_types.apply_blocks): a kept paragraph
 *  keeps the sentences whose words stayed, with their comments. */
export function alignBlocks(before: readonly DocBlock[], after: readonly DocBlock[]): DocBlock[] {
  const a = before.map(blockKey)
  const b = after.map(blockKey)
  // the longest common run, by dynamic programming over the two lists' keys
  const n = a.length
  const m = b.length
  const L: number[][] = Array.from({ length: n + 1 }, () => new Array<number>(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) L[i]![j] = a[i] === b[j] ? L[i + 1]![j + 1]! + 1 : Math.max(L[i + 1]![j]!, L[i]![j + 1]!)
  const pairs: [number, number][] = []
  for (let i = 0, j = 0; i < n && j < m; ) {
    if (a[i] === b[j]) {
      pairs.push([i, j])
      i++
      j++
    } else if (L[i + 1]![j]! >= L[i]![j + 1]!) i++
    else j++
  }
  const out = after.map(x => ({ ...x, id: '' }))
  for (const [i, j] of pairs) out[j]!.id = before[i]!.id
  // the gaps between kept blocks: a changed block takes the id of an unkept one of its type, in order
  const bounds: [number, number][] = [[-1, -1], ...pairs, [n, m]]
  for (let k = 0; k + 1 < bounds.length; k++) {
    const [i0, j0] = bounds[k]!
    const [i1, j1] = bounds[k + 1]!
    let from = i0 + 1
    for (let j = j0 + 1; j < j1; j++) {
      for (let i = from; i < i1; i++) {
        if (before[i]!.type !== out[j]!.type || !before[i]!.id) continue
        out[j]!.id = before[i]!.id
        from = i + 1
        break
      }
    }
  }
  // an id is taken once
  const taken = new Set<string>()
  for (const x of out) {
    if (x.id && taken.has(x.id)) x.id = ''
    if (x.id) taken.add(x.id)
  }
  return out
}

// ------------------------------------------------------------------------------------------------ what the panel keeps

// each document's chosen comment, and the documents whose resolved comments show
const picks = new Map<string, string>()
const resolvedOn = new Set<string>()

/** The comment chosen in document `slug` ('' for none). */
export function pickOf(slug: string): string {
  return picks.get(slug) ?? ''
}

export function setPick(slug: string, id: string): void {
  if (id) picks.set(slug, id)
  else picks.delete(slug)
}

/** Whether document `slug` shows its resolved comments too. */
export function resolvedShown(slug: string): boolean {
  return resolvedOn.has(slug)
}

export function flipResolved(slug: string): void {
  if (resolvedOn.has(slug)) resolvedOn.delete(slug)
  else resolvedOn.add(slug)
}

/** The comment `k` places from the chosen one among those shown, the first (or the last, going up) when none is
 *  chosen; the chosen one at either end. */
export function stepPick(shown: readonly DocComment[], chosen: string, k: number): DocComment | undefined {
  if (!shown.length) return undefined
  const at = shown.findIndex(c => c.id === chosen)
  if (at < 0) return k < 0 ? shown.at(-1) : shown[0]
  return shown[Math.max(0, Math.min(shown.length - 1, at + k))]
}

/** The passage a comment is on, in its words: the title, a heading, a sentence. */
export function passageWords(doc: Obj, sid: string): string {
  if (sid === TITLE_ID) return str(doc.title)
  for (const u of docUnits(doc).units) {
    if (u.id === sid) return plainCites(str(u.heading))
    for (const p of u.paragraphs ?? []) for (const x of p.sentences ?? []) if (x.id === sid) return plainCites(str(x.text))
  }
  return ''
}

/** Who left a comment, as a thread asked about it is told (the browser's Margin.tsx Reply). */
export function commentWho(c: DocComment): string {
  return c.check !== null ? `The comment of the check “${c.name}”` : c.name === 'Claude' ? 'Claude’s note' : 'The analyst’s comment'
}

/** A document being edited: the Markdown it was opened with (`base`, which tells a change made meanwhile), the blocks
 *  it was built from, the text as typed, and what the last save said (a refusal, red). `force`: the next save writes
 *  over a change made meanwhile, as the analyst asked. */
export type DocEdit = { slug: string; base: string; blocks: DocBlock[]; title: string; text: string; said: string; force: boolean }

const edits = new Map<string, DocEdit>()

/** The edit of document `slug`, if one is open. */
export function editOf(slug: string): DocEdit | undefined {
  return edits.get(slug)
}

/** An edit of the document as it stands, or the one already open with what was typed in it. */
export function beginEdit(slug: string, doc: Obj): DocEdit {
  const had = edits.get(slug)
  if (had) return had
  const title = str(doc.title)
  const blocks = docBlocks(doc)
  const base = docMarkdown(title, blocks)
  const e: DocEdit = { slug, base, blocks, title, text: base, said: '', force: false }
  edits.set(slug, e)
  return e
}

/** What the analyst typed, kept as they type it. */
export function draftEdit(slug: string, text: string): void {
  const e = edits.get(slug)
  if (e && e.text !== text) edits.set(slug, { ...e, text, said: '', force: false })
}

/** The edit dropped: the document opens as it stands next time. */
export function discardEdit(slug: string): void {
  edits.delete(slug)
}

/** Whether the edit holds words the document does not. */
export function editChanged(e: DocEdit): boolean {
  return e.text.replace(/\s+$/, '') !== e.base.replace(/\s+$/, '')
}

/** The blocks and title a save sends for an edit (alignBlocks): the edited title, else the title as it was. */
export function savedBlocks(e: DocEdit): { title: string; blocks: DocBlock[] } {
  const got = parseMarkdown(e.text)
  return { title: got.title ?? e.title, blocks: alignBlocks(e.blocks, got.blocks) }
}

/** Save an edit through the browser editor's route (`thimble act doc-save`). The document as it stands is read first:
 *  when it changed since the edit began (a writer or main saved it), the save stops and says so, and the next save
 *  writes over it. Returns '' once saved (the edit is closed), else why not. */
export async function saveEdit(cx: Ctx, sc: Scope, slug: string): Promise<string> {
  const e = edits.get(slug)
  if (!e) return 'nothing is being edited'
  if (!editChanged(e)) {
    edits.delete(slug)
    return ''
  }
  const now = await readState<Obj>(cx, sc, 'doc', [slug])
  if (!now.ok) return keep(e, `could not read the document: ${now.error}`)
  if (!e.force && docMarkdown(str(now.value.title), docBlocks(now.value)) !== e.base) {
    edits.set(slug, { ...e, force: true, said: 'the document changed since you began editing it: s again saves yours over it, d discards yours' })
    return edits.get(slug)!.said
  }
  const { title, blocks } = savedBlocks(e)
  const got = await act(cx, sc, 'doc-save', { doc: slug, title, blocks })
  if (!got.ok) return keep(e, `not saved: ${got.error}`)
  edits.delete(slug)
  return ''
}

function keep(e: DocEdit, said: string): string {
  edits.set(e.slug, { ...e, said })
  return said
}

/** A comment resolved (the margin's ✓) or opened again. Returns '' once done, else why not. */
export async function setComment(cx: Ctx, sc: Scope, slug: string, c: DocComment): Promise<string> {
  if (c.tag) return 'the citation check marks this sentence until its citation is fixed'
  const got = await act(cx, sc, c.open ? 'comment-resolve' : 'comment-reopen', { doc: slug, comment: c.id })
  return got.ok ? '' : got.error
}

