// The document's editor (SPEC.md, section 7, "Documents"): a Client surface module (no `$`) that holds a document's
// Markdown in a window `rows` tall over its whole text, moved to keep the cursor in view, `↑ N more` and `↓ N more` dim
// where rows are above or below it. A click puts the cursor (inverse) on the cell clicked and gives it the keyboard:
// typing inserts, Enter breaks the line, Backspace and Delete remove, the arrows, Home, End and the page keys move;
// ctrl+s saves; Esc gives the keys back to the panel. Each change posts the text to the hooks module as a draft, and a
// save posts it to be saved, as `{type: 'doc-edit', slug, text, save}` (register.tsx, report.ts).
import type { ClientModule } from 'claude-code'

import { width } from './draw'
import { fieldRows } from './field'
import { send } from './gestures'

type Props = { slug: string; text: string; cols: number; rows: number }
/** `base`: the text the hooks module drew it with; `text`: what it holds now; `at`: the cursor's index; `top`: the
 *  first row shown; `on`: a click gave it the keyboard. */
type S = { base: string; text: string; at: number; top: number; on: boolean }
type Row = { start: number; end: number }

function rowOf(rows: readonly Row[], at: number): number {
  let r = 0
  rows.forEach((x, k) => {
    if (x.start <= at) r = k
  })
  return r
}

function indexAt(text: string, row: Row, x: number): number {
  let used = 0
  for (let k = row.start; k < row.end; k++) {
    const w = width(text[k]!)
    if (used + w > x) return k
    used += w
  }
  return row.end
}

/** The window over `len` rows that starts at `top` in `room` rows: a row each for `↑ N more` and `↓ N more` where rows
 *  are cut off, and how many of the text's rows show. */
export function editWindow(top: number, len: number, room: number): { up: number; down: number; n: number } {
  if (len <= room) return { up: 0, down: 0, n: len }
  const up = top > 0 ? 1 : 0
  let n = room - up
  const down = top + n < len ? 1 : 0
  n -= down
  return { up, down, n: Math.max(1, n) }
}

/** The first row to show so that row `r` shows, moving the least from `top`; a window that reaches the last row
 *  starts where it shows the most rows. */
export function editTop(top: number, r: number, len: number, room: number): number {
  if (len <= room) return 0
  let t = Math.max(0, Math.min(top, len - 1))
  if (r < t) t = r
  // a window between the first row and the last shows two rows fewer than it has, for `↑ N more` and `↓ N more`
  else if (r >= t + editWindow(t, len, room).n) t = r - Math.max(1, room - 2) + 1
  return Math.max(0, Math.min(t, len - Math.max(1, room - 1)))
}

const SPECIAL = new Set(['up', 'down', 'left', 'right', 'return', 'enter', 'tab', 'backspace', 'delete', 'pageup', 'pagedown', 'home', 'end', 'escape'])

const DocEdit: ClientModule<Props, S> = (props, surface) => {
  const { Box, Text } = surface.elements
  // the width the panel laid it out at, which wraps its rows as the document's Markdown is saved
  const cols = props.cols || surface.columns || 60
  const room = Math.max(3, props.rows || 20)
  const prev = surface.state
  // a new text from the hooks module (the document saved, or discarded) replaces the editor's unless it holds an edit
  let st: S = prev ?? { base: props.text, text: props.text, at: 0, top: 0, on: false }
  if (prev && props.text !== prev.base) st = { ...prev, base: props.text, text: prev.text === prev.base ? props.text : prev.text, at: prev.text === prev.base ? Math.min(prev.at, props.text.length) : prev.at }
  const rows = fieldRows(st.text, cols)
  const put = (next: S, save = false) => {
    const before = (surface.state ?? st).text
    const rs = fieldRows(next.text, cols)
    surface.setState({ ...next, top: editTop(next.top, rowOf(rs, next.at), rs.length, room) })
    if (save || next.text !== before) send(surface, { type: 'doc-edit', slug: props.slug, text: next.text, save })
  }
  const move = (next: S) => {
    const rs = fieldRows(next.text, cols)
    surface.setState({ ...next, top: editTop(next.top, rowOf(rs, next.at), rs.length, room) })
  }
  surface.onPointer(ev => {
    if (ev.type !== 'down') return
    const cur = surface.state ?? st
    const rs = fieldRows(cur.text, cols)
    const w = editWindow(cur.top, rs.length, room)
    const y = ev.y - w.up
    // a click on `↑ N more` or `↓ N more` moves the window a page
    if (y < 0) return move({ ...cur, on: true, at: rs[Math.max(0, cur.top - w.n)]!.start, top: Math.max(0, cur.top - w.n) })
    if (y >= w.n) return move({ ...cur, on: true, at: rs[Math.min(rs.length - 1, cur.top + 2 * w.n - 1)]!.start, top: cur.top + w.n })
    const r = rs[Math.max(0, Math.min(rs.length - 1, cur.top + y))]!
    surface.setState({ ...cur, on: true, at: indexAt(cur.text, r, Math.max(0, ev.x)) })
  })
  surface.onKey(ev => {
    const cur = surface.state ?? st
    const t = cur.text
    const rs = fieldRows(t, cols)
    const r = rowOf(rs, cur.at)
    const k = ev.key
    if (k === 's' && ev.ctrl) return put({ ...cur, on: true }, true)
    if (k === 'escape') return surface.setState({ ...cur, on: false })
    if (k === 'return' || k === 'enter') return put({ ...cur, on: true, text: `${t.slice(0, cur.at)}\n${t.slice(cur.at)}`, at: cur.at + 1 })
    if (k === 'backspace') return cur.at > 0 ? put({ ...cur, on: true, text: t.slice(0, cur.at - 1) + t.slice(cur.at), at: cur.at - 1 }) : undefined
    if (k === 'delete') return cur.at < t.length ? put({ ...cur, on: true, text: t.slice(0, cur.at) + t.slice(cur.at + 1) }) : undefined
    if (k === 'left') return move({ ...cur, on: true, at: Math.max(0, cur.at - 1) })
    if (k === 'right') return move({ ...cur, on: true, at: Math.min(t.length, cur.at + 1) })
    if (k === 'home' || (k === 'a' && ev.ctrl)) return move({ ...cur, on: true, at: rs[r]!.start })
    if (k === 'end' || (k === 'e' && ev.ctrl)) return move({ ...cur, on: true, at: rs[r]!.end })
    if (k === 'up' || k === 'down' || k === 'pageup' || k === 'pagedown') {
      const by = k === 'up' ? -1 : k === 'down' ? 1 : (k === 'pageup' ? -1 : 1) * Math.max(1, editWindow(cur.top, rs.length, room).n - 1)
      const to = rs[r + by]
      if (!to) return move({ ...cur, on: true, at: by < 0 ? 0 : t.length })
      const x = width(t.slice(rs[r]!.start, cur.at))
      return move({ ...cur, on: true, at: indexAt(t, to, x) })
    }
    if (SPECIAL.has(k) || ev.ctrl || ev.meta) return
    // a character typed, or a run of them pasted
    const typed = k === 'space' ? ' ' : k.replace(/\r\n?/g, '\n')
    if (!typed) return
    put({ ...cur, on: true, text: t.slice(0, cur.at) + typed + t.slice(cur.at), at: cur.at + typed.length })
  })
  if (!prev || st !== prev) surface.setState(st)
  const w = editWindow(st.top, rows.length, room)
  const cur = rowOf(rows, st.at)
  const shown = rows.slice(st.top, st.top + w.n)
  const out = []
  if (w.up) out.push(Text({ dimColor: true, children: `↑ ${st.top.toLocaleString('en-US')} more` }))
  shown.forEach((r, k) => {
    const i = st.top + k
    const line = st.text.slice(r.start, r.end)
    if (!st.on || i !== cur) {
      out.push(Text({ wrap: 'truncate-end', children: line || ' ' }))
      return
    }
    const at = st.at - r.start
    const under = st.text[st.at] && st.at < r.end && st.text[st.at] !== '\n' ? st.text[st.at]! : ' '
    out.push(Text({ wrap: 'truncate-end', children: [line.slice(0, at), Text({ inverse: true, children: under }), line.slice(at + (under === ' ' && st.at >= r.end ? 0 : 1))] }))
  })
  const below = rows.length - st.top - w.n
  if (w.down) out.push(Text({ dimColor: true, children: `↓ ${below.toLocaleString('en-US')} more` }))
  return Box({ flexDirection: 'column', width: cols, children: out })
}

export default DocEdit

files.hooks/viewclient.tsx:
// A terminal view's frame (hooks/viewhost.ts), drawn by a Client surface module (no `$`): the rows its program drew
// and its hot regions. A region under the pointer that is not a whole row is drawn in inverse, and its tip (what it
// does, a value's meaning) on the tip background on the row below it, or above it on the last row. A chart's region
// (`cursor`: a strip, a lane) is never inverse, which would turn the chart into a band: only the pointer's column is
// marked, `┊` in an empty cell and a bar in the text color, on every chart region over the same columns (the lanes and
// the range's strip), and the tip is that cell's (`tips`). A press on a region
// posts a click with the cell it landed on, counted from the region's start; on a region the program lets drag, the
// release posts a drag from the cell pressed to the cell let go, or a click when the pointer did not move. A press on
// no region posts a click of none, which gives the pane its keys back (lines.tsx CLIENT_CLICK). Each post carries the
// frame it was made on, so a click lands on what was drawn.
import type { ClientModule } from 'claude-code'

import { width } from './draw'
import type { Line } from './draw'
import { paintLine } from './paint'

type Hit = { y: number; x0: number; x1: number; row?: boolean; tip?: string; drag?: boolean; cursor?: boolean; tips?: string[] }
type Props = { lines: Line[]; hits: Hit[]; seq: number; cols: number }
type S = { hover: number; x?: number; down: { i: number; x: number } | null }
type Out = { n: number; seq: number; i: number; x?: number; x0?: number; x1?: number; drag?: boolean }

const TIP_BG = 'userMessageBackground'
const RULE = 'subtle'
// every post carries the clicks not yet seen, under this instance's name
const vorigin = Math.random().toString(36).slice(2, 10)
let n = 0
let outbox: Out[] = []

type Run = Line[number]
const sameStyle = (a: Run, b: Run) => a.fg === b.fg && a.bg === b.bg && !a.b === !b.b && !a.d === !b.d && !a.i === !b.i && !a.u === !b.u && !a.inv === !b.inv
// a run whose style shows on spaces too: a background, an underline, inverse
const shows = (r: Run) => Boolean(r.bg || r.u || r.inv)

/** A line's runs as few as look the same: spaces take the style of the run beside them where neither's style shows on
 *  a space, and runs of one style are one, so a chart or a row of columns paints as a few Texts rather than one a cell. */
export function fewer(l: Line): Line {
  const out: Line = []
  for (const r of l) {
    const prev = out.at(-1)
    if (prev && !shows(prev) && !shows(r) && (!r.s.trim() || !prev.s.trim() || sameStyle(prev, r))) {
      out[out.length - 1] = !prev.s.trim() && r.s.trim() ? { ...r, s: prev.s + r.s } : { ...prev, s: prev.s + r.s }
    } else if (prev && sameStyle(prev, r)) out[out.length - 1] = { ...prev, s: prev.s + r.s }
    else out.push(r)
  }
  return out
}

/** The cells [x0, x1) of a line in a style over its own: inverse, or the tip's words on the tip background. */
function overlay(l: Line, x0: number, x1: number, f: (s: Line[number]) => Line[number], put?: string): Line {
  const out: Line = []
  let x = 0
  const cells: { ch: string; s: Line[number] }[] = []
  for (const s of l) for (const ch of s.s) cells.push({ ch, s })
  while (width(cells.map(c => c.ch).join('')) < x1) cells.push({ ch: ' ', s: { s: ' ' } })
  let tip = put !== undefined ? [...put] : null
  for (const c of cells) {
    const w = width(c.ch)
    let seg: Line[number] = { ...c.s, s: c.ch }
    if (x >= x0 && x < x1) {
      if (tip) seg = { s: tip.shift() ?? ' ', bg: TIP_BG }
      else seg = f(seg)
    }
    const prev = out.at(-1)
    if (prev && sameStyle(prev, seg)) out[out.length - 1] = { ...prev, s: prev.s + seg.s }
    else out.push(seg)
    x += w
  }
  return out
}

function post(surface: { post: (d: never) => void }, o: Omit<Out, 'n'>): void {
  outbox = [...outbox, { n: ++n, ...o }].slice(-8)
  surface.post({ type: 'view', vorigin, vacts: outbox } as never)
}

const ViewClient: ClientModule<Props, S> = (props, surface) => {
  const { Box } = surface.elements
  const st = surface.state ?? { hover: -1, down: null }
  const hits = Array.isArray(props.hits) ? props.hits : []
  const at = (x: number, y: number) => {
    // a control wins over the row it stands on
    const inside = hits.map((h, i) => ({ h, i })).filter(({ h }) => h.y === y && x >= h.x0 && x < h.x1)
    return (inside.find(({ h }) => !h.row) ?? inside[0])?.i ?? -1
  }
  surface.onPointer(ev => {
    const button = ev.button ?? 'left'
    if (ev.type === 'down') {
      if (button === 'middle' || ev.shift || ev.ctrl || ev.alt) return
      const i = at(ev.x, ev.y)
      if (i < 0) return post(surface, { seq: props.seq, i: -1 })
      const h = hits[i]!
      if (h.drag) return surface.setState({ ...st, down: { i, x: ev.x - h.x0 } })
      return post(surface, { seq: props.seq, i, x: ev.x - h.x0 })
    }
    if (ev.type === 'up') {
      const d = st.down
      if (!d) return
      const h = hits[d.i]
      surface.setState({ ...st, down: null })
      if (!h) return
      const x1 = Math.max(-1, Math.min(h.x1 - h.x0, ev.x - h.x0))
      if (x1 === d.x) post(surface, { seq: props.seq, i: d.i, x: d.x })
      else post(surface, { seq: props.seq, i: d.i, x0: d.x, x1: Math.max(0, Math.min(h.x1 - h.x0 - 1, x1)), drag: true })
      return
    }
    if (st.down) return
    const i = ev.type === 'leave' ? -1 : at(ev.x, ev.y)
    // on a chart's region the pointer's column matters too
    const x = i >= 0 && hits[i]?.cursor ? ev.x : undefined
    if (i !== st.hover || x !== st.x) surface.setState({ ...st, hover: i, x })
  })
  if (surface.state === undefined) surface.setState(st)
  let lines = Array.isArray(props.lines) ? props.lines : []
  const h = st.hover >= 0 ? hits[st.hover] : undefined
  const cx = h?.cursor && typeof st.x === 'number' && st.x >= h.x0 && st.x < h.x1 ? st.x : -1
  if (h && h.cursor && cx >= 0) {
    // the pointer's column on each chart region over the same cells: `┊` where nothing is drawn, a bar in the text color
    const mark = (seg: Line[number]): Line[number] => {
      if (!seg.s.trim()) return { s: '┊', fg: RULE, ...(seg.bg ? { bg: seg.bg } : {}) }
      const { fg: _fg, d: _d, ...rest } = seg
      return rest
    }
    const cols = new Set(hits.filter(g => g.cursor && g.x0 === h.x0 && g.x1 === h.x1).map(g => g.y))
    lines = lines.map((l, y) => (cols.has(y) ? overlay(l, cx, cx + 1, mark) : l))
  } else if (h && !h.row) {
    lines = lines.map((l, y) => (y === h.y ? overlay(l, h.x0, h.x1, s => ({ ...s, inv: true })) : l))
  }
  const tipWords = cx >= 0 ? h?.tips?.[cx - h.x0] || h?.tip : h?.tip
  if (h && tipWords) {
    const ty = h.y + 1 < lines.length ? h.y + 1 : h.y - 1
    if (ty >= 0) {
      const words = ` ${tipWords} `
      const w = Math.min(width(words), props.cols)
      const at0 = cx >= 0 ? Math.max(h.x0, cx - 1) : h.x0
      const x0 = Math.max(0, Math.min(at0, props.cols - w))
      lines = lines.map((l, y) => (y === ty ? overlay(l, x0, x0 + w, s => s, words.slice(0, w)) : l))
    }
  }
  return Box({ flexDirection: 'column', width: props.cols, children: lines.map(l => paintLine(surface.elements.Text, l.length ? fewer(l) : [{ s: ' ' }])) })
}

export default ViewClient

files.hooks/para.tsx:
// A paragraph (or a table) of a reply that holds citations: a Client surface module, drawn on Claude Code's drawing
// thread (no `$`). It wraps the block to its region, draws each citation as a link (cite.ts), ◌ beside a citation a
// fix round or a verification is working on, draws the citation under the pointer in inverse with its tip on a quiet
// box beside it, and hands each press to gestures.tsx with what is under the pointer: a citation, a table row, or the
// sentence of the word there. A right-click does what a click does.
//
// A Client holds the pointer from press to release, so the terminal cannot select its text: the paragraph selects it
// itself. A drag lights the cells it covers and, on release, the text goes to the clipboard (register.tsx copies it);
// a press and release on one cell is a click, acted on at the release. Beside a selection, an "ask about this" Button
// (its press is the person's own, so register.tsx opens a side thread about the selected text at any width).
//
// A hovered citation is lit and tipped only while the pointer moves over it: a press, a move off the region, a
// reflow of the transcript (a pane opening beside it) or a hover in another paragraph clears it, since the engine does
// not always report the pointer leaving.
import type { ClientModule, ClientSurface, RenderElement } from 'claude-code'

import { blockLayout, passageAt } from './cite'
import type { ChipView } from './cite'
import { cut, lineWidth, shade, width } from './draw'
import { onPointer, send } from './gestures'
import type { Target } from './gestures'
import type { Run, TableRuns } from './lib'
import { COLORS, paintLine } from './paint'

type Props = {
  cols: number
  block: { prefix: string; heading: number; quote: boolean; runs: Run[]; table?: TableRuns }
  chips: ChipView[]
  /** each citation's claim key (cite.ts claimKey) */
  ids: string[]
  raws: string[]
}
/** A selection, from the cell pressed to the cell the drag is on (either order). */
type Sel = { y0: number; x0: number; y1: number; x1: number }
/** `cols`: the width the hover and the selection were set at; after a reflow they are stale. */
type S = { hover: number; frame: number; cols: number; sel?: Sel | null }

// a left press not yet released, per instance: where, on what, and whether the pointer has moved off its cell
const pressed = new WeakMap<object, { y: number; x: number; target: Target | null; moved: boolean }>()
// where each instance drew its "ask about this" Button, so a press on it is the Button's, not a new selection
const askAt = new WeakMap<object, { line: number; x0: number; x1: number }>()
const ASK = ' ask '

/** The selection's cells, line by line, in reading order. */
function selCells(sel: Sel, lines: number): { line: number; x0: number; x1: number }[] {
  const [a, b] = sel.y0 < sel.y1 || (sel.y0 === sel.y1 && sel.x0 <= sel.x1) ? [{ y: sel.y0, x: sel.x0 }, { y: sel.y1, x: sel.x1 }] : [{ y: sel.y1, x: sel.x1 }, { y: sel.y0, x: sel.x0 }]
  const out: { line: number; x0: number; x1: number }[] = []
  for (let y = Math.max(0, a.y); y <= Math.min(lines - 1, b.y); y++) out.push({ line: y, x0: y === a.y ? Math.max(0, a.x) : 0, x1: y === b.y ? b.x + 1 : 9999 })
  return out
}

/** The text a selection covers: wrapped lines joined by a space, a table's rows by a newline. */
export function selectedText(lines: readonly { s: string }[][], sel: Sel, table: boolean): string {
  return selCells(sel, lines.length)
    .map(c => Array.from((lines[c.line] ?? []).map(g => g.s).join('')).slice(c.x0, c.x1).join('').trimEnd())
    .join(table ? '\n' : ' ')
    .trim()
}

// the instance whose citation is hovered: one at a time
let hovered: ClientSurface<S> | null = null

function unhover(surface: ClientSurface<S>): void {
  const cur = surface.state
  if (hovered === surface) hovered = null
  if (!cur || cur.hover === -1) return
  try {
    surface.setState({ ...cur, hover: -1 })
    send(surface, { type: 'hover', id: '' })
  } catch {
    // an instance that is gone has nothing to clear
  }
}

const Para: ClientModule<Props, S> = (props, surface) => {
  const { Box, Text, Button } = surface.elements
  const cols = surface.columns || props.cols || 80
  const st = surface.state ?? { hover: -1, frame: 0, cols }
  const hover = st.cols === cols ? st.hover : -1
  const lay = blockLayout(props.block, props.chips, cols, hover, st.frame)

  // set on every call, so the listener reads this call's layout
  surface.onPointer(ev => {
    const cur = surface.state ?? { hover: -1, frame: 0, cols }
    const k = lay.spans.find(s => s.line === ev.y && ev.x >= s.x0 && ev.x < s.x1)?.chip ?? -1
    const targetAt = (x: number, y: number): Target | null => {
      const c = lay.spans.find(s => s.line === y && x >= s.x0 && x < s.x1)?.chip ?? -1
      return c >= 0 ? { kind: 'citation', ref: props.raws[c] ?? '', text: props.chips[c]?.label ?? '', claim: props.ids[c] ?? '' } : passageAt(lay, x, y)
    }
    const mods = { shift: Boolean(ev.shift), ctrl: Boolean(ev.ctrl), alt: Boolean(ev.alt) }
    // a left press starts a click or a selection; the release tells which
    const ask = askAt.get(surface)
    if (ask && ev.y === ask.line && ev.x >= ask.x0 && ev.x < ask.x1 && ev.button === 'left' && (ev.type === 'down' || ev.type === 'up')) return
    if (ev.type === 'down' && ev.button === 'left') {
      unhover(surface)
      pressed.set(surface, { y: ev.y, x: ev.x, target: targetAt(ev.x, ev.y), moved: false })
      if (cur.sel) surface.setState({ ...(surface.state ?? cur), sel: null })
      return
    }
    if (ev.type === 'move' && ev.button === 'left') {
      const p = pressed.get(surface)
      if (!p) return
      if (ev.y !== p.y || ev.x !== p.x) p.moved = true
      if (p.moved) surface.setState({ ...(surface.state ?? cur), cols, hover: -1, sel: { y0: p.y, x0: p.x, y1: Math.max(0, Math.min(lay.lines.length - 1, ev.y)), x1: Math.max(0, ev.x) } })
      return
    }
    if (ev.type === 'up' && ev.button === 'left') {
      const p = pressed.get(surface)
      pressed.delete(surface)
      if (!p) return
      if (!p.moved) {
        if (p.target) onPointer(p.target, { button: 'left', ...mods, type: 'press' }, surface)
        return
      }
      const sel = surface.state?.sel
      const text = sel ? selectedText(lay.lines, sel, Boolean(props.block.table)) : ''
      // one post: a later one in the same frame would replace it; a redraw shows "ask about this" by the selection
      if (text) send(surface, { type: 'copy', text })
      surface.setState({ ...(surface.state ?? cur), sel: text ? sel : null })
      return
    }
    if ((ev.type === 'down' || ev.type === 'up') && ev.button) {
      const target = targetAt(ev.x, ev.y)
      if (target) onPointer(target, { button: ev.button, ...mods, type: ev.type === 'down' ? 'press' : 'release' }, surface)
      if (ev.type === 'down') unhover(surface)
      return
    }
    if (ev.type !== 'move' || ev.x < 0 || ev.y < 0 || ev.x >= cols || ev.y >= lay.lines.length) {
      unhover(surface)
      return
    }
    if (k === cur.hover && cur.cols === cols) return
    if (k < 0) {
      unhover(surface)
      return
    }
    if (hovered && hovered !== surface) unhover(hovered)
    hovered = surface
    surface.setState({ ...cur, hover: k, cols })
    // the band shows the hovered citation's ref and status, whatever room the paragraph has for a tip
    send(surface, { type: 'hover', id: props.ids[k] ?? '' })
  })
  if (surface.state === undefined) surface.setState(st)

  const sel = st.cols === cols ? st.sel : null
  const lit = sel ? shade(lay.lines, selCells(sel, lay.lines.length), COLORS.selected) : lay.lines
  const rows: RenderElement[] = lit.map(l => paintLine(Text, l))
  const span = hover >= 0 ? lay.spans.find(s => s.chip === hover) : undefined
  const tip = hover >= 0 ? props.chips[hover]?.tip : undefined
  // the tip on a quiet box on the row below the citation, or above it on the paragraph's last row; on a one-line
  // paragraph after its text (an absolute Box is clipped to the region, which is one row tall then)
  if (span && tip) {
    const room = Math.max(10, cols - 3)
    let text = cut(tip, room)
    let top = span.line < lay.lines.length - 1 ? span.line + 1 : Math.max(0, span.line - 1)
    let left = Math.max(0, Math.min(span.x0, cols - width(text) - 2))
    if (lay.lines.length === 1) {
      const end = lineWidth(lay.lines[0]!) + 2
      const free = cols - end - 2
      text = free >= 12 ? cut(tip, free) : ''
      left = end
      top = 0
    }
    if (text) rows.push(Box({ position: 'absolute', top, left, children: Text({ backgroundColor: COLORS.tip, children: ` ${text} ` }) }))
  }
  // a released selection: "ask about this" on the line below its end, or at the right of its last line
  askAt.delete(surface)
  if (sel && !pressed.get(surface)) {
    const cells = selCells(sel, lay.lines.length)
    const end = cells.at(-1)
    if (end) {
      const w = width(ASK)
      const below = end.line + 1 < lay.lines.length
      const line = below ? end.line + 1 : end.line
      const x0 = Math.max(0, below ? Math.min(Math.min(end.x1, lineWidth(lay.lines[end.line]!)) - 1, cols - w) : cols - w)
      askAt.set(surface, { line, x0, x1: x0 + w })
      rows.push(Box({ position: 'absolute', top: line, left: x0, children: Button({ key: 'sel-ask', label: ASK, plain: true, variant: 'primary', onPress: () => undefined }) }))
    }
  }
  return Box({ flexDirection: 'column', children: rows })
}

export default Para

